export const VERSES = {"창 12:1":[["창 12:1","여호와께서 아브람에게 이르시되 너는 너의 본토 친척 아비 집을 떠나 내가 네게 지시할 땅으로 가라"]],"출 12:51":[["출 12:51","그 같은 날에 여호와께서 이스라엘 자손을 그 군대대로 애굽 땅에서 인도하여 내셨더라"]],"삼하 5:4-5":[["삼하 5:4","다윗이 삼십세에 위에 나아가서 사십년을 다스렸으되"],["삼하 5:5","헤브론에서 칠년 육개월 동안 유다를 다스렸고 예루살렘에서 삼십 삼년 동안 온 이스라엘과 유다를 다스렸더라"]],"왕하 3:4-5":[["왕하 3:4","모압 왕 메사는 양을 치는 자라 새끼 양 십만의 털과 수양 십만의 털을 이스라엘 왕에게 바치더니"],["왕하 3:5","아합이 죽은 후에 모압 왕이 이스라엘 왕을 배반한지라"]],"왕하 9:6":[["왕하 9:6","예후가 일어나 집으로 들어가니 소년이 그 머리에 기름을 부으며 이르되 이스라엘 하나님 여호와의 말씀이 내가 네게 기름을 부어 여호와의 백성 곧 이스라엘의 왕을 삼노니"]],"왕하 18:13":[["왕하 18:13","히스기야왕 십 사년에 앗수르 왕 산헤립이 올라와서 유다 모든 견고한 성읍들을 쳐서 취하매"]],"왕하 24:15":[["왕하 24:15","저가 여호야긴을 바벨론으로 사로잡아 가고 왕의 모친과 왕의 아내들과 내시와 나라에 권세 있는 자도 예루살렘에서 바벨론으로 사로잡아 가고"]],"스 1:2":[["스 1:2","바사 왕 고레스는 말하노니 하늘의 신 여호와께서 세상 만국으로 내게 주셨고 나를 명하사 유다 예루살렘에 전을 건축하라 하셨나니"]],"사 53:5":[["사 53:5","그가 찔림은 우리의 허물을 인함이요 그가 상함은 우리의 죄악을 인함이라 그가 징계를 받음으로 우리가 평화를 누리고 그가 채찍에 맞음으로 우리가 나음을 입었도다"]],"막 15:15":[["막 15:15","빌라도가 무리에게 만족을 주고자 하여 바라바는 놓아 주고 예수는 채찍질하고 십자가에 못 박히게 넘겨주니라"]],"행 18:12":[["행 18:12","갈리오가 아가야 총독 되었을 때에 유대인이 일제히 일어나 바울을 대적하여 재판 자리로 데리고 와서"]],"창 21:2-3":[["창 21:2","사라가 잉태하고 하나님의 말씀하신 기한에 미쳐 늙은 아브라함에게 아들을 낳으니"],["창 21:3","아브라함이 그 낳은 아들 곧 사라가 자기에게 낳은 아들을 이름하여 이삭이라 하였고"]],"창 19:24-25":[["창 19:24","여호와께서 하늘 곧 여호와에게로서 유황과 불을 비 같이 소돔과 고모라에 내리사"],["창 19:25","그 성들과 온 들과 성에 거하는 모든 백성과 땅에 난 것을 다 엎어 멸하셨더라"]],"창 28:12":[["창 28:12","꿈에 본즉 사닥다리가 땅위에 섰는데 그 꼭대기가 하늘에 닿았고 또 본즉 하나님의 사자가 그 위에서 오르락 내리락하고"]],"창 37:28":[["창 37:28","때에 미디안 사람 상고들이 지나는지라 그들이 요셉을 구덩이에서 끌어올리고 은 이십개에 그를 이스마엘 사람들에게 팔매 그 상고들이 요셉을 데리고 애굽으로 갔더라"]],"창 41:41":[["창 41:41","바로가 또 요셉에게 이르되 내가 너로 애굽 온 땅을 총리하게 하노라 하고"]],"창 46:6":[["창 46:6","그 생축과 가나안 땅에서 얻은 재물을 이끌었으며 야곱과 그 자손들이 다 함께 애굽으로 갔더라"]],"출 2:2-3":[["출 2:2","그 여자가 잉태하여 아들을 낳아 그 준수함을 보고 그를 석달을 숨겼더니"],["출 2:3","더 숨길 수 없이 되매 그를 위하여 갈 상자를 가져다가 역청과 나무 진을 칠하고 아이를 거기 담아 하숫가 갈대 사이에 두고"]],"출 3:10":[["출 3:10","이제 내가 너를 바로에게 보내어 너로 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라"]],"출 20:2-3":[["출 20:2","나는 너를 애굽 땅, 종 되었던 집에서 인도하여 낸 너의 하나님 여호와로라"],["출 20:3","너는 나 외에는 다른 신들을 네게 있게 말찌니라"]],"민 13:27":[["민 13:27","모세에게 보고하여 가로되 당신이 우리를 보낸 땅에 간즉 과연 젖과 꿀이 그 땅에 흐르고 이것은 그 땅의 실과니이다"]],"수 6:20":[["수 6:20","이에 백성은 외치고 제사장들은 나팔을 불매 백성이 나팔 소리를 듣는 동시에 크게 소리질러 외치니 성벽이 무너져 내린지라 백성이 각기 앞으로 나아가 성에 들어가서 그 성을 취하고"]],"삿 4:14":[["삿 4:14","드보라가 바락에게 이르되 일어나라 이는 여호와께서 시스라를 네 손에 붙이신 날이라 여호와께서 너의 앞서 행하지 아니하시느냐 이에 바락이 일만명을 거느리고 다볼산에서 내려가니"]],"삿 7:20":[["삿 7:20","세 대가 나팔을 불며 항아리를 부수고 좌수에 횃불을 들고 우수에 나팔을 들어 불며 외쳐 가로되 여호와와 기드온의 칼이여 하고"]],"룻 1:16":[["룻 1:16","룻이 가로되 나로 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 유숙하시는 곳에서 나도 유숙하겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니"]],"삼상 10:1":[["삼상 10:1","이에 사무엘이 기름병을 취하여 사울의 머리에 붓고 입맞추어 가로되 여호와께서 네게 기름을 부으사 그 기업의 지도자를 삼지 아니하셨느냐"]],"삼상 17:50":[["삼상 17:50","다윗이 이같이 물매와 돌로 블레셋 사람을 이기고 그를 쳐 죽였으나 자기 손에는 칼이 없었더라"]],"삼하 5:7":[["삼하 5:7","다윗이 시온 산성을 빼앗았으니 이는 다윗성이더라"]],"왕상 6:1":[["왕상 6:1","이스라엘 자손이 애굽 땅에서 나온지 사백 팔십년이요 솔로몬이 이스라엘 왕이 된지 사년 시브월 곧 이월에 솔로몬이 여호와를 위하여 전 건축하기를 시작하였더라"]],"왕상 12:19-20":[["왕상 12:19","이에 이스라엘이 다윗의 집을 배반하여 오늘날까지 이르렀더라"],["왕상 12:20","온 이스라엘이 여로보암의 돌아왔다 함을 듣고 보내어 저를 공회로 청하여다가 온 이스라엘의 왕을 삼았으니 유다 지파 외에는 다윗의 집을 좇는 자가 없으니라"]],"왕상 14:25-26":[["왕상 14:25","르호보암왕 제 오년에 애굽 왕 시삭이 올라와서 예루살렘을 치고"],["왕상 14:26","여호와의 전의 보물과 왕궁의 보물을 몰수히 빼앗고 또 솔로몬의 만든 금방패를 다 빼앗은지라"]],"왕상 16:24":[["왕상 16:24","저가 은 두 달란트로 세멜에게서 사마리아산을 사고 그 산 위에 성을 건축하고 그 건축한 성 이름을 그 산 주인이 되었던 세멜의 이름을 좇아 사마리아라 일컬었더라"]],"왕상 18:38-39":[["왕상 18:38","이에 여호와의 불이 내려서 번제물과 나무와 돌과 흙을 태우고 또 도랑의 물을 핥은지라"],["왕상 18:39","모든 백성이 보고 엎드려 말하되 여호와 그는 하나님이시로다 여호와 그는 하나님이시로다 하니"]],"욘 3:4-5":[["욘 3:4","요나가 그 성에 들어가며 곧 하룻길을 행하며 외쳐 가로되 사십일이 지나면 니느웨가 무너지리라 하였더니"],["욘 3:5","니느웨 백성이 하나님을 믿고 금식을 선포하고 무론 대소하고 굵은 베를 입은지라"]],"왕하 17:6":[["왕하 17:6","호세아 구년에 앗수르 왕이 사마리아를 취하고 이스라엘 사람을 사로잡아 앗수르로 끌어다가 할라와 고산 하볼 하숫가와 메대 사람의 여러 고을에 두었더라"]],"왕하 21:2":[["왕하 21:2","므낫세가 여호와 보시기에 악을 행하여 여호와께서 이스라엘 자손 앞에서 쫓아내신 이방 사람의 가증한 일을 본받아서"]],"렘 1:4-5":[["렘 1:4","여호와의 말씀이 내게 임하니라 이르시되"],["렘 1:5","내가 너를 복중에 짓기 전에 너를 알았고 네가 태에서 나오기 전에 너를 구별하였고 너를 열방의 선지자로 세웠노라 하시기로"]],"왕하 22:8":[["왕하 22:8","대제사장 힐기야가 서기관 사반에게 이르되 내가 여호와의 전에서 율법책을 발견하였노라 하고 그 책을 사반에게 주니 사반이 읽으니라"]],"단 1:1":[["단 1:1","유다 왕 여호야김이 위에 있은지 삼년에 바벨론 왕 느부갓네살이 예루살렘에 이르러 그것을 에워쌌더니"]],"왕하 25:9":[["왕하 25:9","여호와의 전과 왕궁을 사르고 예루살렘의 모든 집을 귀인의 집까지 불살랐으며"]],"단 5:30":[["단 5:30","그날 밤에 갈대아왕 벨사살이 죽임을 당하였고"]],"스 6:15":[["스 6:15","다리오왕 육년 아달월 삼일에 전을 필역하니라"]],"에 2:17":[["에 2:17","왕이 모든 여자보다 에스더를 더욱 사랑하므로 저가 모든 처녀보다 왕의 앞에 더욱 은총을 얻은지라 왕이 그 머리에 면류관을 씌우고 와스디를 대신하여 왕후를 삼은 후에"]],"스 7:10":[["스 7:10","에스라가 여호와의 율법을 연구하여 준행하며 율례와 규례를 이스라엘에게 가르치기로 결심하였었더라"]],"느 6:15":[["느 6:15","성 역사가 오십 이일만에 엘룰월 이십 오일에 끝나매"]],"요 10:22":[["요 10:22","예루살렘에 수전절이 이르니 때는 겨울이라"]],"요 2:20":[["요 2:20","유대인들이 가로되 이 성전은 사십 륙년 동안에 지었거늘 네가 삼 일 동안에 일으키겠느뇨 하더라"]],"눅 2:7":[["눅 2:7","맏아들을 낳아 강보로 싸서 구유에 뉘었으니 이는 사관에 있을 곳이 없음이러라"]],"마 3:16-17":[["마 3:16","예수께서 세례를 받으시고 곧 물에서 올라 오실쌔 하늘이 열리고 하나님의 성령이 비둘기 같이 내려 자기 위에 임하심을 보시더니"],["마 3:17","하늘로서 소리가 있어 말씀하시되 이는 내 사랑하는 아들이요 내 기뻐하는 자라 하시니라"]],"막 1:16-17":[["막 1:16","갈릴리 해변으로 지나가시다가 시몬과 그 형제 안드레가 바다에 그물 던지는 것을 보시니 저희는 어부라"],["막 1:17","예수께서 가라사대 나를 따라 오너라 내가 너희로 사람을 낚는 어부가 되게 하리라 하시니"]],"요 12:13":[["요 12:13","종려나무 가지를 가지고 맞으러 나가 외치되 호산나 찬송하리로다 주의 이름으로 오시는이 곧 이스라엘의 왕이시여 하더라"]],"눅 22:19":[["눅 22:19","또 떡을 가져 사례하시고 떼어 저희에게 주시며 가라사대 이것은 너희를 위하여 주는 내 몸이라 너희가 이를 행하여 나를 기념하라 하시고"]],"눅 24:5-6":[["눅 24:5","여자들이 두려워 얼굴을 땅에 대니 두 사람이 이르되 어찌하여 산 자를 죽은 자 가운데서 찾느냐"],["눅 24:6","여기 계시지 않고 살아나셨느니라 갈릴리에 계실 때에 너희에게 어떻게 말씀하신 것을 기억하라"]],"행 2:4":[["행 2:4","저희가 다 성령의 충만함을 받고 성령이 말하게 하심을 따라 다른 방언으로 말하기를 시작하니라"]],"행 7:59-60":[["행 7:59","저희가 돌로 스데반을 치니 스데반이 부르짖어 가로되 주 예수여 내 영혼을 받으시옵소서 하고"],["행 7:60","무릎을 꿇고 크게 불러 가로되 주여 이 죄를 저들에게 돌리지 마옵소서 이 말을 하고 자니라"]],"행 9:3-4":[["행 9:3","사울이 행하여 다메섹에 가까이 가더니 홀연히 하늘로서 빛이 저를 둘러 비추는지라"],["행 9:4","땅에 엎드러져 들으매 소리 있어 가라사대 사울아 사울아 네가 어찌하여 나를 핍박하느냐 하시거늘"]],"행 15:19":[["행 15:19","그러므로 내 의견에는 이방인 중에서 하나님께로 돌아 오는 자들을 괴롭게 말고"]],"행 28:30-31":[["행 28:30","바울이 온 이태를 자기 셋집에 유하며 자기에게 오는 사람을 다 영접하고"],["행 28:31","담대히 하나님 나라를 전파하며 주 예수 그리스도께 관한 것을 가르치되 금하는 사람이 없었더라"]],"눅 21:6":[["눅 21:6","너희 보는 이것들이 날이 이르면 돌 하나도 돌 위에 남지 않고 다 무너뜨리우리라"]],"계 1:9":[["계 1:9","나 요한은 너희 형제요 예수의 환난과 나라와 참음에 동참하는 자라 하나님의 말씀과 예수의 증거를 인하여 밧모라 하는 섬에 있었더니"]],"창 17:5":[["창 17:5","이제 후로는 네 이름을 아브람이라 하지 아니하고 아브라함이라 하리니 이는 내가 너로 열국의 아비가 되게 함이니라"]],"창 11:10-27":[["창 11:10","셈의 후예는 이러하니라 셈은 일백세 곧 홍수 후 이년에 아르박삿을 낳았고"],["창 11:11","아르박삿을 낳은 후에 오백년을 지내며 자녀를 낳았으며"],["창 11:12","아르박삿은 삼십 오세에 셀라를 낳았고"],["창 11:13","셀라를 낳은 후에 사백 삼년을 지내며 자녀를 낳았으며"],["창 11:14","셀라는 삼십세에 에벨을 낳았고"],["창 11:15","에벨을 낳은 후에 사백 삼년을 지내며 자녀를 낳았으며"],["창 11:16","에벨은 삼십 사세에 벨렉을 낳았고"],["창 11:17","벨렉을 낳은 후에 사백 삼십년을 지내며 자녀를 낳았으며"],["창 11:18","벨렉은 삼십세에 르우를 낳았고"],["창 11:19","르우를 낳은 후에 이백 구년을 지내며 자녀를 낳았으며"],["창 11:20","르우는 삼십 이세에 스룩을 낳았고"],["창 11:21","스룩을 낳은 후에 이백 칠년을 지내며 자녀를 낳았으며"],["창 11:22","스룩은 삼십세에 나홀을 낳았고"],["창 11:23","나홀을 낳은 후에 이백년을 지내며 자녀를 낳았으며"],["창 11:24","나홀은 이십 구세에 데라를 낳았고"],["창 11:25","데라를 낳은 후에 일백 십구년을 지내며 자녀를 낳았으며"],["창 11:26","데라는 칠십세에 아브람과 나홀과 하란을 낳았더라"],["창 11:27","데라의 후예는 이러하니라 데라는 아브람과 나홀과 하란을 낳았고 하란은 롯을 낳았으며"]],"창 11:31":[["창 11:31","데라가 그 아들 아브람과 하란의 아들 그 손자 롯과 그 자부 아브람의 아내 사래를 데리고 갈대아 우르에서 떠나 가나안 땅으로 가고자 하더니 하란에 이르러 거기 거하였으며"]],"창 12:4-10":[["창 12:4","이에 아브람이 여호와의 말씀을 좇아 갔고 롯도 그와 함께 갔으며 아브람이 하란을 떠날 때에 그 나이 칠십 오세였더라"],["창 12:5","아브람이 그 아내 사래와 조카 롯과 하란에서 모은 모든 소유와 얻은 사람들을 이끌고 가나안 땅으로 가려고 떠나서 마침내 가나안 땅에 들어 갔더라"],["창 12:6","아브람이 그 땅을 통과하여 세겜 땅 모레 상수리나무에 이르니 그 때에 가나안 사람이 그 땅에 거하였더라"],["창 12:7","여호와께서 아브람에게 나타나 가라사대 내가 이 땅을 네 자손에게 주리라 하신지라 그가 자기에게 나타나신 여호와를 위하여 그곳에 단을 쌓고"],["창 12:8","거기서 벧엘 동편 산으로 옮겨 장막을 치니 서는 벧엘이요 동은 아이라 그가 그곳에서 여호와를 위하여 단을 쌓고 여호와의 이름을 부르더니"],["창 12:9","점점 남방으로 옮겨 갔더라"],["창 12:10","그 땅에 기근이 있으므로 아브람이 애굽에 우거하려 하여 그리로 내려갔으니 이는 그 땅에 기근이 심하였음이라"]],"창 25:7-9":[["창 25:7","아브라함의 향년이 일백 칠십 오세라"],["창 25:8","그가 수가 높고 나이 많아 기운이 진하여 죽어 자기 열조에게로 돌아가매"],["창 25:9","그 아들 이삭과 이스마엘이 그를 마므레 앞 헷 족속 소할의 아들 에브론의 밭에 있는 막벨라 굴에 장사하였으니"]],"창 11:27":[["창 11:27","데라의 후예는 이러하니라 데라는 아브람과 나홀과 하란을 낳았고 하란은 롯을 낳았으며"]],"창 11:29":[["창 11:29","아브람과 나홀이 장가 들었으니 아브람의 아내 이름은 사래며 나홀의 아내 이름은 밀가니 하란의 딸이요 하란은 밀가의 아비며 또 이스가의 아비더라"]],"창 16:3":[["창 16:3","아브람의 아내 사래가 그 여종 애굽 사람 하갈을 가져 그 남편 아브람에게 첩으로 준 때는 아브람이 가나안 땅에 거한지 십년 후이었더라"]],"창 25:1":[["창 25:1","아브라함이 후처를 취하였으니 그 이름은 그두라라"]],"창 12:5":[["창 12:5","아브람이 그 아내 사래와 조카 롯과 하란에서 모은 모든 소유와 얻은 사람들을 이끌고 가나안 땅으로 가려고 떠나서 마침내 가나안 땅에 들어 갔더라"]],"창 16:15-16":[["창 16:15","하갈이 아브람의 아들을 낳으매 아브람이 하갈의 낳은 그 아들을 이름하여 이스마엘이라 하였더라"],["창 16:16","하갈이 아브람에게 이스마엘을 낳을 때에 아브람이 팔십 륙세이었더라"]],"창 21:2-5":[["창 21:2","사라가 잉태하고 하나님의 말씀하신 기한에 미쳐 늙은 아브라함에게 아들을 낳으니"],["창 21:3","아브라함이 그 낳은 아들 곧 사라가 자기에게 낳은 아들을 이름하여 이삭이라 하였고"],["창 21:4","그 아들 이삭이 난지 팔일만에 그가 하나님의 명대로 할례를 행하였더라"],["창 21:5","아브라함이 그 아들 이삭을 낳을 때에 백세라"]],"창 25:2":[["창 25:2","그가 시므란과 욕산과 므단과 미디안과 이스박과 수아를 낳았고"]],"창 25:25-26":[["창 25:25","먼저 나온 자는 붉고 전신이 갖옷 같아서 이름을 에서라 하였고"],["창 25:26","후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라"]],"마 1:2-6":[["마 1:2","아브라함이 이삭을 낳고 이삭은 야곱을 낳고 야곱은 유다와 그의 형제를 낳고"],["마 1:3","유다는 다말에게서 베레스와 세라를 낳고 베레스는 헤스론을 낳고 헤스론은 람을 낳고"],["마 1:4","람은 아미나답을 낳고 아미나답은 나손을 낳고 나손은 살몬을 낳고"],["마 1:5","살몬은 라합에게서 보아스를 낳고 보아스는 룻에게서 오벳을 낳고 오벳은 이새를 낳고"],["마 1:6","이새는 다윗왕을 낳으니라 다윗은 우리야의 아내에게서 솔로몬을 낳고"]],"마 1:1":[["마 1:1","아브라함과 다윗의 자손 예수 그리스도의 세계라"]],"창 11:26-28":[["창 11:26","데라는 칠십세에 아브람과 나홀과 하란을 낳았더라"],["창 11:27","데라의 후예는 이러하니라 데라는 아브람과 나홀과 하란을 낳았고 하란은 롯을 낳았으며"],["창 11:28","하란은 그 아비 데라보다 먼저 본토 갈대아 우르에서 죽었더라"]],"창 12:4-6":[["창 12:4","이에 아브람이 여호와의 말씀을 좇아 갔고 롯도 그와 함께 갔으며 아브람이 하란을 떠날 때에 그 나이 칠십 오세였더라"],["창 12:5","아브람이 그 아내 사래와 조카 롯과 하란에서 모은 모든 소유와 얻은 사람들을 이끌고 가나안 땅으로 가려고 떠나서 마침내 가나안 땅에 들어 갔더라"],["창 12:6","아브람이 그 땅을 통과하여 세겜 땅 모레 상수리나무에 이르니 그 때에 가나안 사람이 그 땅에 거하였더라"]],"창 12:10":[["창 12:10","그 땅에 기근이 있으므로 아브람이 애굽에 우거하려 하여 그리로 내려갔으니 이는 그 땅에 기근이 심하였음이라"]],"창 13:11-18":[["창 13:11","그러므로 롯이 요단 온 들을 택하고 동으로 옮기니 그들이 서로 떠난지라"],["창 13:12","아브람은 가나안 땅에 거하였고 롯은 평지 성읍들에 머무르며 그 장막을 옮겨 소돔까지 이르렀더라"],["창 13:13","소돔 사람은 악하여 여호와 앞에 큰 죄인이었더라"],["창 13:14","롯이 아브람을 떠난 후에 여호와께서 아브람에게 이르시되 너는 눈을 들어 너 있는 곳에서 동서남북을 바라보라"],["창 13:15","보이는 땅을 내가 너와 네 자손에게 주리니 영원히 이르리라"],["창 13:16","내가 네 자손으로 땅의 티끌 같게 하리니 사람이 땅의 티끌을 능히 셀 수 있을찐대 네 자손도 세리라"],["창 13:17","너는 일어나 그 땅을 종과 횡으로 행하여 보라 내가 그것을 네게 주리라"],["창 13:18","이에 아브람이 장막을 옮겨 헤브론에 있는 마므레 상수리 수풀에 이르러 거하며 거기서 여호와를 위하여 단을 쌓았더라"]],"창 15:5-6":[["창 15:5","그를 이끌고 밖으로 나가 가라사대 하늘을 우러러 뭇별을 셀 수 있나 보라 또 그에게 이르시되 네 자손이 이와 같으리라"],["창 15:6","아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고"]],"창 16:16":[["창 16:16","하갈이 아브람에게 이스마엘을 낳을 때에 아브람이 팔십 륙세이었더라"]],"창 17:1-5":[["창 17:1","아브람의 구십 구세 때에 여호와께서 아브람에게 나타나서 그에게 이르시되 나는 전능한 하나님이라 너는 내 앞에서 행하여 완전하라"],["창 17:2","내가 내 언약을 나와 너 사이에 세워 너로 심히 번성케 하리라 하시니"],["창 17:3","아브람이 엎드린대 하나님이 또 그에게 일러 가라사대"],["창 17:4","내가 너와 내 언약을 세우니 너는 열국의 아비가 될찌라"],["창 17:5","이제 후로는 네 이름을 아브람이라 하지 아니하고 아브라함이라 하리니 이는 내가 너로 열국의 아비가 되게 함이니라"]],"창 21:5":[["창 21:5","아브라함이 그 아들 이삭을 낳을 때에 백세라"]],"창 22:1-2":[["창 22:1","그 일 후에 하나님이 아브라함을 시험하시려고 그를 부르시되 아브라함아 하시니 그가 가로되 내가 여기 있나이다"],["창 22:2","여호와께서 가라사대 네 아들 네 사랑하는 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 지시하는 한 산 거기서 그를 번제로 드리라"]],"창 23:2, 19":[["창 23:2","사라가 가나안 땅 헤브론 곧 기럇아르바에서 죽으매 아브라함이 들어가서 사라를 위하여 슬퍼하며 애통하다가"],["창 23:19","그 후에 아브라함이 그 아내 사라를 가나안 땅 마므레 앞 막벨라 밭 굴에 장사하였더라 (마므레는 곧 헤브론이라)"]],"출 2:10":[["출 2:10","그 아이가 자라매 바로의 딸에게로 데려가니 그의 아들이 되니라 그가 그 이름을 모세라 하여 가로되 이는 내가 그를 물에서 건져 내었음이라 하였더라"]],"출 6:16-20":[["출 6:16","레위의 아들들의 이름은 그 연치대로 이러하니 게르손과 고핫과 므라리요 레위의 수는 일백 삼십 칠세이었으며"],["출 6:17","게르손의 아들들은 그 가족대로 립니와 시므이요"],["출 6:18","고핫의 아들들은 아므람과 이스할과 헤브론과 웃시엘이요 고핫의 수는 일백 삼십 삼세이었으며"],["출 6:19","므라리의 아들은 마흘리와 무시니 이들은 그 연치대로 레위의 족장이요"],["출 6:20","아므람이 그 아비의 누이 요게벳을 아내로 취하였고 그가 아론과 모세를 낳았으며 아므람의 수는 일백 삼십 칠세이었으며"]],"출 2:1-2":[["출 2:1","레위 족속중 한 사람이 가서 레위 여자에게 장가 들었더니"],["출 2:2","그 여자가 잉태하여 아들을 낳아 그 준수함을 보고 그를 석달을 숨겼더니"]],"신 34:1-7":[["신 34:1","모세가 모압 평지에서 느보산에 올라 여리고 맞은편 비스가산 꼭대기에 이르매 여호와께서 길르앗 온 땅을 단까지 보이시고"],["신 34:2","또 온 납달리와 에브라임과 므낫세의 땅과 서해까지의 유다 온 땅과"],["신 34:3","남방과 종려의 성읍 여리고 골짜기 평지를 소알까지 보이시고"],["신 34:4","여호와께서 그에게 이르시되 이는 내가 아브라함과 이삭과 야곱에게 맹세하여 그 후손에게 주리라 한 땅이라 내가 네 눈으로 보게 하였거니와 너는 그리로 건너가지 못하리라 하시매"],["신 34:5","이에 여호와의 종 모세가 여호와의 말씀대로 모압 땅에서 죽어"],["신 34:6","벧브올 맞은편 모압 땅에 있는 골짜기에 장사되었고 오늘까지 그 묘를 아는 자 없으니라"],["신 34:7","모세의 죽을 때 나이 일백 이십세나 그 눈이 흐리지 아니하였고 기력이 쇠하지 아니하였더라"]],"출 6:20":[["출 6:20","아므람이 그 아비의 누이 요게벳을 아내로 취하였고 그가 아론과 모세를 낳았으며 아므람의 수는 일백 삼십 칠세이었으며"]],"출 7:7":[["출 7:7","그들이 바로에게 말할 때에 모세는 팔십세이었고 아론은 팔십 삼세이었더라"]],"민 26:59":[["민 26:59","아므람의 처의 이름은 요게벳이니 레위의 딸이요 애굽에서 레위에게서 난 자라 그가 아므람에게서 아론과 모세와 그 누이 미리암을 낳았고"]],"출 2:21":[["출 2:21","모세가 그와 동거하기를 기뻐하매 그가 그 딸 십보라를 모세에게 주었더니"]],"민 12:1":[["민 12:1","모세가 구스 여자를 취하였더니 그 구스 여자를 취하였으므로 미리암과 아론이 모세를 비방하니라"]],"출 3:1":[["출 3:1","모세가 그 장인 미디안 제사장 이드로의 양무리를 치더니 그 무리를 광야 서편으로 인도하여 하나님의 산 호렙에 이르매"]],"출 2:22":[["출 2:22","그가 아들을 낳으매 모세가 그 이름을 게르솜이라 하여 가로되 내가 타국에서 객이 되었음이라 하였더라"]],"출 18:4":[["출 18:4","하나의 이름은 엘리에셀이라 이는 내 아버지의 하나님이 나를 도우사 바로의 칼에서 구원하셨다 함이더라"]],"출 2:1-3":[["출 2:1","레위 족속중 한 사람이 가서 레위 여자에게 장가 들었더니"],["출 2:2","그 여자가 잉태하여 아들을 낳아 그 준수함을 보고 그를 석달을 숨겼더니"],["출 2:3","더 숨길 수 없이 되매 그를 위하여 갈 상자를 가져다가 역청과 나무 진을 칠하고 아이를 거기 담아 하숫가 갈대 사이에 두고"]],"출 2:5-10":[["출 2:5","바로의 딸이 목욕하러 하수로 내려오고 시녀들은 하숫가에 거닐 때에 그가 갈대 사이의 상자를 보고 시녀를 보내어 가져다가"],["출 2:6","열고 그 아이를 보니 아이가 우는지라 그가 불쌍히 여겨 가로되 이는 히브리 사람의 아이로다"],["출 2:7","그 누이가 바로의 딸에게 이르되 내가 가서 히브리 여인 중에서 유모를 불러다가 당신을 위하여 이 아이를 젖 먹이게 하리이까"],["출 2:8","바로의 딸이 그에게 이르되 가라 그 소녀가 가서 아이의 어미를 불러오니"],["출 2:9","바로의 딸이 그에게 이르되 이 아이를 데려다가 나를 위하여 젖을 먹이라 내가 그 삯을 주리라 여인이 아이를 데려다가 젖을 먹이더니"],["출 2:10","그 아이가 자라매 바로의 딸에게로 데려가니 그의 아들이 되니라 그가 그 이름을 모세라 하여 가로되 이는 내가 그를 물에서 건져 내었음이라 하였더라"]],"행 7:23; 출 2:11-15":[["행 7:23","나이 사십이 되매 그 형제 이스라엘 자손을 돌아볼 생각이 나더니"],["출 2:11","모세가 장성한 후에 한번은 자기 형제들에게 나가서 그 고역함을 보더니 어떤 애굽 사람이 어떤 히브리 사람 곧 자기 형제를 치는 것을 본지라"],["출 2:12","좌우로 살펴 사람이 없음을 보고 그 애굽 사람을 쳐죽여 모래에 감추니라"],["출 2:13","이튿날 다시 나가니 두 히브리 사람이 서로 싸우는지라 그 그른 자에게 이르되 네가 어찌하여 동포를 치느냐 하매"],["출 2:14","그가 가로되 누가 너로 우리의 주재와 법관을 삼았느냐 네가 애굽 사람을 죽임 같이 나도 죽이려느냐 모세가 두려워하여 가로되 일이 탄로되었도다"],["출 2:15","바로가 이 일을 듣고 모세를 죽이고자 하여 찾은지라 모세가 바로의 낯을 피하여 미디안 땅에 머물며 하루는 우물 곁에 앉았더라"]],"출 2:21; 3:1":[["출 2:21","모세가 그와 동거하기를 기뻐하매 그가 그 딸 십보라를 모세에게 주었더니"],["출 3:1","모세가 그 장인 미디안 제사장 이드로의 양무리를 치더니 그 무리를 광야 서편으로 인도하여 하나님의 산 호렙에 이르매"]],"출 3:2-10":[["출 3:2","여호와의 사자가 떨기나무 불꽃 가운데서 그에게 나타나시니라 그가 보니 떨기나무에 불이 붙었으나 사라지지 아니하는지라"],["출 3:3","이에 가로되 내가 돌이켜 가서 이 큰 광경을 보리라 떨기나무가 어찌하여 타지 아니하는고 하는 동시에"],["출 3:4","여호와께서 그가 보려고 돌이켜 오는 것을 보신지라 하나님이 떨기나무 가운데서 그를 불러 가라사대 모세야 모세야 하시매 그가 가로되 내가 여기 있나이다"],["출 3:5","하나님이 가라사대 이리로 가까이 하지 말라 너의 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라"],["출 3:6","또 이르시되 나는 네 조상의 하나님이니 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이니라 모세가 하나님 뵈옵기를 두려워하여 얼굴을 가리우매"],["출 3:7","여호와께서 가라사대 내가 애굽에 있는 내 백성의 고통을 정녕히 보고 그들이 그 간역자로 인하여 부르짖음을 듣고 그 우고를 알고"],["출 3:8","내가 내려와서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 이르려 하노라"],["출 3:9","이제 이스라엘 자손의 부르짖음이 내게 달하고 애굽 사람이 그들을 괴롭게 하는 학대도 내가 보았으니"],["출 3:10","이제 내가 너를 바로에게 보내어 너로 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라"]],"출 7:7; 12:51":[["출 7:7","그들이 바로에게 말할 때에 모세는 팔십세이었고 아론은 팔십 삼세이었더라"],["출 12:51","그 같은 날에 여호와께서 이스라엘 자손을 그 군대대로 애굽 땅에서 인도하여 내셨더라"]],"출 14:21-22":[["출 14:21","모세가 바다 위로 손을 내어민대 여호와께서 큰 동풍으로 밤새도록 바닷물을 물러가게 하시니 물이 갈라져 바다가 마른 땅이 된지라"],["출 14:22","이스라엘 자손이 바다 가운데 육지로 행하고 물은 그들의 좌우에 벽이 되니"]],"출 19:20; 20:1-3":[["출 19:20","여호와께서 시내산 곧 그 산꼭대기에 강림하시고 그리로 모세를 부르시니 모세가 올라 가매"],["출 20:1","하나님이 이 모든 말씀으로 일러 가라사대"],["출 20:2","나는 너를 애굽 땅, 종 되었던 집에서 인도하여 낸 너의 하나님 여호와로라"],["출 20:3","너는 나 외에는 다른 신들을 네게 있게 말찌니라"]],"민 20:11-12":[["민 20:11","그 손을 들어 그 지팡이로 반석을 두번 치매 물이 많이 솟아나오므로 회중과 그들의 짐승이 마시니라"],["민 20:12","여호와께서 모세와 아론에게 이르시되 너희가 나를 믿지 아니하고 이스라엘 자손의 목전에 나의 거룩함을 나타내지 아니한고로 너희는 이 총회를 내가 그들에게 준 땅으로 인도하여 들이지 못하리라 하시니라"]],"룻 4:17-22":[["룻 4:17","그 이웃 여인들이 그에게 이름을 주되 나오미가 아들을 낳았다 하여 그 이름을 오벳이라 하였는데 그는 다윗의 아비인 이새의 아비였더라"],["룻 4:18","베레스의 세계는 이러하니라 베레스는 헤스론을 낳았고"],["룻 4:19","헤스론은 람을 낳았고 람은 암미나답을 낳았고"],["룻 4:20","암미나답은 나손을 낳았고 나손은 살몬을 낳았고"],["룻 4:21","살몬은 보아스를 낳았고 보아스는 오벳을 낳았고"],["룻 4:22","오벳은 이새를 낳았고 이새는 다윗을 낳았더라"]],"삼상 17:12":[["삼상 17:12","다윗은 유다 베들레헴 에브랏 사람 이새라 하는 자의 아들이었는데 이새는 사울 당시 사람 중에 나이 많아 늙은 자로서 여덟 아들이 있는 중"]],"왕상 2:10":[["왕상 2:10","다윗이 그 열조와 함께 누워자서 다윗성에 장사되니"]],"룻 4:13, 17":[["룻 4:13","이에 보아스가 룻을 취하여 아내를 삼고 그와 동침하였더니 여호와께서 그로 잉태케 하시므로 그가 아들을 낳은지라"],["룻 4:17","그 이웃 여인들이 그에게 이름을 주되 나오미가 아들을 낳았다 하여 그 이름을 오벳이라 하였는데 그는 다윗의 아비인 이새의 아비였더라"]],"룻 4:22":[["룻 4:22","오벳은 이새를 낳았고 이새는 다윗을 낳았더라"]],"삼상 16:1":[["삼상 16:1","여호와께서 사무엘에게 이르시되 내가 이미 사울을 버려 이스라엘 왕이 되지 못하게 하였거늘 네가 그를 위하여 언제까지 슬퍼하겠느냐 너는 기름을 뿔에 채워가지고 가라 내가 너를 베들레헴 사람 이새에게로 보내리니 이는 내가 그 아들 중에서 한 왕을 예선하였음이니라"]],"삼상 17:13":[["삼상 17:13","그 장성한 세 아들은 사울을 따라 싸움에 나갔으니 싸움에 나간 세 아들의 이름은 장자 엘리압이요 그 다음은 아비나답이요 제 삼은 삼마며"]],"대상 2:16":[["대상 2:16","저희의 자매는 스루야와 아비가일이라 스루야의 아들은 아비새와 요압과 아사헬 삼형제요"]],"삼상 18:27":[["삼상 18:27","다윗이 일어나서 그 종자와 함께 가서 블레셋 사람 이백명을 죽이고 그 양피를 가져다가 수대로 왕께 드려 왕의 사위가 되고자 하니 사울이 그 딸 미갈을 다윗에게 아내로 주었더라"]],"삼상 25:42":[["삼상 25:42","급히 일어나서 나귀를 타고 따르는 처녀 다섯과 함께 다윗의 사자들을 따라가서 다윗의 아내가 되니라"]],"삼하 3:2-5":[["삼하 3:2","다윗이 헤브론에서 아들들을 낳았으되 맏아들은 암논이라 이스르엘 여인 아히노암의 소생이요"],["삼하 3:3","둘째는 길르압이라 갈멜 사람 나발의 아내 되었던 아비가일의 소생이요 세째는 압살롬이라 그술 왕 달매의 딸 마아가의 아들이요"],["삼하 3:4","네째는 아도니야라 학깃의 아들이요 다섯째는 스바댜라 아비달의 아들이요"],["삼하 3:5","여섯째는 이드르암이라 다윗의 아내 에글라의 소생이니 이는 다윗이 헤브론에서 낳은 자들이더라"]],"삼하 11:27":[["삼하 11:27","그 장사를 마치매 다윗이 보내어 저를 궁으로 데려 오니 저가 그 처가 되어 아들을 낳으니라 다윗의 소위가 여호와 보시기에 악하였더라"]],"삼하 3:2-4":[["삼하 3:2","다윗이 헤브론에서 아들들을 낳았으되 맏아들은 암논이라 이스르엘 여인 아히노암의 소생이요"],["삼하 3:3","둘째는 길르압이라 갈멜 사람 나발의 아내 되었던 아비가일의 소생이요 세째는 압살롬이라 그술 왕 달매의 딸 마아가의 아들이요"],["삼하 3:4","네째는 아도니야라 학깃의 아들이요 다섯째는 스바댜라 아비달의 아들이요"]],"삼하 12:24":[["삼하 12:24","다윗이 그 처 밧세바를 위로하고 저에게 들어가 동침하였더니 저가 아들을 낳으매 그 이름을 솔로몬이라 하니라 여호와께서 그를 사랑하사"]],"삼하 5:14":[["삼하 5:14","예루살렘에서 그에게서 난 자의 이름은 삼무아와 소밥과 나단과 솔로몬과"]],"삼하 13:1":[["삼하 13:1","그 후에 이 일이 있으니라 다윗의 아들 압살롬에게 아름다운 누이가 있으니 이름은 다말이라 다윗의 아들 암논이 저를 연애하나"]],"삼하 2:18":[["삼하 2:18","그곳에 스루야의 세 아들 요압과 아비새와 아사헬이 있었는데 아사헬의 발은 들노루 같이 빠르더라"]],"마 1:9":[["마 1:9","웃시야는 요담을 낳고 요담은 아하스를 낳고 아하스는 히스기야를 낳고"]],"마 1:11":[["마 1:11","바벨론으로 이거할 때에 요시야는 여고냐와 그의 형제를 낳으니라"]],"삼상 17:12, 14":[["삼상 17:12","다윗은 유다 베들레헴 에브랏 사람 이새라 하는 자의 아들이었는데 이새는 사울 당시 사람 중에 나이 많아 늙은 자로서 여덟 아들이 있는 중"],["삼상 17:14","다윗은 말째라 장성한 삼인은 사울을 좇았고"]],"삼상 16:11-13":[["삼상 16:11","또 이새에게 이르되 네 아들들이 다 여기 있느냐 이새가 가로되 아직 말째가 남았는데 그가 양을 지키나이다 사무엘이 이새에게 이르되 보내어 그를 데려오라 그가 여기 오기까지는 우리가 식사 자리에 앉지 아니하겠노라"],["삼상 16:12","이에 보내어 그를 데려오매 그의 빛이 붉고 눈이 빼어나고 얼굴이 아름답더라 여호와께서 가라사대 이가 그니 일어나 기름을 부으라"],["삼상 16:13","사무엘이 기름 뿔을 취하여 그 형제 중에서 그에게 부었더니 이 날 이후로 다윗이 여호와의 신에게 크게 감동되니라 사무엘이 떠나서 라마로 가니라"]],"삼상 16:23":[["삼상 16:23","하나님의 부리신 악신이 사울에게 이를 때에 다윗이 수금을 취하여 손으로 탄즉 사울이 상쾌하여 낫고 악신은 그에게서 떠나더라"]],"삼상 17:49-50":[["삼상 17:49","손을 주머니에 넣어 돌을 취하여 물매로 던져 블레셋 사람의 이마를 치매 돌이 그 이마에 박히니 땅에 엎드러지니라"],["삼상 17:50","다윗이 이같이 물매와 돌로 블레셋 사람을 이기고 그를 쳐 죽였으나 자기 손에는 칼이 없었더라"]],"삼상 19:10":[["삼상 19:10","사울이 단창으로 다윗을 벽에 박으려 하였으나 그는 사울의 앞을 피하고 사울의 창은 벽에 박힌지라 다윗이 그 밤에 도피하매"]],"삼하 2:4; 5:4":[["삼하 2:4","유다 사람들이 와서 거기서 다윗에게 기름을 부어 유다 족속의 왕을 삼았더라 혹이 다윗에게 고하여 가로되 사울을 장사한 사람은 길르앗 야베스 사람들이니이다 하매"],["삼하 5:4","다윗이 삼십세에 위에 나아가서 사십년을 다스렸으되"]],"삼하 5:3, 6-9":[["삼하 5:3","이에 이스라엘 모든 장로가 헤브론에 이르러 왕에게 나아오매 다윗왕이 헤브론에서 여호와 앞에서 저희와 언약을 세우매 저희가 다윗에게 기름을 부어 이스라엘 왕을 삼으니라"],["삼하 5:6","왕과 그 종자들이 예루살렘으로 가서 그 땅 거민 여부스 사람을 치려 하매 그 사람들이 다윗에게 말하여 가로되 네가 이리로 들어오지 못하리라 소경과 절뚝발이라도 너를 물리치리라 하니 저희 생각에는 다윗이 이리로 들어오지 못하리라 함이나"],["삼하 5:7","다윗이 시온 산성을 빼앗았으니 이는 다윗성이더라"],["삼하 5:8","그 날에 다윗이 이르기를 누구든지 여부스 사람을 치거든 수구로 올라가서 다윗의 마음에 미워하는 절뚝발이와 소경을 치라 하였으므로 속담이 되어 이르기를 소경과 절뚝발이는 집에 들어 오지 못하리라 하더라"],["삼하 5:9","다윗이 그 산성에 거하여 다윗성이라 이름하고 밀로에서부터 안으로 성을 둘러 쌓으니라"]],"삼하 6:14-15":[["삼하 6:14","여호와 앞에서 힘을 다하여 춤을 추는데 때에 베 에봇을 입었더라"],["삼하 6:15","다윗과 온 이스라엘 족속이 즐거이 부르며 나팔을 불고 여호와의 궤를 메어 오니라"]],"삼하 7:16":[["삼하 7:16","네 집과 네 나라가 내 앞에서 영원히 보전되고 네 위가 영원히 견고하리라 하셨다 하라"]],"삼하 11:27; 12:7-13":[["삼하 11:27","그 장사를 마치매 다윗이 보내어 저를 궁으로 데려 오니 저가 그 처가 되어 아들을 낳으니라 다윗의 소위가 여호와 보시기에 악하였더라"],["삼하 12:7","나단이 다윗에게 이르되 당신이 그 사람이라 이스라엘의 하나님 여호와께서 이처럼 이르시기를 내가 너로 이스라엘 왕을 삼기 위하여 네게 기름을 붓고 너를 사울의 손에서 구원하고"],["삼하 12:8","네 주인의 집을 네게 주고 네 주인의 처들을 네 품에 두고 이스라엘과 유다 족속을 네게 맡겼느니라 만일 그것이 부족하였을것 같으면 내가 네게 이것 저것을 더 주었으리라"],["삼하 12:9","그러한데 어찌하여 네가 여호와의 말씀을 업신여기고 나 보기에 악을 행하였느뇨 네가 칼로 헷 사람 우리아를 죽이되 암몬 자손의 칼로 죽이고 그 처를 빼앗아 네 처를 삼았도다"],["삼하 12:10","이제 네가 나를 업신여기고 헷 사람 우리아의 처를 빼앗아 네 처를 삼았은즉 칼이 네 집에 영영히 떠나지 아니하리라 하셨고"],["삼하 12:11","여호와께서 또 이처럼 이르시기를 내가 네 집에 재화를 일으키고 내가 네 처들을 가져 네 눈앞에서 다른 사람에게 주리니 그 사람이 네 처들로 더불어 백주에 동침하리라"],["삼하 12:12","너는 은밀히 행하였으나 나는 이스라엘 무리 앞 백주에 이 일을 행하리라 하셨나이다"],["삼하 12:13","다윗이 나단에게 이르되 내가 여호와께 죄를 범하였노라 하매 나단이 다윗에게 대답하되 여호와께서도 당신의 죄를 사하셨나니 당신이 죽지 아니하려니와"]],"삼하 15:13-14":[["삼하 15:13","사자가 다윗에게 와서 고하되 이스라엘의 인심이 다 압살롬에게로 돌아갔나이다 한지라"],["삼하 15:14","다윗이 예루살렘에 함께 있는 모든 신복에게 이르되 일어나 도망하자 그렇지 아니하면 우리 한 사람도 압살롬에게서 피하지 못하리라 빨리 가자 두렵건대 저가 우리를 급히 따라와서 해하고 칼로 성을 칠까 하노라"]],"왕상 1:39; 2:10-11":[["왕상 1:39","제사장 사독이 성막 가운데서 기름 뿔을 가져다가 솔로몬에게 기름을 부으니 이에 양각을 불고 모든 백성이 솔로몬왕 만세를 부르니라"],["왕상 2:10","다윗이 그 열조와 함께 누워자서 다윗성에 장사되니"],["왕상 2:11","다윗이 이스라엘 왕이 된지 사십년이라 헤브론에서 칠년을 치리하였고 예루살렘에서 삼십 삼년을 치리하였더라"]],"왕상 16:28-29":[["왕상 16:28","오므리가 그 열조와 함께 자매 사마리아에 장사되고 그 아들 아합이 대신하여 왕이 되니라"],["왕상 16:29","유다 왕 아사 제 삼십 팔년에 오므리의 아들 아합이 이스라엘 왕이 되니라 오므리의 아들 아합이 사마리아에서 이십 이년을 이스라엘을 다스리니라"]],"왕상 16:29":[["왕상 16:29","유다 왕 아사 제 삼십 팔년에 오므리의 아들 아합이 이스라엘 왕이 되니라 오므리의 아들 아합이 사마리아에서 이십 이년을 이스라엘을 다스리니라"]],"왕상 22:34-37":[["왕상 22:34","한 사람이 우연히 활을 당기어 이스라엘 왕의 갑옷 솔기를 쏜지라 왕이 그 병거 모는 자에게 이르되 내가 부상하였으니 네 손을 돌이켜 나로 군중에서 나가게 하라 하였으나"],["왕상 22:35","이 날에 전쟁이 맹렬하였으므로 왕이 병거 가운데 붙들려 서서 아람 사람을 막다가 저녁에 이르러 죽었는데 상처의 피가 흘러 병거 바닥에 고였더라"],["왕상 22:36","해가 질 즈음에 군중에서 외치는 소리 있어 가로되 각기 성읍으로, 각기 본향으로 하더라"],["왕상 22:37","왕이 이미 죽으매 그 시체를 메어 사마리아에 이르러 거기 장사하니라"]],"왕상 16:28":[["왕상 16:28","오므리가 그 열조와 함께 자매 사마리아에 장사되고 그 아들 아합이 대신하여 왕이 되니라"]],"왕상 16:31":[["왕상 16:31","느밧의 아들 여로보암의 죄를 따라 행하는 것을 오히려 가볍게 여기며 시돈 사람의 왕 엣바알의 딸 이세벨로 아내를 삼고 가서 바알을 섬겨 숭배하고"]],"왕상 22:40":[["왕상 22:40","아합이 그 열조와 함께 자매 그 아들 아하시야가 대신하여 왕이 되니라"]],"왕하 3:1":[["왕하 3:1","유다 왕 여호사밧의 십팔년에 아합의 아들 여호람이 사마리아에서 이스라엘 왕이 되어 십 이년을 치리하니라"]],"왕하 8:18, 26":[["왕하 8:18","저가 이스라엘 왕들의 길로 행하여 아합의 집과 같이 하였으니 이는 아합의 딸이 그 아내가 되었음이라 저가 여호와 보시기에 악을 행하였으나"],["왕하 8:26","아하시야가 위에 나아갈 때에 나이 이십이세라 예루살렘에서 일년을 치리하니라 그 모친의 이름은 아달랴라 이스라엘 왕 오므리의 손녀더라"]],"왕상 16:31-32":[["왕상 16:31","느밧의 아들 여로보암의 죄를 따라 행하는 것을 오히려 가볍게 여기며 시돈 사람의 왕 엣바알의 딸 이세벨로 아내를 삼고 가서 바알을 섬겨 숭배하고"],["왕상 16:32","사마리아에 건축한 바알의 사당 속에 바알을 위하여 단을 쌓으며"]],"왕상 17:1":[["왕상 17:1","길르앗에 우거하는 자 중에 디셉 사람 엘리야가 아합에게 고하되 나의 섬기는 이스라엘 하나님 여호와의 사심을 가리켜 맹세하노니 내 말이 없으면 수년 동안 우로가 있지 아니하리라 하니라"]],"왕상 18:19-20, 38-39":[["왕상 18:19","그런즉 보내어 온 이스라엘과 이세벨의 상에서 먹는 바알의 선지자 사백 오십인과 아세라의 선지자 사백인을 갈멜산으로 모아 내게로 나오게 하소서"],["왕상 18:20","아합이 이에 이스라엘 모든 자손에게로 보내어 선지자들을 갈멜산으로 모으니라"],["왕상 18:38","이에 여호와의 불이 내려서 번제물과 나무와 돌과 흙을 태우고 또 도랑의 물을 핥은지라"],["왕상 18:39","모든 백성이 보고 엎드려 말하되 여호와 그는 하나님이시로다 여호와 그는 하나님이시로다 하니"]],"왕상 21:15-16":[["왕상 21:15","이세벨이 나봇이 돌에 맞아 죽었다 함을 듣고 아합에게 이르되 일어나서 그 이스르엘 사람 나봇이 돈으로 바꾸어 주기를 싫어하던 포도원을 취하소서 나봇이 살아 있지 아니하고 죽었나이다"],["왕상 21:16","아합이 나봇의 죽었다 함을 듣고 곧 일어나 이스르엘 사람 나봇의 포도원을 취하러 그리로 내려갔더라"]],"왕하 3:4":[["왕하 3:4","모압 왕 메사는 양을 치는 자라 새끼 양 십만의 털과 수양 십만의 털을 이스라엘 왕에게 바치더니"]],"왕하 3:27":[["왕하 3:27","이에 자기 위를 이어 왕이 될 맏아들을 취하여 성 위에서 번제를 드린지라 이스라엘에게 크게 통분함이 임하매 저희가 떠나 각기 고국으로 돌아갔더라"]],"왕하 3:5":[["왕하 3:5","아합이 죽은 후에 모압 왕이 이스라엘 왕을 배반한지라"]],"왕하 3:9, 24-25":[["왕하 3:9","이스라엘 왕이 유다 왕과 에돔 왕으로 더불어 행하더니 길을 둘러 행한지 칠일에 군사와 따라가는 생축을 먹일 물이 없는지라"],["왕하 3:24","이스라엘 진에 이르니 이스라엘 사람이 일어나 모압 사람을 쳐서 그 앞에서 도망하게 하고 그 지경에 들어가며 모압 사람을 치고"],["왕하 3:25","그 성읍을 쳐서 헐고 각기 돌을 던져 모든 좋은 밭에 가득하게 하고 모든 샘을 메우고 모든 좋은 나무를 베고 길하레셋의 돌들은 남기고 물맷군이 두루 다니며 치니라"]],"왕하 3:26-27":[["왕하 3:26","모압 왕이 전세가 극렬하여 당하기 어려움을 보고 칼 찬 군사 칠백을 거느리고 충돌하여 지나서 에돔 왕에게로 가고자 하되 능히 못하고"],["왕하 3:27","이에 자기 위를 이어 왕이 될 맏아들을 취하여 성 위에서 번제를 드린지라 이스라엘에게 크게 통분함이 임하매 저희가 떠나 각기 고국으로 돌아갔더라"]],"왕하 9:2":[["왕하 9:2","거기 이르거든 님시의 손자 여호사밧의 아들 예후를 찾아 들어가서 그 형제 중에서 일어나게 하고 데리고 골방으로 들어가서"]],"왕하 10:30; 15:12":[["왕하 10:30","여호와께서 예후에게 이르시되 네가 나보기에 정직한 일을 행하되 잘 행하여 내 마음에 있는대로 아합 집에 다 행하였은즉 네 자손이 이스라엘 왕위를 이어 사대를 지나리라 하시니라"],["왕하 15:12","여호와께서 예후에게 말씀하여 이르시기를 네 자손이 이스라엘 위를 이어 사대까지 이르리라 하신 그 말씀대로 과연 그렇게 되니라"]],"왕하 10:36":[["왕하 10:36","예후가 사마리아에서 이스라엘을 다스린 햇수는 이십 팔년이더라"]],"왕하 10:35":[["왕하 10:35","예후가 그 열조와 함께 자매 사마리아에 장사되고 그 아들 여호아하스가 대신하여 왕이 되니라"]],"왕하 15:12":[["왕하 15:12","여호와께서 예후에게 말씀하여 이르시기를 네 자손이 이스라엘 위를 이어 사대까지 이르리라 하신 그 말씀대로 과연 그렇게 되니라"]],"왕하 9:1-6":[["왕하 9:1","선지자 엘리사가 선지자의 생도 중 하나를 불러 이르되 너는 허리를 동이고 이 기름병을 손에 가지고 길르앗 라못으로 가라"],["왕하 9:2","거기 이르거든 님시의 손자 여호사밧의 아들 예후를 찾아 들어가서 그 형제 중에서 일어나게 하고 데리고 골방으로 들어가서"],["왕하 9:3","기름병을 가지고 그 머리에 부으며 이르기를 여호와의 말씀이 내가 네게 기름을 부어 이스라엘 왕을 삼노라 하셨느니라 하고 곧 문을 열고 도망하되 지체치 말찌니라"],["왕하 9:4","그 소년 곧 소년 선지자가 드디어 길르앗 라못으로 가니라"],["왕하 9:5","저가 이르러 보니 군대 장관들이 앉았는지라 소년이 가로되 장관이여 내가 당신에게 할 말씀이 있나이다 예후가 가로되 우리 모든 사람 중에 뉘게 하려느냐 가로되 장관이여 당신에게니이다"],["왕하 9:6","예후가 일어나 집으로 들어가니 소년이 그 머리에 기름을 부으며 이르되 이스라엘 하나님 여호와의 말씀이 내가 네게 기름을 부어 여호와의 백성 곧 이스라엘의 왕을 삼노니"]],"왕하 9:20, 24":[["왕하 9:20","파숫군이 또 고하여 가로되 저도 저희에게까지 갔으나 돌아오지 아니하고 그 병거 모는 것이 님시의 손자 예후의 모는 것 같이 미치게 모나이다"],["왕하 9:24","예후가 힘을 다하여 활을 당기어 요람의 두 팔 사이를 쏘니 살이 그 염통을 꿰뚫고 나오매 저가 병거 가운데 엎드러진지라"]],"왕하 9:27":[["왕하 9:27","유다 왕 아하시야가 이를 보고 동산 정자 길로 도망하니 예후가 쫓아가며 이르되 저도 병거 가운데서 죽이라 하매 이블르암 가까운 구르 비탈에서 치니 저가 므깃도까지 도망하여 거기서 죽은지라"]],"왕하 9:33":[["왕하 9:33","가로되 저를 내려던지라 하니 내려던지매 그 피가 담과 말에게 뛰더라 예후가 그 시체를 밟으니라"]],"왕하 10:7, 28":[["왕하 10:7","편지가 이르매 저희가 왕자 칠십인을 잡아 몰수히 죽이고 그 머리를 광주리에 담아 이스르엘 예후에게로 보내니라"],["왕하 10:28","예후가 이와 같이 이스라엘 중에서 바알을 멸하였으나"]],"왕하 10:35-36":[["왕하 10:35","예후가 그 열조와 함께 자매 사마리아에 장사되고 그 아들 여호아하스가 대신하여 왕이 되니라"],["왕하 10:36","예후가 사마리아에서 이스라엘을 다스린 햇수는 이십 팔년이더라"]],"사 1:1":[["사 1:1","유다 왕 웃시야와 요담과 아하스와 히스기야 시대에 아모스의 아들 이사야가 유다와 예루살렘에 대하여 본 이상이라"]],"사 6:1":[["사 6:1","웃시야왕의 죽던 해에 내가 본즉 주께서 높이 들린 보좌에 앉으셨는데 그 옷자락은 성전에 가득하였고"]],"사 7:3":[["사 7:3","때에 여호와께서 이사야에게 이르시되 너와 네 아들 스알야숩은 윗못 수도 끝 세탁자의 밭 큰 길에 나가서 아하스를 만나"]],"사 8:3":[["사 8:3","내가 내 아내와 동침하매 그가 잉태하여 아들을 낳은지라 여호와께서 내게 이르시되 그 이름을 마헬살랄하스바스라 하라"]],"사 6:1, 8":[["사 6:1","웃시야왕의 죽던 해에 내가 본즉 주께서 높이 들린 보좌에 앉으셨는데 그 옷자락은 성전에 가득하였고"],["사 6:8","내가 또 주의 목소리를 들은즉 이르시되 내가 누구를 보내며 누가 우리를 위하여 갈꼬 그 때에 내가 가로되 내가 여기 있나이다 나를 보내소서"]],"사 7:3, 14":[["사 7:3","때에 여호와께서 이사야에게 이르시되 너와 네 아들 스알야숩은 윗못 수도 끝 세탁자의 밭 큰 길에 나가서 아하스를 만나"],["사 7:14","그러므로 주께서 친히 징조로 너희에게 주실 것이라 보라 처녀가 잉태하여 아들을 낳을 것이요 그 이름을 임마누엘이라 하리라"]],"왕하 19:20, 32":[["왕하 19:20","아모스의 아들 이사야가 히스기야에게 기별하여 가로되 이스라엘 하나님 여호와의 말씀이 네가 앗수르 왕 산헤립 까닭에 내게 기도하는 것을 내가 들었노라 하셨나이다"],["왕하 19:32","그러므로 여호와께서 앗수르 왕을 가리켜 이르시기를 저가 이 성에 이르지 못하며 이리로 살을 쏘지 못하며 방패를 성을 향하여 세우지 못하며 치려고 토성을 쌓지도 못하고"]],"왕하 19:35-36":[["왕하 19:35","이 밤에 여호와의 사자가 나와서 앗수르 진에서 군사 십 팔만 오천을 친지라 아침에 일찌기 일어나 보니 다 송장이 되었더라"],["왕하 19:36","앗수르 왕 산헤립이 떠나 돌아가서 니느웨에 거하더니"]],"왕하 20:5-6":[["왕하 20:5","너는 돌아가서 내 백성의 주권자 히스기야에게 이르기를 왕의 조상 다윗의 하나님 여호와의 말씀이 내가 네 기도를 들었고 네 눈물을 보았노라 내가 너를 낫게 하리니 네가 삼일만에 여호와의 전에 올라가겠고"],["왕하 20:6","내가 네 날을 십 오년을 더할것이며 내가 너와 이 성을 앗수르 왕의 손에서 구원하고 내가 나를 위하고 또 내 종 다윗을 위하므로 이 성을 보호하리라 하셨다 하라 하셨더라"]],"왕하 20:16-18":[["왕하 20:16","이사야가 히스기야에게 이르되 여호와의 말씀을 들으소서"],["왕하 20:17","여호와의 말씀이 날이 이르리니 무릇 왕궁의 모든 것과 왕의 열조가 오늘까지 쌓아 두었던 것을 바벨론으로 옮긴바 되고 하나도 남지 아니할 것이요"],["왕하 20:18","또 왕의 몸에서 날 아들 중에서 사로잡혀 바벨론 왕궁의 환관이 되리라 하셨나이다"]],"왕하 18:1-3":[["왕하 18:1","이스라엘 왕 엘라의 아들 호세아 삼년에 유다 왕 아하스의 아들 히스기야가 왕이 되니"],["왕하 18:2","위에 나아갈 때에 나이 이십 오세라 예루살렘에서 이십 구년을 치리하니라 그 모친의 이름은 아비라 스가리야의 딸이더라"],["왕하 18:3","히스기야가 그 조상 다윗의 모든 행위와 같이 여호와 보시기에 정직히 행하여"]],"왕하 18:2":[["왕하 18:2","위에 나아갈 때에 나이 이십 오세라 예루살렘에서 이십 구년을 치리하니라 그 모친의 이름은 아비라 스가리야의 딸이더라"]],"대하 32:33":[["대하 32:33","히스기야가 그 열조와 함께 자매 온 유다와 예루살렘 거민이 저를 다윗 자손의 묘실 중 높은 곳에 장사하여 저의 죽음에 존경함을 표하였더라 그 아들 므낫세가 대신하여 왕이 되니라"]],"왕하 18:3":[["왕하 18:3","히스기야가 그 조상 다윗의 모든 행위와 같이 여호와 보시기에 정직히 행하여"]],"왕하 18:1":[["왕하 18:1","이스라엘 왕 엘라의 아들 호세아 삼년에 유다 왕 아하스의 아들 히스기야가 왕이 되니"]],"왕하 20:21; 21:1":[["왕하 20:21","히스기야가 그 열조와 함께 자고 그 아들 므낫세가 대신하여 왕이 되니라"],["왕하 21:1","므낫세가 위에 나아갈 때에 나이 십 이세라 예루살렘에서 오십 오년을 치리하니라 그 모친의 이름은 헵시바더라"]],"왕하 18:1-2":[["왕하 18:1","이스라엘 왕 엘라의 아들 호세아 삼년에 유다 왕 아하스의 아들 히스기야가 왕이 되니"],["왕하 18:2","위에 나아갈 때에 나이 이십 오세라 예루살렘에서 이십 구년을 치리하니라 그 모친의 이름은 아비라 스가리야의 딸이더라"]],"왕하 18:4":[["왕하 18:4","여러 산당을 제하며 주상을 깨뜨리며 아세라 목상을 찍으며 모세가 만들었던 놋뱀을 이스라엘 자손이 이때까지 향하여 분향하므로 그것을 부수고 느후스단이라 일컬었더라"]],"대하 30:1":[["대하 30:1","히스기야가 온 이스라엘과 유다에 보내고 또 에브라임과 므낫세에 편지를 보내어 예루살렘 여호와의 전에 와서 이스라엘 하나님 여호와를 위하여 유월절을 지키라 하니라"]],"왕하 18:7":[["왕하 18:7","여호와께서 저와 함께 하시매 저가 어디로 가든지 형통하였더라 저가 앗수르 왕을 배척하고 섬기지 아니하였고"]],"왕하 18:14":[["왕하 18:14","유다 왕 히스기야가 라기스로 보내어 앗수르 왕에게 이르되 내가 범죄하였나이다 나를 떠나 돌아가소서 왕이 내게 지우시는 것을 내가 당하리이다 하였더니 앗수르 왕이 곧 은 삼백 달란트와 금 삼십 달란트를 정하여 유다 왕 히스기야로 내게 한지라"]],"왕하 20:1-6":[["왕하 20:1","그 때에 히스기야가 병들어 죽게 되매 아모스의 아들 선지자 이사야가 저에게 나아와서 이르되 여호와의 말씀이 너는 집을 처치하라 네가 죽고 살지 못하리라 하셨나이다"],["왕하 20:2","히스기야가 낯을 벽으로 향하고 여호와께 기도하여 가로되"],["왕하 20:3","여호와여 구하오니 내가 진실과 전심으로 주 앞에 행하며 주의 보시기에 선하게 행한 것을 기억하옵소서 하고 심히 통곡하더라"],["왕하 20:4","이사야가 성읍 가운데까지도 이르기 전에 여호와의 말씀이 저에게 임하여 가라사대"],["왕하 20:5","너는 돌아가서 내 백성의 주권자 히스기야에게 이르기를 왕의 조상 다윗의 하나님 여호와의 말씀이 내가 네 기도를 들었고 네 눈물을 보았노라 내가 너를 낫게 하리니 네가 삼일만에 여호와의 전에 올라가겠고"],["왕하 20:6","내가 네 날을 십 오년을 더할것이며 내가 너와 이 성을 앗수르 왕의 손에서 구원하고 내가 나를 위하고 또 내 종 다윗을 위하므로 이 성을 보호하리라 하셨다 하라 하셨더라"]],"왕하 20:12-13":[["왕하 20:12","그 때에 발라단의 아들 바벨론 왕 부로닥발라단이 히스기야가 병 들었다 함을 듣고 편지와 예물을 저에게 보낸지라"],["왕하 20:13","히스기야가 사자의 말을 듣고 자기 보물고의 금은과 향품과 보배로운 기름과 그 군기고와 내탕고의 모든 것을 다 사자에게 보였는데 무릇 왕궁과 그 나라 안에 있는 것을 저에게 보이지 아니한 것이 없으니라"]],"대하 32:30; 왕하 20:20":[["대하 32:30","이 히스기야가 또 기혼의 윗 샘물을 막아 그 아래로 좇아 다윗성 서편으로 곧게 인도하였으니 저의 모든 일이 형통하였더라"],["왕하 20:20","히스기야의 남은 사적과 그 모든 권력과 못과 수도를 만들어 물을 성중으로 인도하여 들인 일은 유다 왕 역대지략에 기록되지 아니하였느냐"]],"왕하 20:21":[["왕하 20:21","히스기야가 그 열조와 함께 자고 그 아들 므낫세가 대신하여 왕이 되니라"]],"왕하 19:36":[["왕하 19:36","앗수르 왕 산헤립이 떠나 돌아가서 니느웨에 거하더니"]],"왕하 19:37":[["왕하 19:37","그 신 니스록의 묘에 경배할 때에 아드람멜렉과 사레셀이 저를 칼로 쳐 죽이고 아라랏 땅으로 도망하매 그 아들 에살핫돈이 대신하여 왕이 되니라"]],"왕하 18:17, 28":[["왕하 18:17","앗수르 왕이 다르단과 랍사리스와 랍사게로 대군을 거느리고 라기스에서부터 예루살렘으로 가서 히스기야왕을 치게 하매 저희가 예루살렘으로 올라가니라 저희가 올라가서 윗못 수도 곁 곧 세탁자의 밭에 있는 큰 길에 이르러 서니라"],["왕하 18:28","랍사게가 드디어 일어 서서 유다 방언으로 크게 소리질러 불러 가로되 너희는 대왕 앗수르 왕의 말씀을 들으라"]],"왕하 19:35":[["왕하 19:35","이 밤에 여호와의 사자가 나와서 앗수르 진에서 군사 십 팔만 오천을 친지라 아침에 일찌기 일어나 보니 다 송장이 되었더라"]],"왕하 24:6":[["왕하 24:6","여호야김이 그 열조와 함께 자매 그 아들 여호야긴이 대신하여 왕이 되니라"]],"왕하 24:8":[["왕하 24:8","여호야긴이 위에 나아갈 때에 나이 십 팔세라 예루살렘에서 석 달을 치리하니라 그 모친의 이름은 느후스다라 예루살렘 엘라단의 딸이더라"]],"렘 24:1":[["렘 24:1","바벨론 왕 느부갓네살이 유다 왕 여호야김의 아들 여고냐와 유다 방백들과 목공들과 철공들을 예루살렘에서 바벨론으로 옮긴 후에 여호와께서 여호와의 전 앞에 놓인 무화과 두 광주리로 내게 보이셨는데"]],"마 1:6, 11":[["마 1:6","이새는 다윗왕을 낳으니라 다윗은 우리야의 아내에게서 솔로몬을 낳고"],["마 1:11","바벨론으로 이거할 때에 요시야는 여고냐와 그의 형제를 낳으니라"]],"대상 3:15-16":[["대상 3:15","요시야의 아들들은 맏아들 요하난과 둘째 여호야김과 세째 시드기야와 네째 살룸이요"],["대상 3:16","여호야김의 아들들은 그 아들 여고냐, 그 아들 시드기야요"]],"왕하 24:17":[["왕하 24:17","바벨론 왕이 또 여호야긴의 아자비 맛다니야로 대신하여 왕을 삼고 그 이름을 고쳐 시드기야라 하였더라"]],"대상 3:17-18":[["대상 3:17","사로잡혀 간 여고냐의 아들들은 그 아들 스알디엘과"],["대상 3:18","말기람과 브다야와 세낫살과 여가먀와 호사마와 느다뱌요"]],"마 1:12":[["마 1:12","바벨론으로 이거한 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고"]],"마 1:12, 16":[["마 1:12","바벨론으로 이거한 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"왕하 24:12, 15":[["왕하 24:12","유다 왕 여호야긴이 그 모친과 신복과 방백들과 내시들과 함께 바벨론 왕에게 나아가매 왕이 잡으니 때는 바벨론 왕 팔년이라"],["왕하 24:15","저가 여호야긴을 바벨론으로 사로잡아 가고 왕의 모친과 왕의 아내들과 내시와 나라에 권세 있는 자도 예루살렘에서 바벨론으로 사로잡아 가고"]],"렘 22:30":[["렘 22:30","나 여호와가 이같이 말하노라 너희는 이 사람이 무자하겠고 그 평생에 형통치 못할 자라 기록하라 이는 그 자손 중 형통하여 다윗의 위에 앉아 유다를 다스릴 사람이 다시는 없을 것임이니라"]],"왕하 25:27-30":[["왕하 25:27","유다 왕 여호야긴이 사로잡혀 간지 삼십 칠년 곧 바벨론 왕 에윌므로닥의 즉위한 원년 십 이월 이십 칠일에 유다 왕 여호야긴을 옥에서 내어놓아 그 머리를 들게 하고"],["왕하 25:28","선히 말하고 그 위를 바벨론에 저와 함께 있는 모든 왕의 위보다 높이고"],["왕하 25:29","그 죄수의 의복을 바꾸게 하고 그 일평생에 항상 왕의 앞에서 먹게 하였고"],["왕하 25:30","저의 쓸 것은 날마다 왕에게서 받는 정수가 있어서 종신토록 끊이지 아니하였더라"]],"단 4:30":[["단 4:30","나 왕이 말하여 가로되 이 큰 바벨론은 내가 능력과 권세로 건설하여 나의 도성을 삼고 이것으로 내 위엄의 영광을 나타낸 것이 아니냐 하였더니"]],"왕하 24:1":[["왕하 24:1","여호야김 시대에 바벨론 왕 느부갓네살이 올라오매 여호야김이 삼년을 섬기다가 돌이켜 저를 배반하였더니"]],"왕하 25:27":[["왕하 25:27","유다 왕 여호야긴이 사로잡혀 간지 삼십 칠년 곧 바벨론 왕 에윌므로닥의 즉위한 원년 십 이월 이십 칠일에 유다 왕 여호야긴을 옥에서 내어놓아 그 머리를 들게 하고"]],"렘 46:2":[["렘 46:2","애굽을 논한 것이니 곧 유다 왕 요시야의 아들 여호야김 제 사년에 유브라데 하숫가 갈그미스에서 바벨론 왕 느부갓네살에게 패한 애굽 왕 바로느고의 군대에 대한 말씀이라"]],"단 1:1-6":[["단 1:1","유다 왕 여호야김이 위에 있은지 삼년에 바벨론 왕 느부갓네살이 예루살렘에 이르러 그것을 에워쌌더니"],["단 1:2","주께서 유다 왕 여호야김과 하나님의 전 기구 얼마를 그의 손에 붙이시매 그가 그것을 가지고 시날 땅 자기 신의 묘에 이르러 그 신의 보고에 두었더라"],["단 1:3","왕이 환관장 아스부나스에게 명하여 이스라엘 자손 중에서 왕족과 귀족의 몇 사람"],["단 1:4","곧 흠이 없고 아름다우며 모든 재주를 통달하며 지식이 구비하며 학문에 익숙하여 왕궁에 모실만한 소년을 데려오게 하였고 그들에게 갈대아 사람의 학문과 방언을 가르치게 하였고"],["단 1:5","또 왕이 지정하여 자기의 진미와 자기의 마시는 포도주에서 그들의 날마다 쓸 것을 주어 삼년을 기르게 하였으니 이는 그 후에 그들로 왕의 앞에 모셔 서게 하려함이었더라"],["단 1:6","그들 중에 유다 자손 곧 다니엘과 하나냐와 미사엘과 아사랴가 있었더니"]],"왕하 24:10-17":[["왕하 24:10","그 때에 바벨론 왕 느부갓네살의 신복들이 예루살렘에 올라와서 그 성을 에워싸니라"],["왕하 24:11","그 신복들이 에워쌀 때에 바벨론 왕 느부갓네살도 그 성에 이르니"],["왕하 24:12","유다 왕 여호야긴이 그 모친과 신복과 방백들과 내시들과 함께 바벨론 왕에게 나아가매 왕이 잡으니 때는 바벨론 왕 팔년이라"],["왕하 24:13","저가 여호와의 전의 모든 보물과 왕궁 보물을 집어내고 또 이스라엘 왕 솔로몬이 만든 것 곧 여호와의 전의 금 기명을 다 훼파하였으니 여호와의 말씀과 같이 되었더라"],["왕하 24:14","저가 또 예루살렘의 모든 백성과 모든 방백과 모든 용사 합 일만명과 모든 공장과 대장장이를 사로잡아 가매 빈천한 자 외에는 그 땅에 남은 자가 없었더라"],["왕하 24:15","저가 여호야긴을 바벨론으로 사로잡아 가고 왕의 모친과 왕의 아내들과 내시와 나라에 권세 있는 자도 예루살렘에서 바벨론으로 사로잡아 가고"],["왕하 24:16","또 용사 칠천과 공장과 대장장이 일천 곧 다 강장하여 싸움에 능한 자들을 바벨론으로 사로잡아 가고"],["왕하 24:17","바벨론 왕이 또 여호야긴의 아자비 맛다니야로 대신하여 왕을 삼고 그 이름을 고쳐 시드기야라 하였더라"]],"왕하 25:8-9":[["왕하 25:8","바벨론 왕 느부갓네살의 십 구년 오월 칠일에 바벨론 왕의 신하 시위대 장관 느부사라단이 예루살렘에 이르러"],["왕하 25:9","여호와의 전과 왕궁을 사르고 예루살렘의 모든 집을 귀인의 집까지 불살랐으며"]],"단 2:31, 47":[["단 2:31","왕이여 왕이 한 큰 신상을 보셨나이다 그 신상이 왕의 앞에 섰는데 크고 광채가 특심하며 그 모양이 심히 두려우니"],["단 2:47","왕이 대답하여 다니엘에게 이르되 너희 하나님은 참으로 모든 신의 신이시요 모든 왕의 주재시로다 네가 능히 이 은밀한 것을 나타내었으니 네 하나님은 또 은밀한 것을 나타내시는 자시로다"]],"단 4:33-34, 37":[["단 4:33","그 동시에 이 일이 나 느부갓네살에게 응하므로 내가 사람에게 쫓겨나서 소처럼 풀을 먹으며 몸이 하늘 이슬에 젖고 머리털이 독수리 털과 같았고 손톱은 새 발톱과 같았었느니라"],["단 4:34","그 기한이 차매 나 느부갓네살이 하늘을 우러러 보았더니 내 총명이 다시 내게로 돌아온지라 이에 내가 지극히 높으신 자에게 감사하며 영생하시는 자를 찬양하고 존경하였노니 그 권세는 영원한 권세요 그 나라는 대대에 이르리로다"],["단 4:37","그러므로 지금 나 느부갓네살이 하늘의 왕을 찬양하며 칭송하며 존경하노니 그의 일이 다 진실하고 그의 행하심이 의로우시므로 무릇 교만하게 행하는 자를 그가 능히 낮추심이니라"]],"스 1:1":[["스 1:1","바사 왕 고레스 원년에 여호와께서 예레미야의 입으로 하신 말씀을 응하게 하시려고 바사 왕 고레스의 마음을 감동시키시매 저가 온 나라에 공포도 하고 조서도 내려 가로되"]],"스 6:2":[["스 6:2","메대도 악메다 궁에서 한 두루마리를 얻으니 거기 기록하였으되"]],"스 1:1-3":[["스 1:1","바사 왕 고레스 원년에 여호와께서 예레미야의 입으로 하신 말씀을 응하게 하시려고 바사 왕 고레스의 마음을 감동시키시매 저가 온 나라에 공포도 하고 조서도 내려 가로되"],["스 1:2","바사 왕 고레스는 말하노니 하늘의 신 여호와께서 세상 만국으로 내게 주셨고 나를 명하사 유다 예루살렘에 전을 건축하라 하셨나니"],["스 1:3","이스라엘의 하나님은 참 신이시라 너희 중에 무릇 그 백성 된 자는 다 유다 예루살렘으로 올라가서 거기 있는 여호와의 전을 건축하라 너희 하나님이 함께 하시기를 원하노라"]],"스 1:7, 11":[["스 1:7","고레스왕이 또 여호와의 전 기명을 꺼내니 옛적에 느부갓네살이 예루살렘에서 옮겨다가 자기 신들의 당에 두었던 것이라"],["스 1:11","금, 은기명의 도합이 오천 사백이라 사로잡힌 자를 바벨론에서 예루살렘으로 데리고 올 때에 세스바살이 그 기명들을 다 가지고 왔더라"]],"스 6:2-3":[["스 6:2","메대도 악메다 궁에서 한 두루마리를 얻으니 거기 기록하였으되"],["스 6:3","고레스왕 원년에 조서를 내려 이르기를 예루살렘 하나님의 전에 대하여 이르노니 이 전 곧 제사 드리는 처소를 건축하되 지대를 견고히 쌓고 그 전의 고는 육십 규빗으로, 광도 육십 규빗으로 하고"]],"마 2:1":[["마 2:1","헤롯왕 때에 예수께서 유대 베들레헴에서 나시매 동방으로부터 박사들이 예루살렘에 이르러 말하되"]],"눅 2:39":[["눅 2:39","주의 율법을 좇아 모든 일을 필하고 갈릴리로 돌아가 본 동네 나사렛에 이르니라"]],"막 6:3":[["막 6:3","이 사람이 마리아의 아들 목수가 아니냐 야고보와 요셉과 유다와 시몬의 형제가 아니냐 그 누이들이 우리와 함께 여기 있지 아니하냐 하고 예수를 배척한지라"]],"눅 3:23":[["눅 3:23","예수께서 가르치심을 시작할 때에 삼십세쯤 되시니라 사람들의 아는대로는 요셉의 아들이니 요셉의 이상은 헬리요"]],"마 1:9-10":[["마 1:9","웃시야는 요담을 낳고 요담은 아하스를 낳고 아하스는 히스기야를 낳고"],["마 1:10","히스기야는 므낫세를 낳고 므낫세는 아몬을 낳고 아몬은 요시야를 낳고"]],"마 1:11-12":[["마 1:11","바벨론으로 이거할 때에 요시야는 여고냐와 그의 형제를 낳으니라"],["마 1:12","바벨론으로 이거한 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고"]],"마 1:16":[["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"마 1:16; 13:55":[["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"],["마 13:55","이는 그 목수의 아들이 아니냐 그 모친은 마리아, 그 형제들은 야고보, 요셉, 시몬, 유다라 하지 않느냐"]],"마 13:55":[["마 13:55","이는 그 목수의 아들이 아니냐 그 모친은 마리아, 그 형제들은 야고보, 요셉, 시몬, 유다라 하지 않느냐"]],"눅 1:36":[["눅 1:36","보라 네 친족 엘리사벳도 늙어서 아들을 배었느니라 본래 수태하지 못한다 하던 이가 이미 여섯 달이 되었나니"]],"마 2:14, 23":[["마 2:14","요셉이 일어나서 밤에 아기와 그의 모친을 데리고 애굽으로 떠나가"],["마 2:23","나사렛이란 동네에 와서 사니 이는 선지자로 하신 말씀에 나사렛 사람이라 칭하리라 하심을 이루려 함이러라"]],"눅 2:42, 46":[["눅 2:42","예수께서 열 두살 될 때에 저희가 이 절기의 전례를 좇아 올라갔다가"],["눅 2:46","사흘 후에 성전에서 만난즉 그가 선생들 중에 앉으사 저희에게 듣기도 하시며 묻기도 하시니"]],"눅 3:1; 막 1:9":[["눅 3:1","디베료 가이사가 위에 있은지 열 다섯 해 곧 본디오 빌라도가 유대의 총독으로, 헤롯이 갈릴리의 분봉왕으로, 그 동생 빌립이 이두래와 드라고닛 지방의 분봉왕으로, 루사니아가 아빌레네의 분봉왕으로,"],["막 1:9","그 때에 예수께서 갈릴리 나사렛으로부터 와서 요단강에서 요한에게 세례를 받으시고"]],"마 4:13, 23":[["마 4:13","나사렛을 떠나 스불론과 납달리 지경 해변에 있는 가버나움에 가서 사시니"],["마 4:23","예수께서 온 갈릴리에 두루 다니사 저희 회당에서 가르치시며 천국 복음을 전파하시며 백성 중에 모든 병과 모든 약한 것을 고치시니"]],"막 3:14":[["막 3:14","이에 열 둘을 세우셨으니 이는 자기와 함께 있게 하시고 또 보내사 전도도 하며"]],"마 26:57":[["마 26:57","예수를 잡은 자들이 끌고 대제사장 가야바에게로 가니 거기 서기관과 장로들이 모여 있더라"]],"막 16:6; 고전 15:3-4":[["막 16:6","청년이 이르되 놀라지 말라 너희가 십자가에 못 박히신 나사렛 예수를 찾는구나 그가 살아나셨고 여기 계시지 아니하니라 보라 그를 두었던 곳이니라"],["고전 15:3","내가 받은 것을 먼저 너희에게 전하였노니 이는 성경대로 그리스도께서 우리 죄를 위하여 죽으시고"],["고전 15:4","장사 지낸바 되었다가 성경대로 사흘만에 다시 살아나사"]],"눅 3:1":[["눅 3:1","디베료 가이사가 위에 있은지 열 다섯 해 곧 본디오 빌라도가 유대의 총독으로, 헤롯이 갈릴리의 분봉왕으로, 그 동생 빌립이 이두래와 드라고닛 지방의 분봉왕으로, 루사니아가 아빌레네의 분봉왕으로,"]],"마 27:19":[["마 27:19","총독이 재판 자리에 앉았을 때에 그 아내가 사람을 보내어 가로되 저 옳은 사람에게 아무 상관도 하지 마옵소서 오늘 꿈에 내가 그 사람을 인하여 애를 많이 썼나이다 하더라"]],"눅 13:1":[["눅 13:1","그 때 마침 두어 사람이 와서 빌라도가 어떤 갈릴리 사람들의 피를 저희의 제물에 섞은 일로 예수께 고하니"]],"요 18:38":[["요 18:38","빌라도가 가로되 진리가 무엇이냐 하더라 이 말을 하고 다시 유대인들에게 나가서 이르되 나는 그에게서 아무 죄도 찾지 못하노라"]],"마 27:24":[["마 27:24","빌라도가 아무 효험도 없이 도리어 민란이 나려는 것을 보고 물을 가져다가 무리 앞에서 손을 씻으며 가로되 이 사람의 피에 대하여 나는 무죄하니 너희가 당하라"]],"요 19:19":[["요 19:19","빌라도가 패를 써서 십자가 위에 붙이니 나사렛 예수 유대인의 왕이라 기록되었더라"]],"요 18:13":[["요 18:13","먼저 안나스에게로 끌고 가니 안나스는 그 해의 대제사장인 가야바의 장인이라"]],"요 11:49-50":[["요 11:49","그 중에 한 사람 그 해 대제사장인 가야바가 저희에게 말하되 너희가 아무 것도 알지 못하는도다"],["요 11:50","한 사람이 백성을 위하여 죽어서 온 민족이 망하지 않게 되는 것이 너희에게 유익한 줄을 생각지 아니하는도다 하였으니"]],"마 26:3-4":[["마 26:3","그 때에 대제사장들과 백성의 장로들이 가야바라 하는 대제사장의 아문에 모여"],["마 26:4","예수를 궤계로 잡아 죽이려고 의논하되"]],"마 26:57, 63-65":[["마 26:57","예수를 잡은 자들이 끌고 대제사장 가야바에게로 가니 거기 서기관과 장로들이 모여 있더라"],["마 26:63","예수께서 잠잠하시거늘 대제사장이 가로되 내가 너로 살아 계신 하나님께 맹세하게 하노니 네가 하나님의 아들 그리스도인지 우리에게 말하라"],["마 26:64","예수께서 가라사대 네가 말하였느니라 그러나 내가 너희에게 이르노니 이 후에 인자가 권능의 우편에 앉은 것과 하늘 구름을 타고 오는 것을 너희가 보리라 하시니"],["마 26:65","이에 대제사장이 자기 옷을 찢으며 가로되 저가 참람한 말을 하였으니 어찌 더 증인을 요구하리요 보라 너희가 지금 이 참람한 말을 들었도다"]],"요 18:28":[["요 18:28","저희가 예수를 가야바에게서 관정으로 끌고 가니 새벽이라 저희는 더럽힘을 받지 아니하고 유월절 잔치를 먹고자 하여 관정에 들어가지 아니하더라"]],"행 4:6-7":[["행 4:6","대제사장 안나스와 가야바와 요한과 알렉산더와 및 대제사장의 문중이 다 참예하여"],["행 4:7","사도들을 가운데 세우고 묻되 너희가 무슨 권세와 뉘 이름으로 이 일을 행하였느냐"]],"행 13:9":[["행 13:9","바울이라고 하는 사울이 성령이 충만하여 그를 주목하고"]],"빌 3:5":[["빌 3:5","내가 팔일만에 할례를 받고 이스라엘의 족속이요 베냐민의 지파요 히브리인 중의 히브리인이요 율법으로는 바리새인이요"]],"행 22:3":[["행 22:3","나는 유대인으로 길리기아 다소에서 났고 이 성에서 자라 가말리엘의 문하에서 우리 조상들의 율법의 엄한 교훈을 받았고 오늘 너희 모든 사람처럼 하나님께 대하여 열심하는 자라"]],"행 22:28":[["행 22:28","천부장이 대답하되 나는 돈을 많이 들여 이 시민권을 얻었노라 바울이 가로되 나는 나면서부터로라 하니"]],"행 22:3; 빌 3:5":[["행 22:3","나는 유대인으로 길리기아 다소에서 났고 이 성에서 자라 가말리엘의 문하에서 우리 조상들의 율법의 엄한 교훈을 받았고 오늘 너희 모든 사람처럼 하나님께 대하여 열심하는 자라"],["빌 3:5","내가 팔일만에 할례를 받고 이스라엘의 족속이요 베냐민의 지파요 히브리인 중의 히브리인이요 율법으로는 바리새인이요"]],"행 18:3":[["행 18:3","업이 같으므로 함께 거하여 일을 하니 그 업은 장막을 만드는 것이더라"]],"행 23:16":[["행 23:16","바울의 생질이 그들이 매복하여 있다 함을 듣고 와서 영문에 들어가 바울에게 고한지라"]],"롬 16:7, 11":[["롬 16:7","내 친척이요 나와 함께 갇혔던 안드로니고와 유니아에게 문안하라 저희는 사도에게 유명히 여김을 받고 또한 나보다 먼저 그리스도 안에 있는 자라"],["롬 16:11","내 친척 헤로디온에게 문안하라 나깃수의 권속중 주 안에 있는 자들에게 문안하라"]],"고전 7:7-8":[["고전 7:7","나는 모든 사람이 나와 같기를 원하노라 그러나 각각 하나님께 받은 자기의 은사가 있으니 하나는 이러하고 하나는 저러하니라"],["고전 7:8","내가 혼인하지 아니한 자들과 및 과부들에게 이르노니 나와 같이 그냥 지내는 것이 좋으니라"]],"행 7:58; 8:1":[["행 7:58","성 밖에 내치고 돌로 칠쌔 증인들이 옷을 벗어 사울이라 하는 청년의 발앞에 두니라"],["행 8:1","사울이 그의 죽임 당함을 마땅히 여기더라 그 날에 예루살렘에 있는 교회에 큰 핍박이 나서 사도 외에는 다 유대와 사마리아 모든 땅으로 흩어지니라"]],"행 9:3-6":[["행 9:3","사울이 행하여 다메섹에 가까이 가더니 홀연히 하늘로서 빛이 저를 둘러 비추는지라"],["행 9:4","땅에 엎드러져 들으매 소리 있어 가라사대 사울아 사울아 네가 어찌하여 나를 핍박하느냐 하시거늘"],["행 9:5","대답하되 주여 뉘시오니이까 가라사대 나는 네가 핍박하는 예수라"],["행 9:6","네가 일어나 성으로 들어가라 행할 것을 네게 이를 자가 있느니라 하시니"]],"행 13:2-4":[["행 13:2","주를 섬겨 금식할 때에 성령이 가라사대 내가 불러 시키는 일을 위하여 바나바와 사울을 따로 세우라 하시니"],["행 13:3","이에 금식하며 기도하고 두 사람에게 안수하여 보내니라"],["행 13:4","두 사람이 성령의 보내심을 받아 실루기아에 내려가 거기서 배 타고 구브로에 가서"]],"행 18:11":[["행 18:11","일년 육개월을 유하며 그들 가운데서 하나님의 말씀을 가르치니라"]],"행 19:8-10":[["행 19:8","바울이 회당에 들어가 석 달 동안을 담대히 하나님 나라에 대하여 강론하며 권면하되"],["행 19:9","어떤 사람들은 마음이 굳어 순종치 않고 무리 앞에서 이 도를 비방하거늘 바울이 그들을 떠나 제자들을 따로 세우고 두란노 서원에서 날마다 강론하여"],["행 19:10","이같이 두 해 동안을 하매 아시아에 사는 자는 유대인이나 헬라인이나 다 주의 말씀을 듣더라"]],"행 21:30-33":[["행 21:30","온 성이 소동하여 백성이 달려와 모여 바울을 잡아 성전 밖으로 끌고 나가니 문들이 곧 닫히더라"],["행 21:31","저희가 그를 죽이려 할 때에 온 예루살렘의 요란하다는 소문이 군대의 천부장에게 들리매"],["행 21:32","저가 급히 군사들과 백부장들을 거느리고 달려 내려가니 저희가 천부장과 군사들을 보고 바울 치기를 그치는지라"],["행 21:33","이에 천부장이 가까이 가서 바울을 잡아 두 쇠사슬로 결박하라 명하고 누구며 무슨 일을 하였느냐 물으니"]],"행 24:27":[["행 24:27","이태를 지내서 보르기오 베스도가 벨릭스의 소임을 대신하니 벨릭스가 유대인의 마음을 얻고자 하여 바울을 구류하여 두니라"]],"행 28:16, 30":[["행 28:16","우리가 로마에 들어가니 바울은 자기를 지키는 한 군사와 함께 따로 있게 허락하더라"],["행 28:30","바울이 온 이태를 자기 셋집에 유하며 자기에게 오는 사람을 다 영접하고"]],"창 17:19":[["창 17:19","하나님이 가라사대 아니라 네 아내 사라가 정녕 네게 아들을 낳으리니 너는 그 이름을 이삭이라 하라 내가 그와 내 언약을 세우리니 그의 후손에게 영원한 언약이 되리라"]],"창 21:5; 17:17":[["창 21:5","아브라함이 그 아들 이삭을 낳을 때에 백세라"],["창 17:17","아브라함이 엎드리어 웃으며 심중에 이르되 백세 된 사람이 어찌 자식을 낳을까 사라는 구십세니 어찌 생산하리요 하고"]],"창 25:20":[["창 25:20","이삭은 사십세에 리브가를 취하여 아내를 삼았으니 리브가는 밧단 아람의 아람 족속 중 브두엘의 딸이요 아람 족속 중 라반의 누이였더라"]],"창 26:6, 23; 35:27":[["창 26:6","이삭이 그랄에 거하였더니"],["창 26:23","이삭이 거기서부터 브엘세바로 올라갔더니"],["창 35:27","야곱이 기럇아르바의 마므레로 가서 그 아비 이삭에게 이르렀으니 기럇아르바는 곧 아브라함과 이삭의 우거하던 헤브론이더라"]],"창 35:28-29; 49:31":[["창 35:28","이삭의 나이 일백 팔십세라"],["창 35:29","이삭이 나이 많고 늙어 기운이 진하매 죽어 자기 열조에게로 돌아가니 그 아들 에서와 야곱이 그를 장사하였더라"],["창 49:31","아브라함과 그 아내 사라가 거기 장사되었고 이삭과 그 아내 리브가도 거기 장사되었으며 나도 레아를 그곳에 장사하였노라"]],"창 21:3":[["창 21:3","아브라함이 그 낳은 아들 곧 사라가 자기에게 낳은 아들을 이름하여 이삭이라 하였고"]],"창 24:15":[["창 24:15","말을 마치지 못하여서 리브가가 물 항아리를 어깨에 메고 나오니 그는 아브라함의 동생 나홀의 아내 밀가의 아들 브두엘의 소생이라"]],"창 16:15; 25:9":[["창 16:15","하갈이 아브람의 아들을 낳으매 아브람이 하갈의 낳은 그 아들을 이름하여 이스마엘이라 하였더라"],["창 25:9","그 아들 이삭과 이스마엘이 그를 마므레 앞 헷 족속 소할의 아들 에브론의 밭에 있는 막벨라 굴에 장사하였으니"]],"창 24:67":[["창 24:67","이삭이 리브가를 인도하여 모친 사라의 장막으로 들이고 그를 취하여 아내를 삼고 사랑하였으니 이삭이 모친 상사 후에 위로를 얻었더라"]],"창 25:25, 30":[["창 25:25","먼저 나온 자는 붉고 전신이 갖옷 같아서 이름을 에서라 하였고"],["창 25:30","야곱에게 이르되 내가 곤비하니 그 붉은 것을 나로 먹게 하라 한지라 그러므로 에서의 별명은 에돔이더라"]],"창 25:26":[["창 25:26","후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라"]],"창 36:4-5":[["창 36:4","아다는 엘리바스를 에서에게 낳았고 바스맛은 르우엘을 낳았고"],["창 36:5","오홀리바마는 여우스와 얄람과 고라를 낳았으니 이들은 에서의 아들이요 가나안 땅에서 그에게 낳은 자더라"]],"창 35:23-26":[["창 35:23","레아의 소생은 야곱의 장자 르우벤과 그 다음 시므온과 레위와 유다와 잇사갈과 스불론이요"],["창 35:24","라헬의 소생은 요셉과 베냐민이며"],["창 35:25","라헬의 여종 빌하의 소생은 단과 납달리요"],["창 35:26","레아의 여종 실바의 소생은 갓과 아셀이니 이들은 야곱의 아들들이요 밧단아람에서 그에게 낳은 자더라"]],"창 35:24":[["창 35:24","라헬의 소생은 요셉과 베냐민이며"]],"마 1:2, 16":[["마 1:2","아브라함이 이삭을 낳고 이삭은 야곱을 낳고 야곱은 유다와 그의 형제를 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"창 21:3-5":[["창 21:3","아브라함이 그 낳은 아들 곧 사라가 자기에게 낳은 아들을 이름하여 이삭이라 하였고"],["창 21:4","그 아들 이삭이 난지 팔일만에 그가 하나님의 명대로 할례를 행하였더라"],["창 21:5","아브라함이 그 아들 이삭을 낳을 때에 백세라"]],"창 21:8-10":[["창 21:8","아이가 자라매 젖을 떼고 이삭의 젖을 떼는 날에 아브라함이 대연을 배설하였더라"],["창 21:9","사라가 본즉 아브라함의 아들 애굽 여인 하갈의 소생이 이삭을 희롱하는지라"],["창 21:10","그가 아브라함에게 이르되 이 여종과 그 아들을 내어쫓으라 이 종의 아들은 내 아들 이삭과 함께 기업을 얻지 못하리라 하매"]],"창 22:2, 9-13":[["창 22:2","여호와께서 가라사대 네 아들 네 사랑하는 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 지시하는 한 산 거기서 그를 번제로 드리라"],["창 22:9","하나님이 그에게 지시하신 곳에 이른지라 이에 아브라함이 그곳에 단을 쌓고 나무를 벌여놓고 그 아들 이삭을 결박하여 단 나무 위에 놓고"],["창 22:10","손을 내밀어 칼을 잡고 그 아들을 잡으려 하더니"],["창 22:11","여호와의 사자가 하늘에서부터 그를 불러 가라사대 아브라함아 아브라함아 하시는지라 아브라함이 가로되 내가 여기 있나이다 하매"],["창 22:12","사자가 가라사대 그 아이에게 네 손을 대지 말라 아무 일도 그에게 하지 말라 네가 네 아들 네 독자라도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라"],["창 22:13","아브라함이 눈을 들어 살펴본즉 한 수양이 뒤에 있는데 뿔이 수풀에 걸렸는지라 아브라함이 가서 그 수양을 가져다가 아들을 대신하여 번제로 드렸더라"]],"창 23:1-2":[["창 23:1","사라가 일백 이십 칠세를 살았으니 이것이 곧 사라의 향년이라"],["창 23:2","사라가 가나안 땅 헤브론 곧 기럇아르바에서 죽으매 아브라함이 들어가서 사라를 위하여 슬퍼하며 애통하다가"]],"창 24:4, 67; 25:20":[["창 24:4","내 고향 내 족속에게로 가서 내 아들 이삭을 위하여 아내를 택하라"],["창 24:67","이삭이 리브가를 인도하여 모친 사라의 장막으로 들이고 그를 취하여 아내를 삼고 사랑하였으니 이삭이 모친 상사 후에 위로를 얻었더라"],["창 25:20","이삭은 사십세에 리브가를 취하여 아내를 삼았으니 리브가는 밧단 아람의 아람 족속 중 브두엘의 딸이요 아람 족속 중 라반의 누이였더라"]],"창 25:21, 26":[["창 25:21","이삭이 그 아내가 잉태하지 못하므로 그를 위하여 여호와께 간구하매 여호와께서 그 간구를 들으셨으므로 그 아내 리브가가 잉태하였더니"],["창 25:26","후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라"]],"창 25:8-9":[["창 25:8","그가 수가 높고 나이 많아 기운이 진하여 죽어 자기 열조에게로 돌아가매"],["창 25:9","그 아들 이삭과 이스마엘이 그를 마므레 앞 헷 족속 소할의 아들 에브론의 밭에 있는 막벨라 굴에 장사하였으니"]],"창 26:1, 7":[["창 26:1","아브라함 때에 첫 흉년이 들었더니 그 땅에 또 흉년이 들매 이삭이 그랄로 가서 블레셋왕 아비멜렉에게 이르렀더니"],["창 26:7","그곳 사람들이 그 아내를 물으매 그가 말하기를 그는 나의 누이라 하였으니 리브가는 보기에 아리따우므로 그곳 백성이 리브가로 인하여 자기를 죽일까 하여 그는 나의 아내라 하기를 두려워함이었더라"]],"창 26:18, 23-25":[["창 26:18","그 아비 아브라함 때에 팠던 우물들을 다시 팠으니 이는 아브라함 죽은 후에 블레셋 사람이 그 우물들을 메웠음이라 이삭이 그 우물들의 이름을 그 아비의 부르던 이름으로 불렀더라"],["창 26:23","이삭이 거기서부터 브엘세바로 올라갔더니"],["창 26:24","그 밤에 여호와께서 그에게 나타나 가라사대 나는 네 아비 아브라함의 하나님이니 두려워 말라 내 종 아브라함을 위하여 내가 너와 함께 있어 네게 복을 주어 네 자손으로 번성케 하리라 하신지라"],["창 26:25","이삭이 그곳에 단을 쌓아 여호와의 이름을 부르고 거기 장막을 쳤더니 그 종들이 거기서도 우물을 팠더라"]],"창 27:1, 27-29":[["창 27:1","이삭이 나이 많아 눈이 어두워 잘 보지 못하더니 맏아들 에서를 불러 가로되 내 아들아 하매 그가 가로되 내가 여기 있나이다 하니"],["창 27:27","그가 가까이 가서 그에게 입맞추니 아비가 그 옷의 향취를 맡고 그에게 축복하여 가로되 내 아들의 향취는 여호와의 복 주신 밭의 향취로다"],["창 27:28","하나님은 하늘의 이슬과 땅의 기름짐이며 풍성한 곡식과 포도주로 네게 주시기를 원하노라"],["창 27:29","만민이 너를 섬기고 열국이 네게 굴복하리니 네가 형제들의 주가 되고 네 어미의 아들들이 네게 굴복하며 네게 저주하는 자는 저주를 받고 네게 축복하는 자는 복을 받기를 원하노라"]],"창 35:28-29":[["창 35:28","이삭의 나이 일백 팔십세라"],["창 35:29","이삭이 나이 많고 늙어 기운이 진하매 죽어 자기 열조에게로 돌아가니 그 아들 에서와 야곱이 그를 장사하였더라"]],"창 32:28":[["창 32:28","그 사람이 가로되 네 이름을 다시는 야곱이라 부를 것이 아니요 이스라엘이라 부를 것이니 이는 네가 하나님과 사람으로 더불어 겨루어 이기었음이니라"]],"창 25:21-26":[["창 25:21","이삭이 그 아내가 잉태하지 못하므로 그를 위하여 여호와께 간구하매 여호와께서 그 간구를 들으셨으므로 그 아내 리브가가 잉태하였더니"],["창 25:22","아이들이 그의 태 속에서 서로 싸우는지라 그가 가로되 이같으면 내가 어찌할꼬 하고 가서 여호와께 묻자온대"],["창 25:23","여호와께서 그에게 이르시되 두 국민이 네 태중에 있구나 두 민족이 네 복중에서부터 나누이리라 이 족속이 저 족속보다 강하겠고 큰 자는 어린 자를 섬기리라 하셨더라"],["창 25:24","그 해산 기한이 찬즉 태에 쌍동이가 있었는데"],["창 25:25","먼저 나온 자는 붉고 전신이 갖옷 같아서 이름을 에서라 하였고"],["창 25:26","후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라"]],"창 28:10; 31:41; 33:18; 35:27; 47:27":[["창 28:10","야곱이 브엘세바에서 떠나 하란으로 향하여 가더니"],["창 31:41","내가 외삼촌의 집에 거한 이 이십년에 외삼촌의 두 딸을 위하여 십 사년, 외삼촌의 양떼를 위하여 육년을 외삼촌을 봉사하였거니와 외삼촌께서 내 품값을 열번이나 변역하셨으니"],["창 33:18","야곱이 밧단아람에서부터 평안히 가나안 땅 세겜 성에 이르러 성 앞에 그 장막을 치고"],["창 35:27","야곱이 기럇아르바의 마므레로 가서 그 아비 이삭에게 이르렀으니 기럇아르바는 곧 아브라함과 이삭의 우거하던 헤브론이더라"],["창 47:27","이스라엘 족속이 애굽 고센 땅에 거하며 거기서 산업을 얻고 생육하며 번성하였더라"]],"창 35:22-26; 30:21":[["창 35:22","이스라엘이 그 땅에 유할 때에 르우벤이 가서 그 서모 빌하와 통간하매 이스라엘이 이를 들었더라 야곱의 아들은 열둘이라"],["창 35:23","레아의 소생은 야곱의 장자 르우벤과 그 다음 시므온과 레위와 유다와 잇사갈과 스불론이요"],["창 35:24","라헬의 소생은 요셉과 베냐민이며"],["창 35:25","라헬의 여종 빌하의 소생은 단과 납달리요"],["창 35:26","레아의 여종 실바의 소생은 갓과 아셀이니 이들은 야곱의 아들들이요 밧단아람에서 그에게 낳은 자더라"],["창 30:21","그 후에 그가 딸을 낳고 그 이름을 디나라 하였더라"]],"창 47:28; 50:13":[["창 47:28","야곱이 애굽 땅에 십 칠년을 거하였으니 그의 수가 일백 사십 칠세라"],["창 50:13","그를 가나안 땅으로 메어다가 마므레 앞 막벨라 밭 굴에 장사하였으니 이는 아브라함이 헷 족속 에브론에게 밭과 함께 사서 소유 매장지를 삼은 곳이더라"]],"창 28:13":[["창 28:13","또 본즉 여호와께서 그 위에 서서 가라사대 나는 여호와니 너의 조부 아브라함의 하나님이요 이삭의 하나님이라 너 누운 땅을 내가 너와 네 자손에게 주리니"]],"창 25:21":[["창 25:21","이삭이 그 아내가 잉태하지 못하므로 그를 위하여 여호와께 간구하매 여호와께서 그 간구를 들으셨으므로 그 아내 리브가가 잉태하였더니"]],"창 29:10, 23":[["창 29:10","야곱이 그 외삼촌 라반의 딸 라헬과 그 외삼촌의 양을 보고 나아가서 우물 아구에서 돌을 옮기고 외삼촌 라반의 양떼에게 물을 먹이고"],["창 29:23","저녁에 그 딸 레아를 야곱에게로 데려가매 야곱이 그에게로 들어가니라"]],"창 29:23":[["창 29:23","저녁에 그 딸 레아를 야곱에게로 데려가매 야곱이 그에게로 들어가니라"]],"창 29:28":[["창 29:28","야곱이 그대로 하여 그 칠일을 채우매 라반이 딸 라헬도 그에게 아내로 주고"]],"창 30:4, 9":[["창 30:4","그 시녀 빌하를 남편에게 첩으로 주매 야곱이 그에게로 들어갔더니"],["창 30:9","레아가 자기의 생산이 멈춤을 보고 그 시녀 실바를 취하여 야곱에게 주어 첩을 삼게 하였더니"]],"창 35:23":[["창 35:23","레아의 소생은 야곱의 장자 르우벤과 그 다음 시므온과 레위와 유다와 잇사갈과 스불론이요"]],"창 30:24; 35:24":[["창 30:24","그 이름을 요셉이라 하니 여호와는 다시 다른 아들을 내게 더하시기를 원하노라 함이었더라"],["창 35:24","라헬의 소생은 요셉과 베냐민이며"]],"창 35:18, 24":[["창 35:18","그가 죽기에 임하여 그 혼이 떠나려할 때에 아들의 이름은 베노니라 불렀으나 그 아비가 그를 베냐민이라 불렀더라"],["창 35:24","라헬의 소생은 요셉과 베냐민이며"]],"창 35:25":[["창 35:25","라헬의 여종 빌하의 소생은 단과 납달리요"]],"창 35:26":[["창 35:26","레아의 여종 실바의 소생은 갓과 아셀이니 이들은 야곱의 아들들이요 밧단아람에서 그에게 낳은 자더라"]],"창 30:21":[["창 30:21","그 후에 그가 딸을 낳고 그 이름을 디나라 하였더라"]],"창 48:5":[["창 48:5","내가 애굽으로 와서 네게 이르기 전에 애굽에서 네게 낳은 두 아들 에브라임과 므낫세는 내것이라 르우벤과 시므온처럼 내것이 될 것이요"]],"창 25:24-26":[["창 25:24","그 해산 기한이 찬즉 태에 쌍동이가 있었는데"],["창 25:25","먼저 나온 자는 붉고 전신이 갖옷 같아서 이름을 에서라 하였고"],["창 25:26","후에 나온 아우는 손으로 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 하였으며 리브가가 그들을 낳을 때에 이삭이 육십세이었더라"]],"창 25:29-34":[["창 25:29","야곱이 죽을 쑤었더니 에서가 들에서부터 돌아와서 심히 곤비하여"],["창 25:30","야곱에게 이르되 내가 곤비하니 그 붉은 것을 나로 먹게 하라 한지라 그러므로 에서의 별명은 에돔이더라"],["창 25:31","야곱이 가로되 형의 장자의 명분을 오늘날 내게 팔라"],["창 25:32","에서가 가로되 내가 죽게 되었으니 이 장자의 명분이 내게 무엇이 유익하리요"],["창 25:33","야곱이 가로되 오늘 내게 맹세하라 에서가 맹세하고 장자의 명분을 야곱에게 판지라"],["창 25:34","야곱이 떡과 팥죽을 에서에게 주매 에서가 먹으며 마시고 일어나서 갔으니 에서가 장자의 명분을 경홀히 여김이었더라"]],"창 27:18-19, 27":[["창 27:18","야곱이 아버지에게 나아가서 내 아버지여 하고 부른대 가로되 내가 여기 있노라 내 아들아 네가 누구냐"],["창 27:19","야곱이 아비에게 대답하되 나는 아버지의 맏아들 에서로소이다 아버지께서 내게 명하신대로 내가 하였사오니 청컨대 일어나 앉아서 내 사냥한 고기를 잡수시고 아버지의 마음껏 내게 축복하소서"],["창 27:27","그가 가까이 가서 그에게 입맞추니 아비가 그 옷의 향취를 맡고 그에게 축복하여 가로되 내 아들의 향취는 여호와의 복 주신 밭의 향취로다"]],"창 28:10-12, 19":[["창 28:10","야곱이 브엘세바에서 떠나 하란으로 향하여 가더니"],["창 28:11","한 곳에 이르러는 해가 진지라 거기서 유숙하려고 그곳의 한 돌을 취하여 베개하고 거기 누워 자더니"],["창 28:12","꿈에 본즉 사닥다리가 땅위에 섰는데 그 꼭대기가 하늘에 닿았고 또 본즉 하나님의 사자가 그 위에서 오르락 내리락하고"],["창 28:19","그곳 이름을 벧엘이라 하였더라 이 성의 본 이름은 루스더라"]],"창 29:20, 25-28":[["창 29:20","야곱이 라헬을 위하여 칠년 동안 라반을 봉사하였으나 그를 연애하는 까닭에 칠년을 수일 같이 여겼더라"],["창 29:25","야곱이 아침에 보니 레아라 라반에게 이르되 외삼촌이 어찌하여 내게 이같이 행하셨나이까 내가 라헬을 위하여 외삼촌께 봉사하지 아니하였나이까 외삼촌이 나를 속이심은 어찜이니이까"],["창 29:26","라반이 가로되 형보다 아우를 먼저 주는 것은 우리 지방에서 하지 아니하는 바이라"],["창 29:27","이를 위하여 칠일을 채우라 우리가 그도 네게 주리니 네가 그를 위하여 또 칠년을 내게 봉사할찌니라"],["창 29:28","야곱이 그대로 하여 그 칠일을 채우매 라반이 딸 라헬도 그에게 아내로 주고"]],"창 30:21-24; 31:41":[["창 30:21","그 후에 그가 딸을 낳고 그 이름을 디나라 하였더라"],["창 30:22","하나님이 라헬을 생각하신지라 하나님이 그를 들으시고 그 태를 여신고로"],["창 30:23","그가 잉태하여 아들을 낳고 가로되 하나님이 나의 부끄러움을 씻으셨다 하고"],["창 30:24","그 이름을 요셉이라 하니 여호와는 다시 다른 아들을 내게 더하시기를 원하노라 함이었더라"],["창 31:41","내가 외삼촌의 집에 거한 이 이십년에 외삼촌의 두 딸을 위하여 십 사년, 외삼촌의 양떼를 위하여 육년을 외삼촌을 봉사하였거니와 외삼촌께서 내 품값을 열번이나 변역하셨으니"]],"창 32:24, 28":[["창 32:24","야곱은 홀로 남았더니 어떤 사람이 날이 새도록 야곱과 씨름하다가"],["창 32:28","그 사람이 가로되 네 이름을 다시는 야곱이라 부를 것이 아니요 이스라엘이라 부를 것이니 이는 네가 하나님과 사람으로 더불어 겨루어 이기었음이니라"]],"창 33:4":[["창 33:4","에서가 달려와서 그를 맞아서 안고 목을 어긋맞기고 그와 입맞추고 피차 우니라"]],"창 35:18-19":[["창 35:18","그가 죽기에 임하여 그 혼이 떠나려할 때에 아들의 이름은 베노니라 불렀으나 그 아비가 그를 베냐민이라 불렀더라"],["창 35:19","라헬이 죽으매 에브랏 곧 베들레헴 길에 장사되었고"]],"창 37:33-34":[["창 37:33","아비가 그것을 알아보고 가로되 내 아들의 옷이라 악한 짐승이 그를 먹었도다 요셉이 정녕 찢겼도다 하고"],["창 37:34","자기 옷을 찢고 굵은 베로 허리를 묶고 오래도록 그 아들을 위하여 애통하니"]],"창 46:27; 47:7-9":[["창 46:27","애굽에서 요셉에게 낳은 아들이 두명이니 야곱의 집 사람으로 애굽에 이른 자의 도합이 칠십명이었더라"],["창 47:7","요셉이 자기 아비 야곱을 인도하여 바로 앞에 서게 하니 야곱이 바로에게 축복하매"],["창 47:8","바로가 야곱에게 묻되 네 연세가 얼마뇨"],["창 47:9","야곱이 바로에게 고하되 내 나그네 길의 세월이 일백 삼십년이니이다 나의 연세가 얼마 못되니 우리 조상의 나그네 길의 세월에 미치지 못하나 험악한 세월을 보내었나이다 하고"]],"창 48:5, 14; 49:28":[["창 48:5","내가 애굽으로 와서 네게 이르기 전에 애굽에서 네게 낳은 두 아들 에브라임과 므낫세는 내것이라 르우벤과 시므온처럼 내것이 될 것이요"],["창 48:14","이스라엘이 우수를 펴서 차자 에브라임의 머리에 얹고 좌수를 펴서 므낫세의 머리에 얹으니 므낫세는 장자라도 팔을 어긋맞겨 얹었더라"],["창 49:28","이들은 이스라엘의 십 이 지파라 이와 같이 그 아비가 그들에게 말하고 그들에게 축복하였으되 곧 그들 각인의 분량대로 축복하였더라"]],"창 41:45":[["창 41:45","그가 요셉의 이름을 사브낫바네아라 하고 또 온 제사장 보디베라의 딸 아스낫을 그에게 주어 아내를 삼게 하니라 요셉이 나가 애굽 온 땅을 순찰하니라"]],"창 30:22-24":[["창 30:22","하나님이 라헬을 생각하신지라 하나님이 그를 들으시고 그 태를 여신고로"],["창 30:23","그가 잉태하여 아들을 낳고 가로되 하나님이 나의 부끄러움을 씻으셨다 하고"],["창 30:24","그 이름을 요셉이라 하니 여호와는 다시 다른 아들을 내게 더하시기를 원하노라 함이었더라"]],"창 30:25":[["창 30:25","라헬이 요셉을 낳은 때에 야곱이 라반에게 이르되 나를 보내어 내 고향 내 본토로 가게 하시되"]],"창 41:41, 46":[["창 41:41","바로가 또 요셉에게 이르되 내가 너로 애굽 온 땅을 총리하게 하노라 하고"],["창 41:46","요셉이 애굽왕 바로 앞에 설 때에 삼십세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니"]],"창 50:26":[["창 50:26","요셉이 일백 십세에 죽으매 그들이 그의 몸에 향 재료를 넣고 애굽에서 입관하였더라"]],"출 13:19; 수 24:32":[["출 13:19","모세가 요셉의 해골을 취하였으니 이는 요셉이 이스라엘 자손으로 단단히 맹세케 하여 이르기를 하나님이 필연 너희를 권고하시리니 너희는 나의 해골을 여기서 가지고 나가라 하였음이었더라"],["수 24:32","이스라엘 자손이 애굽에서 이끌어 낸 요셉의 뼈를 세겜에 장사하였으니 이곳은 야곱이 세겜의 아비 하몰의 자손에게 금 일백개를 주고 산 땅이라 그것이 요셉 자손의 기업이 되었더라"]],"창 37:3":[["창 37:3","요셉은 노년에 얻은 아들이므로 이스라엘이 여러 아들보다 그를 깊이 사랑하여 위하여 채색옷을 지었더니"]],"창 35:18; 43:29":[["창 35:18","그가 죽기에 임하여 그 혼이 떠나려할 때에 아들의 이름은 베노니라 불렀으나 그 아비가 그를 베냐민이라 불렀더라"],["창 43:29","요셉이 눈을 들어 자기 어머니의 아들 자기 동생 베냐민을 보고 가로되 너희가 내게 말하던 너희 작은 동생이 이냐 그가 또 가로되 소자여 하나님이 네게 은혜 베푸시기를 원하노라"]],"창 41:51":[["창 41:51","요셉이 그 장자의 이름을 므낫세라 하였으니 하나님이 나로 나의 모든 고난과 나의 아비의 온 집 일을 잊어버리게 하셨다 함이요"]],"창 41:52":[["창 41:52","차자의 이름을 에브라임이라 하였으니 하나님이 나로 나의 수고한 땅에서 창성하게 하셨다 함이었더라"]],"창 50:23":[["창 50:23","에브라임의 자손 삼대를 보았으며 므낫세의 아들 마길의 아들들도 요셉의 슬하에서 양육되었더라"]],"대상 7:20, 27":[["대상 7:20","에브라임의 아들은 수델라요 그 아들은 베렛이요 그 아들은 다핫이요 그 아들은 엘르아다요 그 아들은 다핫이요"],["대상 7:27","그 아들은 눈이요 그 아들은 여호수아더라"]],"창 30:22-25":[["창 30:22","하나님이 라헬을 생각하신지라 하나님이 그를 들으시고 그 태를 여신고로"],["창 30:23","그가 잉태하여 아들을 낳고 가로되 하나님이 나의 부끄러움을 씻으셨다 하고"],["창 30:24","그 이름을 요셉이라 하니 여호와는 다시 다른 아들을 내게 더하시기를 원하노라 함이었더라"],["창 30:25","라헬이 요셉을 낳은 때에 야곱이 라반에게 이르되 나를 보내어 내 고향 내 본토로 가게 하시되"]],"창 37:3, 7, 9":[["창 37:3","요셉은 노년에 얻은 아들이므로 이스라엘이 여러 아들보다 그를 깊이 사랑하여 위하여 채색옷을 지었더니"],["창 37:7","우리가 밭에서 곡식을 묶더니 내 단은 일어서고 당신들의 단은 내 단을 둘러서서 절하더이다"],["창 37:9","요셉이 다시 꿈을 꾸고 그 형들에게 고하여 가로되 내가 또 꿈을 꾼즉 해와 달과 열 한 별이 내게 절하더이다 하니라"]],"창 37:2, 28":[["창 37:2","야곱의 약전이 이러하니라 요셉이 십 칠세의 소년으로서 그 형제와 함께 양을 칠 때에 그 아비의 첩 빌하와 실바의 아들들로 더불어 함께하였더니 그가 그들의 과실을 아비에게 고하더라"],["창 37:28","때에 미디안 사람 상고들이 지나는지라 그들이 요셉을 구덩이에서 끌어올리고 은 이십개에 그를 이스마엘 사람들에게 팔매 그 상고들이 요셉을 데리고 애굽으로 갔더라"]],"창 39:1, 4, 20":[["창 39:1","요셉이 이끌려 애굽에 내려가매 바로의 신하 시위대장 애굽 사람 보디발이 그를 그리로 데려간 이스마엘 사람의 손에서 그를 사니라"],["창 39:4","요셉이 그 주인에게 은혜를 입어 섬기매 그가 요셉으로 가정 총무를 삼고 자기 소유를 다 그 손에 위임하니"],["창 39:20","이에 요셉의 주인이 그를 잡아 옥에 넣으니 그 옥은 왕의 죄수를 가두는 곳이었더라 요셉이 옥에 갇혔으나"]],"창 40:8, 21-22":[["창 40:8","그들이 그에게 이르되 우리가 꿈을 꾸었으나 이를 해석할 자가 없도다 요셉이 그들에게 이르되 해석은 하나님께 있지 아니하니이까 청컨대 내게 고하소서"],["창 40:21","바로의 술 맡은 관원장은 전직을 회복하매 그가 잔을 바로의 손에 받들어 드렸고"],["창 40:22","떡 굽는 관원장은 매달리니 요셉이 그들에게 해석함과 같이 되었으나"]],"창 41:25-26, 41, 46":[["창 41:25","요셉이 바로에게 고하되 바로의 꿈은 하나이라 하나님이 그 하실 일을 바로에게 보이심이니이다"],["창 41:26","일곱 좋은 암소는 일곱해요 일곱 좋은 이삭도 일곱해니 그 꿈은 하나이라"],["창 41:41","바로가 또 요셉에게 이르되 내가 너로 애굽 온 땅을 총리하게 하노라 하고"],["창 41:46","요셉이 애굽왕 바로 앞에 설 때에 삼십세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니"]],"창 41:48, 56-57":[["창 41:48","요셉이 애굽 땅에 있는 그 칠년 곡물을 거두어 각성에 저축하되 각성 주위의 밭의 곡물을 그 성중에 저장하매"],["창 41:56","온 지면에 기근이 있으매 요셉이 모든 창고를 열고 애굽 백성에게 팔쌔 애굽 땅에 기근이 심하며"],["창 41:57","각국 백성도 양식을 사려고 애굽으로 들어와 요셉에게 이르렀으니 기근이 온 세상에 심함이었더라"]],"창 45:1-3":[["창 45:1","요셉이 시종하는 자들 앞에서 그 정을 억제하지 못하여 소리질러 모든 사람을 자기에게서 물러가라 하고 그 형제에게 자기를 알리니 때에 그와 함께한 자가 없었더라"],["창 45:2","요셉이 방성대곡하니 애굽 사람에게 들리며 바로의 궁중에 들리더라"],["창 45:3","요셉이 그 형들에게 이르되 나는 요셉이라 내 아버지께서 아직 살아 계시니이까 형들이 그 앞에서 놀라서 능히 대답하지 못하는지라"]],"창 45:9-10; 47:11":[["창 45:9","당신들은 속히 아버지께로 올라가서 고하기를 아버지의 아들 요셉의 말에 하나님이 나를 애굽 전국의 주로 세우셨으니 내게로 지체말고 내려오사"],["창 45:10","아버지의 아들들과 아버지의 손자들과 아버지의 양과 소와 모든 소유가 고센 땅에 있어서 나와 가깝게 하소서"],["창 47:11","요셉이 바로의 명대로 그 아비와 형들에게 거할 곳을 주되 애굽의 좋은 땅 라암세스를 그들에게 주어 기업을 삼게 하고"]],"창 50:19-20":[["창 50:19","요셉이 그들에게 이르되 두려워 마소서 내가 하나님을 대신하리이까"],["창 50:20","당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 만민의 생명을 구원하게 하시려 하셨나니"]],"출 28:1; 29:9":[["출 28:1","너는 이스라엘 자손 중 네 형 아론과 그 아들들 곧 나답과 아비후와 엘르아살과 이다말을 그와 함께 네게로 나아오게 하여 나를 섬기는 제사장 직분을 행하게 하되"],["출 29:9","아론과 그 아들들에게 띠를 띠우며 관을 씌워서 제사장의 직분을 그들에게 맡겨 영원한 규례가 되게 하라 너는 이같이 아론과 그 아들들에게 위임하여 거룩하게 할찌니라"]],"민 33:38-39":[["민 33:38","이스라엘 자손이 애굽 땅에서 나온지 사십년 오월 일일에 제사장 아론이 여호와의 명으로 호르산에 올라가 거기서 죽었으니"],["민 33:39","아론이 호르산에서 죽던 때에 나이 일백 이십 삼세이었더라"]],"출 15:20":[["출 15:20","아론의 누이 선지자 미리암이 손에 소고를 잡으매 모든 여인도 그를 따라 나오며 소고를 잡고 춤추니"]],"출 6:23":[["출 6:23","아론이 암미나답의 딸 나손의 누이 엘리세바를 아내로 취하였고 그가 나답과 아비후와 엘르아살과 이다말을 낳았으며"]],"출 6:23; 레 10:1-2":[["출 6:23","아론이 암미나답의 딸 나손의 누이 엘리세바를 아내로 취하였고 그가 나답과 아비후와 엘르아살과 이다말을 낳았으며"],["레 10:1","아론의 아들 나답과 아비후가 각기 향로를 가져다가 여호와의 명하시지 않은 다른 불을 담아 여호와 앞에 분향하였더니"],["레 10:2","불이 여호와 앞에서 나와 그들을 삼키매 그들이 여호와 앞에서 죽은지라"]],"출 6:23; 민 20:28":[["출 6:23","아론이 암미나답의 딸 나손의 누이 엘리세바를 아내로 취하였고 그가 나답과 아비후와 엘르아살과 이다말을 낳았으며"],["민 20:28","모세가 아론의 옷을 벗겨 그 아들 엘르아살에게 입히매 아론이 그 산꼭대기에서 죽으니라 모세와 엘르아살이 산에서 내려오니"]],"출 6:25":[["출 6:25","아론의 아들 엘르아살이 부디엘의 딸 중에서 아내를 취하였고 그가 비느하스를 낳았으니 이들은 레위 사람의 조상을 따라 가족의 어른들이라"]],"눅 1:5":[["눅 1:5","유대 왕 헤롯 때에 아비야 반열에 제사장 하나가 있으니 이름은 사가랴요 그 아내는 아론의 자손이니 이름은 엘리사벳이라"]],"출 6:20; 7:7":[["출 6:20","아므람이 그 아비의 누이 요게벳을 아내로 취하였고 그가 아론과 모세를 낳았으며 아므람의 수는 일백 삼십 칠세이었으며"],["출 7:7","그들이 바로에게 말할 때에 모세는 팔십세이었고 아론은 팔십 삼세이었더라"]],"출 4:14-16":[["출 4:14","여호와께서 모세를 향하여 노를 발하시고 가라사대 레위 사람 네 형 아론이 있지 아니하뇨 그의 말 잘함을 내가 아노라 그가 너를 만나러 나오나니 그가 너를 볼 때에 마음에 기뻐할 것이라"],["출 4:15","너는 그에게 말하고 그 입에 말을 주라 내가 네 입과 그의 입에 함께 있어서 너의 행할 일을 가르치리라"],["출 4:16","그가 너를 대신하여 백성에게 말할 것이니 그는 네 입을 대신할 것이요 너는 그에게 하나님 같이 되리라"]],"출 7:10":[["출 7:10","모세와 아론이 바로에게 가서 여호와의 명하신대로 행하여 아론이 바로와 그 신하 앞에 지팡이를 던졌더니 뱀이 된지라"]],"출 12:50-51":[["출 12:50","온 이스라엘 자손이 이와 같이 행하되 여호와께서 모세와 아론에게 명하신대로 행하였으며"],["출 12:51","그 같은 날에 여호와께서 이스라엘 자손을 그 군대대로 애굽 땅에서 인도하여 내셨더라"]],"출 17:12":[["출 17:12","모세의 팔이 피곤하매 그들이 돌을 가져다가 모세의 아래에 놓아 그로 그 위에 앉게 하고 아론과 훌이 하나는 이편에서, 하나는 저편에서 모세의 손을 붙들어 올렸더니 그 손이 해가 지도록 내려오지 아니한지라"]],"출 32:1-4":[["출 32:1","백성이 모세가 산에서 내려옴이 더딤을 보고 모여 아론에게 이르러 가로되 일어나라 우리를 인도할 신을 우리를 위하여 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어찌 되었는지 알지 못함이니라"],["출 32:2","아론이 그들에게 이르되 너희 아내와 자녀의 귀의 금고리를 빼어 내게로 가져 오라"],["출 32:3","모든 백성이 그 귀에서 금고리를 빼어 아론에게로 가져 오매"],["출 32:4","아론이 그들의 손에서 그 고리를 받아 부어서 각도로 새겨 송아지 형상을 만드니 그들이 말하되 이스라엘아 이는 너희를 애굽 땅에서 인도하여 낸 너희 신이로다 하는지라"]],"레 8:12; 9:22-23":[["레 8:12","또 관유로 아론의 머리에 부어 발라 거룩하게 하고"],["레 9:22","아론이 백성을 향하여 손을 들어 축복함으로 속죄제와 번제와 화목제를 필하고 내려오니라"],["레 9:23","모세와 아론이 회막에 들어갔다가 나와서 백성에게 축복하매 여호와의 영광이 온 백성에게 나타나며"]],"레 10:1-2":[["레 10:1","아론의 아들 나답과 아비후가 각기 향로를 가져다가 여호와의 명하시지 않은 다른 불을 담아 여호와 앞에 분향하였더니"],["레 10:2","불이 여호와 앞에서 나와 그들을 삼키매 그들이 여호와 앞에서 죽은지라"]],"민 17:8":[["민 17:8","이튿날 모세가 증거의 장막에 들어가 본즉 레위 집을 위하여 낸 아론의 지팡이에 움이 돋고 순이 나고 꽃이 피어서 살구 열매가 열렸더라"]],"민 20:12, 24":[["민 20:12","여호와께서 모세와 아론에게 이르시되 너희가 나를 믿지 아니하고 이스라엘 자손의 목전에 나의 거룩함을 나타내지 아니한고로 너희는 이 총회를 내가 그들에게 준 땅으로 인도하여 들이지 못하리라 하시니라"],["민 20:24","아론은 그 열조에게로 돌아가고 내가 이스라엘 자손에게 준 땅에는 들어가지 못하리니 이는 너희가 므리바 물에서 내 말을 거역한 연고니라"]],"민 20:28; 33:38-39":[["민 20:28","모세가 아론의 옷을 벗겨 그 아들 엘르아살에게 입히매 아론이 그 산꼭대기에서 죽으니라 모세와 엘르아살이 산에서 내려오니"],["민 33:38","이스라엘 자손이 애굽 땅에서 나온지 사십년 오월 일일에 제사장 아론이 여호와의 명으로 호르산에 올라가 거기서 죽었으니"],["민 33:39","아론이 호르산에서 죽던 때에 나이 일백 이십 삼세이었더라"]],"민 13:16":[["민 13:16","이는 모세가 땅을 탐지하러 보낸 자들의 이름이라 모세가 눈의 아들 호세아를 여호수아라 칭하였더라"]],"민 13:8, 16":[["민 13:8","에브라임 지파에서는 눈의 아들 호세아요"],["민 13:16","이는 모세가 땅을 탐지하러 보낸 자들의 이름이라 모세가 눈의 아들 호세아를 여호수아라 칭하였더라"]],"출 33:11; 신 34:9":[["출 33:11","사람이 그 친구와 이야기함 같이 여호와께서는 모세와 대면하여 말씀하시며 모세는 진으로 돌아오나 그 수종자 눈의 아들 청년 여호수아는 회막을 떠나지 아니하니라"],["신 34:9","모세가 눈의 아들 여호수아에게 안수하였으므로 그에게 지혜의 신이 충만하니 이스라엘 자손이 여호와께서 모세에게 명하신대로 여호수아의 말을 순종하였더라"]],"수 19:49-50":[["수 19:49","이스라엘 자손이 그 경계를 따라서 기업의 땅 나누기를 마치고 자기들 중에서 눈의 아들 여호수아에게 기업을 주었으되"],["수 19:50","곧 여호와의 명령대로 여호수아의 구한 성읍 에브라임 산지 딤낫 세라를 주매 여호수아가 그 성읍을 중건하고 거기 거하였었더라"]],"수 24:29-30":[["수 24:29","이 일 후에 여호와의 종 눈의 아들 여호수아가 일백 십세에 죽으매"],["수 24:30","무리가 그를 그의 기업의 경내 딤낫 세라에 장사하였으니 딤낫 세라는 에브라임 산지 가아스산 북이었더라"]],"민 13:8":[["민 13:8","에브라임 지파에서는 눈의 아들 호세아요"]],"출 17:8-10, 13":[["출 17:8","때에 아말렉이 이르러 이스라엘과 르비딤에서 싸우니라"],["출 17:9","모세가 여호수아에게 이르되 우리를 위하여 사람들을 택하여 나가서 아말렉과 싸우라 내일 내가 하나님의 지팡이를 손에 잡고 산꼭대기에 서리라"],["출 17:10","여호수아가 모세의 말대로 행하여 아말렉과 싸우고 모세와 아론과 훌은 산꼭대기에 올라가서"],["출 17:13","여호수아가 칼날로 아말렉과 그 백성을 쳐서 파하니라"]],"출 24:13; 33:11":[["출 24:13","모세가 그 종자 여호수아와 함께 일어나 하나님의 산으로 올라가며"],["출 33:11","사람이 그 친구와 이야기함 같이 여호와께서는 모세와 대면하여 말씀하시며 모세는 진으로 돌아오나 그 수종자 눈의 아들 청년 여호수아는 회막을 떠나지 아니하니라"]],"민 14:6-9":[["민 14:6","그 땅을 탐지한 자 중 눈의 아들 여호수아와 여분네의 아들 갈렙이 그 옷을 찢고"],["민 14:7","이스라엘 자손의 온 회중에게 일러 가로되 우리가 두루 다니며 탐지한 땅은 심히 아름다운 땅이라"],["민 14:8","여호와께서 우리를 기뻐하시면 우리를 그 땅으로 인도하여 들이시고 그 땅을 우리에게 주시리라 이는 과연 젖과 꿀이 흐르는 땅이니라"],["민 14:9","오직 여호와를 거역하지 말라 또 그 땅 백성을 두려워하지 말라 그들은 우리 밥이라 그들의 보호자는 그들에게서 떠났고 여호와는 우리와 함께 하시느니라 그들을 두려워 말라 하나"]],"민 27:18, 22-23":[["민 27:18","여호와께서 모세에게 이르시되 눈의 아들 여호수아는 신에 감동된 자니 너는 데려다가 그에게 안수하고"],["민 27:22","모세가 여호와께서 자기에게 명하신대로 하여 여호수아를 데려다가 제사장 엘르아살과 온 회중 앞에 세우고"],["민 27:23","그에게 안수하여 위탁하되 여호와께서 자기에게 명하신대로 하였더라"]],"수 1:1-2; 3:17":[["수 1:1","여호와의 종 모세가 죽은 후에 여호와께서 모세의 시종 눈의 아들 여호수아에게 일러 가라사대"],["수 1:2","내 종 모세가 죽었으니 이제 너는 이 모든 백성으로 더불어 일어나 이 요단을 건너 내가 그들 곧 이스라엘 자손에게 주는 땅으로 가라"],["수 3:17","여호와의 언약궤를 멘 제사장들은 요단 가운데 마른 땅에 굳게 섰고 온 이스라엘 백성은 마른 땅으로 행하여 요단을 건너니라"]],"수 7:4; 8:19":[["수 7:4","백성중 삼천명쯤 그리로 올라갔다가 아이 사람 앞에서 도망하니"],["수 8:19","그 손을 드는 순간에 복병이 그 처소에서 급히 일어나 성읍에 달려 들어가서 점령하고 곧 성읍에 불을 놓았더라"]],"수 10:12-13":[["수 10:12","여호와께서 아모리 사람을 이스라엘 자손에게 붙이시던 날에 여호수아가 여호와께 고하되 이스라엘 목전에서 가로되 태양아 너는 기브온 위에 머무르라 달아 너도 아얄론 골짜기에 그리할찌어다 하매"],["수 10:13","태양이 머물고 달이 그치기를 백성이 그 대적에게 원수를 갚도록 하였느니라 야살의 책에 기록되기를 태양이 중천에 머물러서 거의 종일토록 속히 내려가지 아니하였다 하지 아니하였느냐"]],"수 14:1":[["수 14:1","이스라엘 자손이 가나안 땅에서 취한 기업 곧 제사장 엘르아살과 눈의 아들 여호수아와 이스라엘 자손 지파의 족장들이 분배한 것이 이 아래와 같으니라"]],"수 24:1, 15, 25":[["수 24:1","여호수아가 이스라엘 모든 지파를 세겜에 모으고 이스라엘 장로들과 그 두령들과 재판장들과 유사들을 부르매 그들이 하나님 앞에 보인지라"],["수 24:15","만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 열조가 강 저편에서 섬기던 신이든지 혹 너희의 거하는 땅 아모리 사람의 신이든지 너희 섬길 자를 오늘날 택하라 오직 나와 내 집은 여호와를 섬기겠노라"],["수 24:25","그 날에 여호수아가 세겜에서 백성으로 더불어 언약을 세우고 그들을 위하여 율례와 법도를 베풀었더라"]],"삿 4:4":[["삿 4:4","그 때에 랍비돗의 아내 여선지 드보라가 이스라엘의 사사가 되었는데"]],"삿 4:5":[["삿 4:5","그는 에브라임 산지 라마와 벧엘 사이 드보라의 종려나무 아래 거하였고 이스라엘 자손은 그에게 나아가 재판을 받더라"]],"삿 5:31":[["삿 5:31","여호와여 주의 대적은 다 이와 같이 망하게 하시고 주를 사랑하는 자는 해가 힘있게 돋음 같게 하시옵소서 하니라 그 땅이 사십년 동안 태평하였더라"]],"삿 4:2-3":[["삿 4:2","여호와께서 하솔에 도읍한 가나안 왕 야빈의 손에 그들을 파셨는데 그 군대 장관은 이방 하로셋에 거하는 시스라요"],["삿 4:3","야빈왕은 철병거 구백승이 있어서 이십년 동안 이스라엘 자손을 심히 학대한고로 이스라엘 자손이 여호와께 부르짖었더라"]],"삿 4:4-5":[["삿 4:4","그 때에 랍비돗의 아내 여선지 드보라가 이스라엘의 사사가 되었는데"],["삿 4:5","그는 에브라임 산지 라마와 벧엘 사이 드보라의 종려나무 아래 거하였고 이스라엘 자손은 그에게 나아가 재판을 받더라"]],"삿 4:6":[["삿 4:6","드보라가 보내어 아비노암의 아들 바락을 납달리 게데스에서 불러다가 그에게 이르되 이스라엘 하나님 여호와께서 이같이 명하지 아니하셨느냐 이르시기를 너는 납달리 자손과 스불론 자손 일만명을 거느리고 다볼산으로 가라"]],"삿 4:8-9":[["삿 4:8","바락이 그에게 이르되 당신이 나와 함께 가면 내가 가려니와 당신이 나와 함께 가지 아니하면 나는 가지 않겠노라"],["삿 4:9","가로되 내가 반드시 너와 함께 가리라 그러나 네가 이제 가는 일로는 영광을 얻지 못하리니 이는 여호와께서 시스라를 여인의 손에 파실것임이니라 하고 드보라가 일어나 바락과 함께 게데스로 가니라"]],"삿 4:13-15":[["삿 4:13","시스라가 모든 병거 곧 철병거 구백승과 자기와 함께 있는 온 군사를 이방 하로셋에서부터 기손강으로 모은지라"],["삿 4:14","드보라가 바락에게 이르되 일어나라 이는 여호와께서 시스라를 네 손에 붙이신 날이라 여호와께서 너의 앞서 행하지 아니하시느냐 이에 바락이 일만명을 거느리고 다볼산에서 내려가니"],["삿 4:15","여호와께서 바락의 앞에서 시스라와 그 모든 병거와 그 온 군대를 칼날로 쳐서 패하게 하시매 시스라가 병거에서 내려 도보로 도망한지라"]],"삿 4:21":[["삿 4:21","그가 곤비하여 깊이 잠든지라 헤벨의 아내 야엘이 장막 말뚝을 취하고 손에 방망이를 들고 그에게로 가만히 가서 말뚝을 그 살쩍에 박으매 말뚝이 꿰뚫고 땅에 박히니 시스라가 기절하여 죽으니라"]],"삿 5:1, 7":[["삿 5:1","이 날에 드보라와 아비노암의 아들 바락이 노래하여 가로되"],["삿 5:7","이스라엘에 관원이 그치고 그쳤더니 나 드보라가 일어났고 내가 일어나서 이스라엘의 어미가 되었도다"]],"삿 6:31-32":[["삿 6:31","요아스가 자기를 둘러선 모든 자에게 이르되 너희가 바알을 위하여 쟁론하느냐 너희가 바알을 구원하겠느냐 그를 위하여 쟁론하는 자는 이 아침에 죽음을 당하리라 바알이 과연 신일찐대 그 단을 훼파하였은즉 스스로 쟁론할 것이니라 하니라"],["삿 6:32","그 날에 기드온을 여룹바알이라 하였으니 이는 그가 바알의 단을 훼파하였은즉 바알이 더불어 쟁론할 것이라 함이었더라"]],"삿 6:11, 15":[["삿 6:11","여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니"],["삿 6:15","기드온이 그에게 대답하되 주여 내가 무엇으로 이스라엘을 구원하리이까 보소서 나의 집은 므낫세 중에 극히 약하고 나는 내 아비 집에서 제일 작은 자니이다"]],"삿 6:11":[["삿 6:11","여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니"]],"삿 8:28":[["삿 8:28","미디안이 이스라엘 자손 앞에 복종하여 다시는 그 머리를 들지 못하였으므로 기드온의 사는날 동안 사십년에 그 땅이 태평하였더라"]],"삿 8:32":[["삿 8:32","요아스의 아들 기드온이 나이 많아 죽으매 아비에셀 사람의 오브라에 있는 그의 아비 요아스의 묘실에 장사하였더라"]],"삿 6:11, 29":[["삿 6:11","여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니"],["삿 6:29","서로 물어 가로되 이것이 누구의 소위인고 하고 그들이 캐어 물은 후에 가로되 요아스의 아들 기드온이 이를 행하였도다 하고"]],"삿 8:30":[["삿 8:30","기드온이 아내가 많으므로 몸에서 낳은 아들이 칠십인이었고"]],"삿 8:31":[["삿 8:31","세겜에 있는 첩도 아들을 낳았으므로 그 이름을 아비멜렉이라 하였더라"]],"삿 8:20":[["삿 8:20","그 장자 여델에게 이르되 일어나 그들을 죽이라 하였으나 그 소년이 칼을 빼지 못하였으니 이는 아직 어려서 두려워함이었더라"]],"삿 8:31; 9:5":[["삿 8:31","세겜에 있는 첩도 아들을 낳았으므로 그 이름을 아비멜렉이라 하였더라"],["삿 9:5","오브라에 있는 그 아비의 집으로 가서 여룹바알의 아들 곧 자기 형제 칠십인을 한 반석 위에서 죽였으되 오직 여룹바알의 말째 아들 요담은 스스로 숨었으므로 남으니라"]],"삿 9:5":[["삿 9:5","오브라에 있는 그 아비의 집으로 가서 여룹바알의 아들 곧 자기 형제 칠십인을 한 반석 위에서 죽였으되 오직 여룹바알의 말째 아들 요담은 스스로 숨었으므로 남으니라"]],"삿 6:1, 3-4":[["삿 6:1","이스라엘 자손이 또 여호와의 목전에 악을 행하였으므로 여호와께서 칠년 동안 그들을 미디안의 손에 붙이시니"],["삿 6:3","이스라엘이 파종한 때면 미디안 사람, 아말렉 사람, 동방 사람이 치러 올라와서"],["삿 6:4","진을 치고 가사에 이르도록 토지 소산을 멸하여 이스라엘 가운데 식물을 남겨두지 아니하며 양이나 소나 나귀도 남기지 아니하니"]],"삿 6:11-12":[["삿 6:11","여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니"],["삿 6:12","여호와의 사자가 기드온에게 나타나 이르되 큰 용사여 여호와께서 너와 함께 계시도다"]],"삿 6:27, 32":[["삿 6:27","이에 기드온이 종 열을 데리고 여호와의 말씀하신대로 행하되 아비의 가족과 그 성읍 사람들을 두려워하므로 이 일을 감히 백주에 행하지 못하고 밤에 행하니라"],["삿 6:32","그 날에 기드온을 여룹바알이라 하였으니 이는 그가 바알의 단을 훼파하였은즉 바알이 더불어 쟁론할 것이라 함이었더라"]],"삿 6:37-40":[["삿 6:37","보소서 내가 양털 한 뭉치를 타작마당에 두리니 이슬이 양털에만 있고 사면 땅은 마르면 주께서 이미 말씀하심 같이 내 손으로 이스라엘을 구원하실줄 내가 알겠나이다 하였더니"],["삿 6:38","그대로 된지라 이튿날 기드온이 일찌기 일어나서 양털을 취하여 이슬을 짜니 물이 그릇에 가득하더라"],["삿 6:39","기드온이 또 하나님께 여짜오되 주여 내게 진노하지 마옵소서 내가 이번만 말하리이다 구하옵나니 나로 다시 한번 양털로 시험하게 하소서 양털만 마르고 사면 땅에는 다 이슬이 있게 하옵소서 하였더니"],["삿 6:40","이 밤에 하나님이 그대로 행하시니 곧 양털만 마르고 사면 땅에는 다 이슬이 있었더라"]],"삿 7:3, 6-7":[["삿 7:3","이제 너는 백성의 귀에 고하여 이르기를 누구든지 두려워서 떠는 자여든 길르앗산에서 떠나 돌아가라 하라 하시니 이에 돌아간 백성이 이만 이천명이요 남은 자가 일만명이었더라"],["삿 7:6","손으로 움켜 입에 대고 핥는 자의 수는 삼백명이요 그 외의 백성은 다 무릎을 꿇고 물을 마신지라"],["삿 7:7","여호와께서 기드온에게 이르시되 내가 이 물을 핥아 먹은 삼백명으로 너희를 구원하며 미디안 사람을 네 손에 붙이리니 남은 백성은 각각 그 처소로 돌아갈 것이니라 하시니"]],"삿 7:20-22":[["삿 7:20","세 대가 나팔을 불며 항아리를 부수고 좌수에 횃불을 들고 우수에 나팔을 들어 불며 외쳐 가로되 여호와와 기드온의 칼이여 하고"],["삿 7:21","각기 당처에 서서 그 진을 사면으로 에워싸매 그 온 적군이 달음질하고 부르짖으며 도망하였는데"],["삿 7:22","삼백명이 나팔을 불 때에 여호와께서 그 온 적군으로 동무끼리 칼날로 치게 하시므로 적군이 도망하여 스레라의 벧 싯다에 이르고 또 답밧에 가까운 아벨므홀라의 경계에 이르렀으며"]],"삿 8:12, 21":[["삿 8:12","세바와 살문나가 도망하는지라 기드온이 추격하여 미디안 두 왕 세바와 살문나를 사로잡고 그 온 군대를 파하니라"],["삿 8:21","세바와 살문나가 가로되 네가 일어나 우리를 치라 대저 사람이 어떠하면 그 힘도 그러하니라 기드온이 일어나서 세바와 살문나를 죽이고 그 약대 목에 꾸몄던 새 달 형상의 장식을 취하니라"]],"삿 8:22-23":[["삿 8:22","때에 이스라엘 사람들이 기드온에게 이르되 당신이 우리를 미디안의 손에서 구원하셨으니 당신과 당신의 아들과 당신의 손자가 우리를 다스리소서"],["삿 8:23","기드온이 그들에게 이르되 내가 너희를 다스리지 아니하겠고 나의 아들도 너희를 다스리지 아니할 것이요 여호와께서 너희를 다스리시리라"]],"삿 8:24, 27":[["삿 8:24","기드온이 또 그들에게 이르되 내가 너희에게 한 일을 청구하노니 너희는 각기 탈취한 귀고리를 내게 줄찌니라 하니 그 대적은 이스마엘 사람이므로 금 귀고리가 있었음이라"],["삿 8:27","기드온이 그 금으로 에봇 하나를 만들어서 자기의 성읍 오브라에 두었더니 온 이스라엘이 그것을 음란하게 위하므로 그것이 기드온과 그 집에 올무가 되니라"]],"룻 1:4":[["룻 1:4","그들은 모압 여자 중에서 아내를 취하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 거기 거한지 십년 즈음에"]],"룻 1:1":[["룻 1:1","사사들의 치리하던 때에 그 땅에 흉년이 드니라 유다 베들레헴에 한 사람이 그 아내와 두 아들을 데리고 모압 지방에 가서 우거하였는데"]],"룻 1:22":[["룻 1:22","나오미가 모압 지방에서 그 자부 모압 여인 룻과 함께 돌아왔는데 그들이 보리 추수 시작할 때에 베들레헴에 이르렀더라"]],"룻 4:17":[["룻 4:17","그 이웃 여인들이 그에게 이름을 주되 나오미가 아들을 낳았다 하여 그 이름을 오벳이라 하였는데 그는 다윗의 아비인 이새의 아비였더라"]],"룻 1:2":[["룻 1:2","그 사람의 이름은 엘리멜렉이요 그 아내의 이름은 나오미요 그 두 아들의 이름은 말론과 기룐이니 유다 베들레헴 에브랏 사람들이더라 그들이 모압 지방에 들어가서 거기 유하더니"]],"룻 1:2-4":[["룻 1:2","그 사람의 이름은 엘리멜렉이요 그 아내의 이름은 나오미요 그 두 아들의 이름은 말론과 기룐이니 유다 베들레헴 에브랏 사람들이더라 그들이 모압 지방에 들어가서 거기 유하더니"],["룻 1:3","나오미의 남편 엘리멜렉이 죽고 나오미와 그 두 아들이 남았으며"],["룻 1:4","그들은 모압 여자 중에서 아내를 취하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 거기 거한지 십년 즈음에"]],"룻 1:5; 4:10":[["룻 1:5","말론과 기룐 두 사람이 다 죽고 그 여인은 두 아들과 남편의 뒤에 남았더라"],["룻 4:10","또 말론의 아내 모압 여인 룻을 사서 나의 아내로 취하고 그 죽은 자의 기업을 그 이름으로 잇게 하여 그 이름이 그 형제 중과 그곳 성문에서 끊어지지 않게 함에 너희가 오늘날 증인이 되었느니라"]],"룻 1:4, 14":[["룻 1:4","그들은 모압 여자 중에서 아내를 취하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 거기 거한지 십년 즈음에"],["룻 1:14","그들이 소리를 높여 다시 울더니 오르바는 그 시모에게 입맞추되 룻은 그를 붙좇았더라"]],"룻 4:13":[["룻 4:13","이에 보아스가 룻을 취하여 아내를 삼고 그와 동침하였더니 여호와께서 그로 잉태케 하시므로 그가 아들을 낳은지라"]],"룻 4:17, 22":[["룻 4:17","그 이웃 여인들이 그에게 이름을 주되 나오미가 아들을 낳았다 하여 그 이름을 오벳이라 하였는데 그는 다윗의 아비인 이새의 아비였더라"],["룻 4:22","오벳은 이새를 낳았고 이새는 다윗을 낳았더라"]],"마 1:5, 16":[["마 1:5","살몬은 라합에게서 보아스를 낳고 보아스는 룻에게서 오벳을 낳고 오벳은 이새를 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"룻 1:1-4; 4:10":[["룻 1:1","사사들의 치리하던 때에 그 땅에 흉년이 드니라 유다 베들레헴에 한 사람이 그 아내와 두 아들을 데리고 모압 지방에 가서 우거하였는데"],["룻 1:2","그 사람의 이름은 엘리멜렉이요 그 아내의 이름은 나오미요 그 두 아들의 이름은 말론과 기룐이니 유다 베들레헴 에브랏 사람들이더라 그들이 모압 지방에 들어가서 거기 유하더니"],["룻 1:3","나오미의 남편 엘리멜렉이 죽고 나오미와 그 두 아들이 남았으며"],["룻 1:4","그들은 모압 여자 중에서 아내를 취하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 거기 거한지 십년 즈음에"],["룻 4:10","또 말론의 아내 모압 여인 룻을 사서 나의 아내로 취하고 그 죽은 자의 기업을 그 이름으로 잇게 하여 그 이름이 그 형제 중과 그곳 성문에서 끊어지지 않게 함에 너희가 오늘날 증인이 되었느니라"]],"룻 1:3-5":[["룻 1:3","나오미의 남편 엘리멜렉이 죽고 나오미와 그 두 아들이 남았으며"],["룻 1:4","그들은 모압 여자 중에서 아내를 취하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 거기 거한지 십년 즈음에"],["룻 1:5","말론과 기룐 두 사람이 다 죽고 그 여인은 두 아들과 남편의 뒤에 남았더라"]],"룻 1:14, 16-17":[["룻 1:14","그들이 소리를 높여 다시 울더니 오르바는 그 시모에게 입맞추되 룻은 그를 붙좇았더라"],["룻 1:16","룻이 가로되 나로 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 유숙하시는 곳에서 나도 유숙하겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니"],["룻 1:17","어머니께서 죽으시는 곳에서 나도 죽어 거기 장사될 것이라 만일 내가 죽는 일 외에 어머니와 떠나면 여호와께서 내게 벌을 내리시고 더 내리시기를 원하나이다"]],"룻 2:3, 11-12":[["룻 2:3","룻이 가서 베는 자를 따라 밭에서 이삭을 줍는데 우연히 엘리멜렉의 친족 보아스에게 속한 밭에 이르렀더라"],["룻 2:11","보아스가 그에게 대답하여 가로되 네 남편이 죽은 후로 네가 시모에게 행한 모든 것과 네 부모와 고국을 떠나 전에 알지 못하던 백성에게로 온 일이 내게 분명히 들렸느니라"],["룻 2:12","여호와께서 네 행한 일을 보응하시기를 원하며 이스라엘의 하나님 여호와께서 그 날개 아래 보호를 받으러 온 네게 온전한 상 주시기를 원하노라"]],"룻 3:7-9":[["룻 3:7","보아스가 먹고 마시고 마음이 즐거워서 가서 노적가리 곁에 눕는지라 룻이 가만히 가서 그 발치 이불을 들고 거기 누웠더라"],["룻 3:8","밤중에 그 사람이 놀라 몸을 돌이켜 본즉 한 여인이 자기 발치에 누웠는지라"],["룻 3:9","가로되 네가 누구뇨 대답하되 나는 당신의 시녀 룻이오니 당신의 옷자락으로 시녀를 덮으소서 당신은 우리 기업을 무를 자가 됨이니이다"]],"룻 4:6, 9-10":[["룻 4:6","그 기업 무를 자가 가로되 나는 내 기업에 손해가 있을까 하여 나를 위하여 무르지 못하노니 나의 무를 권리를 네가 취하라 나는 무르지 못하겠노라"],["룻 4:9","보아스가 장로들과 모든 백성에게 이르되 내가 엘리멜렉과 기룐과 말론에게 있던 모든 것을 나오미의 손에서 산 일에 너희가 오늘날 증인이 되었고"],["룻 4:10","또 말론의 아내 모압 여인 룻을 사서 나의 아내로 취하고 그 죽은 자의 기업을 그 이름으로 잇게 하여 그 이름이 그 형제 중과 그곳 성문에서 끊어지지 않게 함에 너희가 오늘날 증인이 되었느니라"]],"삼상 1:20":[["삼상 1:20","한나가 잉태하고 때가 이르매 아들을 낳아 사무엘이라 이름하였으니 이는 내가 여호와께 그를 구하였다 함이더라"]],"삼상 1:1, 19-20":[["삼상 1:1","에브라임 산지 라마다임소빔에 에브라임 사람 엘가나라 하는 자가 있으니 그는 여로함의 아들이요 엘리후의 손자요 도후의 증손이요 숩의 현손이더라"],["삼상 1:19","그들이 아침에 일찌기 일어나 여호와 앞에 경배하고 돌아가서 라마의 자기 집에 이르니라 엘가나가 그 아내 한나와 동침하매 여호와께서 그를 생각하신지라"],["삼상 1:20","한나가 잉태하고 때가 이르매 아들을 낳아 사무엘이라 이름하였으니 이는 내가 여호와께 그를 구하였다 함이더라"]],"삼상 7:17":[["삼상 7:17","라마로 돌아왔으니 이는 거기 자기 집이 있음이라 거기서도 이스라엘을 다스렸으며 또 거기 여호와를 위하여 단을 쌓았더라"]],"삼상 3:20; 7:15":[["삼상 3:20","단에서부터 브엘세바까지의 온 이스라엘이 사무엘은 여호와의 선지자로 세우심을 입은 줄을 알았더라"],["삼상 7:15","사무엘이 사는 날 동안에 이스라엘을 다스렸으되"]],"삼상 25:1":[["삼상 25:1","사무엘이 죽으매 온 이스라엘 무리가 모여 그를 애곡하며 라마 그의 집에서 그를 장사한지라 다윗이 일어나 바란 광야로 내려가니라"]],"삼상 2:21":[["삼상 2:21","여호와께서 한나를 권고하사 그로 잉태하여 세 아들과 두 딸을 낳게 하셨고 아이 사무엘은 여호와 앞에서 자라니라"]],"삼상 2:11":[["삼상 2:11","엘가나는 라마의 자기 집으로 돌아가고 그 아이는 제사장 엘리 앞에서 여호와를 섬기니라"]],"삼상 8:2":[["삼상 8:2","장자의 이름은 요엘이요 차자의 이름은 아비야라 그들이 브엘세바에서 사사가 되니라"]],"대상 6:33":[["대상 6:33","직무를 행하는 자와 그 아들들이 이러하니 그핫의 자손 중에 헤만은 찬송하는 자라 저는 요엘의 아들이요 요엘은 사무엘의 아들이요"]],"삼상 1:10-11, 20":[["삼상 1:10","한나가 마음이 괴로와서 여호와께 기도하고 통곡하며"],["삼상 1:11","서원하여 가로되 만군의 여호와여 만일 주의 여종의 고통을 돌아보시고 나를 생각하시고 주의 여종을 잊지 아니하사 아들을 주시면 내가 그의 평생에 그를 여호와께 드리고 삭도를 그 머리에 대지 아니하겠나이다"],["삼상 1:20","한나가 잉태하고 때가 이르매 아들을 낳아 사무엘이라 이름하였으니 이는 내가 여호와께 그를 구하였다 함이더라"]],"삼상 1:24-28; 2:11":[["삼상 1:24","젖을 뗀 후에 그를 데리고 올라갈쌔 수소 셋과 가루 한 에바와 포도주 한 가죽부대를 가지고 실로 여호와의 집에 나아갔는데 아이가 어리더라"],["삼상 1:25","그들이 수소를 잡고 아이를 데리고 엘리에게 가서"],["삼상 1:26","한나가 가로되 나의 주여 당신의 사심으로 맹세하나이다 나는 여기서 나의 주 당신 곁에 서서 여호와께 기도하던 여자라"],["삼상 1:27","이 아이를 위하여 내가 기도하였더니 여호와께서 나의 구하여 기도한 바를 허락하신지라"],["삼상 1:28","그러므로 나도 그를 여호와께 드리되 그의 평생을 여호와께 드리나이다 하고 그 아이는 거기서 여호와께 경배하니라"],["삼상 2:11","엘가나는 라마의 자기 집으로 돌아가고 그 아이는 제사장 엘리 앞에서 여호와를 섬기니라"]],"삼상 3:10":[["삼상 3:10","여호와께서 임하여 서서 전과 같이 사무엘아 사무엘아 부르시는지라 사무엘이 가로되 말씀하옵소서 주의 종이 듣겠나이다"]],"삼상 3:20":[["삼상 3:20","단에서부터 브엘세바까지의 온 이스라엘이 사무엘은 여호와의 선지자로 세우심을 입은 줄을 알았더라"]],"삼상 4:11, 18":[["삼상 4:11","하나님의 궤는 빼앗겼고 엘리의 두 아들 홉니와 비느하스는 죽임을 당하였더라"],["삼상 4:18","하나님의 궤를 말할 때에 엘리가 자기 의자에서 자빠져 문 곁에서 목이 부러져 죽었으니 나이 많고 비둔한 연고라 그가 이스라엘 사사가 된지 사십년이었더라"]],"삼상 7:5-6, 12":[["삼상 7:5","사무엘이 가로되 온 이스라엘은 미스바로 모이라 내가 너희를 위하여 여호와께 기도하리라 하매"],["삼상 7:6","그들이 미스바에 모여 물을 길어 여호와 앞에 붓고 그 날에 금식하고 거기서 가로되 우리가 여호와께 범죄하였나이다 하니라 사무엘이 미스바에서 이스라엘 자손을 다스리니라"],["삼상 7:12","사무엘이 돌을 취하여 미스바와 센 사이에 세워 가로되 여호와께서 여기까지 우리를 도우셨다 하고 그 이름을 에벤에셀이라 하니라"]],"삼상 7:16-17":[["삼상 7:16","해마다 벧엘과 길갈과 미스바로 순회하여 그 모든 곳에서 이스라엘을 다스렸고"],["삼상 7:17","라마로 돌아왔으니 이는 거기 자기 집이 있음이라 거기서도 이스라엘을 다스렸으며 또 거기 여호와를 위하여 단을 쌓았더라"]],"삼상 8:3-5":[["삼상 8:3","그 아들들이 그 아비의 행위를 따르지 아니하고 이를 따라서 뇌물을 취하고 판결을 굽게 하니라"],["삼상 8:4","이스라엘 모든 장로가 모여 라마에 있는 사무엘에게 나아가서"],["삼상 8:5","그에게 이르되 보소서 당신은 늙고 당신의 아들들은 당신의 행위를 따르지 아니하니 열방과 같이 우리에게 왕을 세워 우리를 다스리게 하소서 한지라"]],"삼상 11:15; 12:3-5":[["삼상 11:15","모든 백성이 길갈로 가서 거기서 여호와 앞에 사울로 왕을 삼고 거기서 여호와 앞에 화목제를 드리고 사울과 이스라엘 모든 사람이 거기서 크게 기뻐하니라"],["삼상 12:3","내가 여기 있나니 여호와 앞과 그 기름 부음을 받은 자 앞에서 내게 대하여 증거하라 내가 뉘 소를 취하였느냐 뉘 나귀를 취하였느냐 누구를 속였느냐 누구를 압제하였느냐 내 눈을 흐리게 하는 뇌물을 뉘 손에서 취하였느냐 그리하였으면 내가 그것을 너희에게 갚으리라"],["삼상 12:4","그들이 가로되 당신이 우리를 속이지 아니하였고 압제하지 아니하였고 뉘 손에서 아무 것도 취한 것이 없나이다"],["삼상 12:5","사무엘이 백성에게 이르되 너희가 내 손에서 아무 것도 찾아낸 것이 없음을 여호와께서 너희에게 대하여 증거하시며 그 기름 부음을 받은 자도 오늘날 증거하느니라 그들이 가로되 그가 증거하시나이다"]],"삼상 15:22":[["삼상 15:22","사무엘이 가로되 여호와께서 번제와 다른 제사를 그 목소리 순종하는 것을 좋아하심 같이 좋아하시겠나이까 순종이 제사보다 낫고 듣는것이 수양의 기름보다 나으니"]],"삼상 16:4, 13":[["삼상 16:4","사무엘이 여호와의 말씀대로 행하여 베들레헴에 이르매 성읍 장로들이 떨며 그를 영접하여 가로되 평강을 위하여 오시나이까"],["삼상 16:13","사무엘이 기름 뿔을 취하여 그 형제 중에서 그에게 부었더니 이 날 이후로 다윗이 여호와의 신에게 크게 감동되니라 사무엘이 떠나서 라마로 가니라"]],"삼상 28:7, 11-15":[["삼상 28:7","사울이 그 신하들에게 이르되 나를 위하여 신접한 여인을 찾으라 내가 그리로 가서 그에게 물으리라 그 신하들이 그에게 이르되 보소서 엔돌에 신접한 여인이 있나이다"],["삼상 28:11","여인이 가로되 내가 누구를 네게로 불러 올리랴 사울이 가로되 사무엘을 불러 올리라"],["삼상 28:12","여인이 사무엘을 보고 큰 소리로 외치며 사울에게 말하여 가로되 당신이 어찌하여 나를 속이셨나이까 당신이 사울이시니이다"],["삼상 28:13","왕이 그에게 이르되 두려워 말라 네가 무엇을 보았느냐 여인이 사울에게 이르되 내가 신이 땅에서 올라오는 것을 보았나이다"],["삼상 28:14","사울이 그에게 이르되 그 모양이 어떠하냐 그가 가로되 한 노인이 올라 오는데 그가 겉옷을 입었나이다 사울이 그가 사무엘인줄 알고 그 얼굴을 땅에 대고 절하니라"],["삼상 28:15","사무엘이 사울에게 이르되 네가 어찌하여 나를 불러 올려서 나로 분요케 하느냐 사울이 대답하되 나는 심히 군급하니이다 블레셋 사람은 나를 향하여 군대를 일으켰고 하나님은 나를 떠나서 다시는 선지자로도, 꿈으로도 내게 대답지 아니하시기로 나의 행할 일을 배우려고 당신을 불러 올렸나이다"]],"삼상 9:1-2":[["삼상 9:1","베냐민 지파에 기스라 이름하는 유력한 사람이 있으니 그는 아비엘의 아들이요 스롤의 손자요 베고랏의 증손이요 아비아의 현손이라 베냐민 사람이더라"],["삼상 9:2","기스가 아들이 있으니 그 이름은 사울이요 준수한 소년이라 이스라엘 자손 중에 그보다 더 준수한 자가 없고 키는 모든 백성보다 어깨 위는 더 하더라"]],"삼상 9:2":[["삼상 9:2","기스가 아들이 있으니 그 이름은 사울이요 준수한 소년이라 이스라엘 자손 중에 그보다 더 준수한 자가 없고 키는 모든 백성보다 어깨 위는 더 하더라"]],"삼상 10:26":[["삼상 10:26","사울도 기브아 자기 집으로 갈 때에 마음이 하나님께 감동된 유력한 자들은 그와 함께 갔어도"]],"삼상 10:20-21; 11:15":[["삼상 10:20","사무엘이 이에 이스라엘 모든 지파를 가까이 오게 하였더니 베냐민 지파가 뽑혔고"],["삼상 10:21","베냐민 지파를 그 가족대로 가까이 오게 하였더니 마드리의 가족이 뽑혔고 그 중에서 기스의 아들 사울이 뽑혔으나 그를 찾아도 만나지 못한지라"],["삼상 11:15","모든 백성이 길갈로 가서 거기서 여호와 앞에 사울로 왕을 삼고 거기서 여호와 앞에 화목제를 드리고 사울과 이스라엘 모든 사람이 거기서 크게 기뻐하니라"]],"삼상 13:1":[["삼상 13:1","사울이 왕이 될 때에 사십세라 그가 이스라엘을 다스린지 이년에"]],"삼상 31:1-4":[["삼상 31:1","블레셋 사람이 이스라엘을 치매 이스라엘 사람들이 블레셋 사람 앞에서 도망하여 길보아산에서 엎드러져 죽으니라"],["삼상 31:2","블레셋 사람들이 사울과 그 아들들을 쫓아 미쳐서 사울의 아들 요나단과 아비나답과 말기수아를 죽이니라"],["삼상 31:3","사울이 패전하매 활 쏘는 자가 따라 미치니 사울이 그 활 쏘는 자를 인하여 중상한지라"],["삼상 31:4","그가 병기 든 자에게 이르되 네 칼을 빼어 나를 찌르라 할례 없는 자들이 와서 나를 찌르고 모욕할까 두려워하노라 하나 병기 든 자가 심히 두려워하여 즐겨 행치 아니하는지라 이에 사울이 자기 칼을 취하고 그 위에 엎드러지매"]],"삼상 9:1":[["삼상 9:1","베냐민 지파에 기스라 이름하는 유력한 사람이 있으니 그는 아비엘의 아들이요 스롤의 손자요 베고랏의 증손이요 아비아의 현손이라 베냐민 사람이더라"]],"삼상 14:50-51":[["삼상 14:50","사울의 아내의 이름은 아히노암이니 아히마아스의 딸이요 그 군장의 이름은 아브넬이니 사울의 숙부 넬의 아들이며"],["삼상 14:51","사울의 아비는 기스요 아브넬의 아비는 넬이니 아비엘의 아들이었더라"]],"삼상 14:50":[["삼상 14:50","사울의 아내의 이름은 아히노암이니 아히마아스의 딸이요 그 군장의 이름은 아브넬이니 사울의 숙부 넬의 아들이며"]],"삼하 3:7":[["삼하 3:7","사울에게 첩이 있었으니 이름은 리스바요 아야의 딸이더라 이스보셋이 아브넬에게 이르되 네가 어찌하여 내 아버지의 첩을 통간하였느냐"]],"삼상 14:49":[["삼상 14:49","사울의 아들은 요나단과 리스위와 말기수아요 그 두 딸의 이름은 이러하니 맏딸의 이름은 메랍이요 작은 딸의 이름은 미갈이며"]],"삼상 14:49; 31:2":[["삼상 14:49","사울의 아들은 요나단과 리스위와 말기수아요 그 두 딸의 이름은 이러하니 맏딸의 이름은 메랍이요 작은 딸의 이름은 미갈이며"],["삼상 31:2","블레셋 사람들이 사울과 그 아들들을 쫓아 미쳐서 사울의 아들 요나단과 아비나답과 말기수아를 죽이니라"]],"삼하 2:8-9":[["삼하 2:8","사울의 군장 넬의 아들 아브넬이 이미 사울의 아들 이스보셋을 데리고 마하나임으로 건너가서"],["삼하 2:9","길르앗과 아술과 이스르엘과 에브라임과 베냐민과 온 이스라엘의 왕을 삼았더라"]],"삼하 21:8":[["삼하 21:8","이에 아야의 딸 리스바에게서 난 자 곧 사울의 두 아들 알모니와 므비보셋과 사울의 딸 메랍에게서 난 자 곧 므홀랏 사람 바실래의 아들 아드리엘의 다섯 아들을 잡고"]],"삼하 4:4":[["삼하 4:4","사울의 아들 요나단에게 절뚝발이 아들 하나가 있으니 이름은 므비보셋이라 전에 사울과 요나단의 죽은 소식이 이스르엘에서 올 때에 그 나이 다섯살이었는데 그 유모가 안고 도망하더니 급히 도망하므로 아이가 떨어져 절게 되었더라"]],"삼상 9:3, 18-20":[["삼상 9:3","사울의 아비 기스가 암나귀들을 잃고 그 아들 사울에게 이르되 너는 한 사환을 데리고 일어나 가서 암나귀들을 찾으라 하매"],["삼상 9:18","사울이 성문 가운데 사무엘에게 나아가 가로되 선견자의 집이 어디인지 청컨대 내게 가르치소서"],["삼상 9:19","사무엘이 사울에게 대답하여 가로되 내가 선견자니라 너는 내 앞서 산당으로 올라가라 너희가 오늘날 나와 함께 먹을 것이요 아침에는 내가 너를 보내되 네 마음에 있는 것을 다 네게 말하리라"],["삼상 9:20","사흘 전에 잃은 네 암나귀들을 염려하지 말라 찾았느니라 온 이스라엘의 사모하는 자가 누구냐 너와 네 아비의 온 집이 아니냐"]],"삼상 10:21-22":[["삼상 10:21","베냐민 지파를 그 가족대로 가까이 오게 하였더니 마드리의 가족이 뽑혔고 그 중에서 기스의 아들 사울이 뽑혔으나 그를 찾아도 만나지 못한지라"],["삼상 10:22","그러므로 그들이 또 여호와께 묻되 그 사람이 여기 왔나이까 여호와께서 대답하시되 그가 행구 사이에 숨었느니라"]],"삼상 11:11, 15":[["삼상 11:11","이튿날에 사울이 백성을 삼대에 나누고 새벽에 적진 중에 들어가서 날이 더울 때까지 암몬 사람을 치매 남은 자가 다 흩어져서 둘도 함께한 자가 없었더라"],["삼상 11:15","모든 백성이 길갈로 가서 거기서 여호와 앞에 사울로 왕을 삼고 거기서 여호와 앞에 화목제를 드리고 사울과 이스라엘 모든 사람이 거기서 크게 기뻐하니라"]],"삼상 13:9-14":[["삼상 13:9","사울이 가로되 번제와 화목제물을 이리로 가져오라 하여 번제를 드렸더니"],["삼상 13:10","번제 드리기를 필하자 사무엘이 온지라 사울이 나가 맞으며 문안하매"],["삼상 13:11","사무엘이 가로되 왕의 행한 것이 무엇이뇨 사울이 가로되 백성은 나에게서 흩어지고 당신은 정한 날 안에 오지 아니하고 블레셋 사람은 믹마스에 모였음을 내가 보았으므로"],["삼상 13:12","이에 내가 이르기를 블레셋 사람은 나를 치러 길갈로 내려오겠거늘 내가 여호와께 은혜를 간구치 못하였다 하고 부득이하여 번제를 드렸나이다"],["삼상 13:13","사무엘이 사울에게 이르되 왕이 망령되이 행하였도다 왕이 왕의 하나님 여호와께서 왕에게 명하신 명령을 지키지 아니하였도다 그리하였더면 여호와께서 이스라엘 위에 왕의 나라를 영영히 세우셨을 것이어늘"],["삼상 13:14","지금은 왕의 나라가 길지 못할 것이라 여호와께서 왕에게 명하신 바를 왕이 지키지 아니하였으므로 여호와께서 그 마음에 맞는 사람을 구하여 그 백성의 지도자를 삼으셨느니라 하고"]],"삼상 15:9, 23":[["삼상 15:9","사울과 백성이 아각과 그 양과 소의 가장 좋은 것 또는 기름진 것과 어린 양과 모든 좋은 것을 남기고 진멸키를 즐겨 아니하고 가치 없고 낮은 것은 진멸하니라"],["삼상 15:23","이는 거역하는 것은 사술의 죄와 같고 완고한 것은 사신 우상에게 절하는 죄와 같음이라 왕이 여호와의 말씀을 버렸으므로 여호와께서도 왕을 버려 왕이 되지 못하게 하셨나이다"]],"삼상 16:14, 23":[["삼상 16:14","여호와의 신이 사울에게서 떠나고 여호와의 부리신 악신이 그를 번뇌케 한지라"],["삼상 16:23","하나님의 부리신 악신이 사울에게 이를 때에 다윗이 수금을 취하여 손으로 탄즉 사울이 상쾌하여 낫고 악신은 그에게서 떠나더라"]],"삼상 17:11, 50":[["삼상 17:11","사울과 온 이스라엘이 블레셋 사람의 이 말을 듣고 놀라 크게 두려워하니라"],["삼상 17:50","다윗이 이같이 물매와 돌로 블레셋 사람을 이기고 그를 쳐 죽였으나 자기 손에는 칼이 없었더라"]],"삼상 18:7-9":[["삼상 18:7","여인들이 뛰놀며 창화하여 가로되 사울의 죽인 자는 천천이요 다윗은 만만이로다 한지라"],["삼상 18:8","사울이 이 말에 불쾌하여 심히 노하여 가로되 다윗에게는 만만을 돌리고 내게는 천천만 돌리니 그의 더 얻을 것이 나라 밖에 무엇이냐 하고"],["삼상 18:9","그 날 후로 사울이 다윗을 주목하였더라"]],"삼상 19:10; 23:14":[["삼상 19:10","사울이 단창으로 다윗을 벽에 박으려 하였으나 그는 사울의 앞을 피하고 사울의 창은 벽에 박힌지라 다윗이 그 밤에 도피하매"],["삼상 23:14","다윗이 황무지 요새에도 있었고 또 십 황무지 산골에도 유하였으므로 사울이 매일 찾되 하나님이 그를 그의 손에 붙이지 아니하시니라"]],"삼상 28:7-8":[["삼상 28:7","사울이 그 신하들에게 이르되 나를 위하여 신접한 여인을 찾으라 내가 그리로 가서 그에게 물으리라 그 신하들이 그에게 이르되 보소서 엔돌에 신접한 여인이 있나이다"],["삼상 28:8","사울이 다른 옷을 입어 변장하고 두 사람과 함께 갈쌔 그들이 밤에 그 여인에게 이르러는 사울이 가로되 청하노니 나를 위하여 신접한 술법으로 내가 네게 말하는 사람을 불러올리라"]],"삼상 31:4-6":[["삼상 31:4","그가 병기 든 자에게 이르되 네 칼을 빼어 나를 찌르라 할례 없는 자들이 와서 나를 찌르고 모욕할까 두려워하노라 하나 병기 든 자가 심히 두려워하여 즐겨 행치 아니하는지라 이에 사울이 자기 칼을 취하고 그 위에 엎드러지매"],["삼상 31:5","병기 든 자가 사울의 죽음을 보고 자기도 자기 칼 위에 엎드러져 그와 함께 죽으니라"],["삼상 31:6","사울과 그 세 아들과 병기 든 자와 그의 모든 사람이 다 그 날에 함께 죽었더라"]],"삼하 12:25":[["삼하 12:25","선지자 나단을 보내사 그 이름을 여디디야라 하시니 이는 여호와께서 사랑하심을 인함이더라"]],"왕상 11:42":[["왕상 11:42","솔로몬이 예루살렘에서 온 이스라엘을 다스린 날 수가 사십년이라"]],"왕상 4:32":[["왕상 4:32","저가 잠언 삼천을 말하였고 그 노래는 일천 다섯이며"]],"왕상 11:3":[["왕상 11:3","왕은 후비가 칠백인이요 빈장이 삼백인이라 왕비들이 왕의 마음을 돌이켰더라"]],"왕상 11:43":[["왕상 11:43","솔로몬이 그 열조와 함께 자매 그 부친 다윗의 성에 장사되고 그 아들 르호보암이 대신하여 왕이 되니라"]],"삼하 11:3":[["삼하 11:3","다윗이 보내어 그 여인을 알아보게 하였더니 고하되 그는 엘리암의 딸이요 헷 사람 우리아의 아내 밧세바가 아니니이까"]],"대상 3:5":[["대상 3:5","예루살렘에서 낳은 아들들은 이러하니 시므아와 소밥과 나단과 솔로몬 네 사람은 다 암미엘의 딸 밧수아의 소생이요"]],"왕상 3:1":[["왕상 3:1","솔로몬이 애굽 왕 바로로 더불어 인연을 맺어 그 딸을 취하고 데려다가 다윗성에 두고 자기의 궁과 여호와의 전과 예루살렘 주위의 성이 필역되기를 기다리니라"]],"왕상 14:21":[["왕상 14:21","솔로몬의 아들 르호보암은 유다 왕이 되었으니 르호보암이 위에 나아갈 때에 나이 사십일세라 여호와께서 자기 이름을 두시려고 이스라엘 모든 지파 가운데서 빼신 성 예루살렘에서 십 칠년을 치리하니라 그 모친의 이름은 나아마라 암몬 사람이더라"]],"왕상 4:11, 15":[["왕상 4:11","돌 높은 땅 온 지방에는 벤아비나답이니 저는 솔로몬의 딸 다밧으로 아내를 삼았으며"],["왕상 4:15","납달리에는 아히마아스니 저는 솔로몬의 딸 바스맛으로 아내를 삼았으며"]],"마 1:6-7, 16":[["마 1:6","이새는 다윗왕을 낳으니라 다윗은 우리야의 아내에게서 솔로몬을 낳고"],["마 1:7","솔로몬은 르호보암을 낳고 르호보암은 아비야를 낳고 아비야는 아사를 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"왕상 1:38-39":[["왕상 1:38","제사장 사독과 선지자 나단과 여호야다의 아들 브나야와 그렛 사람과 블렛 사람이 내려가서 솔로몬을 다윗왕의 노새에 태우고 인도하여 기혼으로 가서"],["왕상 1:39","제사장 사독이 성막 가운데서 기름 뿔을 가져다가 솔로몬에게 기름을 부으니 이에 양각을 불고 모든 백성이 솔로몬왕 만세를 부르니라"]],"왕상 3:5, 9, 13":[["왕상 3:5","기브온에서 밤에 여호와께서 솔로몬의 꿈에 나타나시니라 하나님이 이르시되 내가 네게 무엇을 줄꼬 너는 구하라"],["왕상 3:9","누가 주의 이 많은 백성을 재판할 수 있사오리이까 지혜로운 마음을 종에게 주사 주의 백성을 재판하여 선악을 분별하게 하옵소서"],["왕상 3:13","내가 또 너의 구하지 아니한 부와 영광도 네게 주노니 네 평생에 열왕 중에 너와 같은 자가 없을 것이라"]],"왕상 3:16, 27":[["왕상 3:16","때에 창기 두 계집이 왕에게 와서 그 앞에 서며"],["왕상 3:27","왕이 대답하여 가로되 산 아들을 저 계집에게 주고 결코 죽이지 말라 저가 그 어미니라 하매"]],"왕상 6:1, 38":[["왕상 6:1","이스라엘 자손이 애굽 땅에서 나온지 사백 팔십년이요 솔로몬이 이스라엘 왕이 된지 사년 시브월 곧 이월에 솔로몬이 여호와를 위하여 전 건축하기를 시작하였더라"],["왕상 6:38","제 십일년 불월 곧 팔월에 그 설계와 식양대로 전이 다 필역되었으니 솔로몬이 전을 건축한 동안이 칠년이었더라"]],"왕상 7:1":[["왕상 7:1","솔로몬이 자기의 궁을 십삼년 동안 건축하여 그 전부를 준공하니라"]],"왕상 8:22-23":[["왕상 8:22","솔로몬이 여호와의 단 앞에서 이스라엘의 온 회중을 마주서서 하늘을 향하여 손을 펴고"],["왕상 8:23","가로되 이스라엘 하나님 여호와여 상천 하지에 주와 같은 신이 없나이다 주께서는 온 마음으로 주의 앞에서 행하는 종들에게 언약을 지키시고 은혜를 베푸시나이다"]],"왕상 9:15":[["왕상 9:15","솔로몬왕이 역군을 일으킨 까닭은 여호와의 전과 자기 궁과 밀로와 예루살렘성과 하솔과 므깃도와 게셀을 건축하려 하였음이라"]],"왕상 10:1":[["왕상 10:1","스바 여왕이 여호와의 이름으로 말미암은 솔로몬의 명예를 듣고 와서 어려운 문제로 저를 시험코자 하여"]],"왕상 11:4, 11":[["왕상 11:4","솔로몬의 나이 늙을 때에 왕비들이 그 마음을 돌이켜 다른 신들을 좇게 하였으므로 왕의 마음이 그 부친 다윗의 마음과 같지 아니하여 그 하나님 여호와 앞에 온전치 못하였으니"],["왕상 11:11","여호와께서 솔로몬에게 말씀하시되 네게 이러한 일이 있었고 또 네가 나의 언약과 내가 네게 명한 법도를 지키지 아니하였으니 내가 결단코 이 나라를 네게서 빼앗아 네 신복에게 주리라"]],"왕상 11:42-43":[["왕상 11:42","솔로몬이 예루살렘에서 온 이스라엘을 다스린 날 수가 사십년이라"],["왕상 11:43","솔로몬이 그 열조와 함께 자매 그 부친 다윗의 성에 장사되고 그 아들 르호보암이 대신하여 왕이 되니라"]],"왕상 12:21":[["왕상 12:21","르호보암이 예루살렘에 이르러 유다 온 족속과 베냐민 지파를 모으니 택한 용사가 십 팔만이라 이스라엘 족속과 싸워 나라를 회복하여 솔로몬의 아들 르호보암에게 돌리려 하더니"]],"왕상 14:31":[["왕상 14:31","르호보암이 그 열조와 함께 자니 그 열조와 함께 다윗성에 장사되니라 그 모친의 이름은 나아마라 암몬 사람이더라 그 아들 아비얌이 대신하여 왕이 되니라"]],"대하 11:18":[["대하 11:18","르호보암이 다윗의 아들 여리못의 딸 마할랏으로 아내를 삼았으니 마할랏은 이새의 아들 엘리압의 딸 아비하일의 소생이라"]],"대하 11:20-21":[["대하 11:20","그 후에 압살롬의 딸 마아가에게 장가 들었더니 저가 아비야와 앗대와 시사와 슬로밋을 낳았더라"],["대하 11:21","르호보암이 아내 십 팔과 첩 육십을 취하여 아들 이십 팔과 딸 육십을 낳았으나 압살롬의 딸 마아가를 모든 처첩보다 더 사랑하여"]],"대하 11:21":[["대하 11:21","르호보암이 아내 십 팔과 첩 육십을 취하여 아들 이십 팔과 딸 육십을 낳았으나 압살롬의 딸 마아가를 모든 처첩보다 더 사랑하여"]],"왕상 12:13-14":[["왕상 12:13","왕이 포학한 말로 백성에게 대답할쌔 노인의 교도를 버리고"],["왕상 12:14","소년의 가르침을 좇아 저희에게 고하여 가로되 내 부친은 너희의 멍에를 무겁게 하였으나 나는 너희의 멍에를 더욱 무겁게 할찌라 내 부친은 채찍으로 너희를 징치하였으나 나는 전갈로 너희를 징치하리라 하니라"]],"왕상 12:16, 20":[["왕상 12:16","온 이스라엘이 자기들의 말을 왕이 듣지 아니함을 보고 왕에게 대답하여 가로되 우리가 다윗과 무슨 관계가 있느뇨 이새의 아들에게서 업이 없도다 이스라엘아 너희의 장막으로 돌아가라 다윗이여 이제 너는 네 집이나 돌아보라 하고 이스라엘이 그 장막으로 돌아가니라"],["왕상 12:20","온 이스라엘이 여로보암의 돌아왔다 함을 듣고 보내어 저를 공회로 청하여다가 온 이스라엘의 왕을 삼았으니 유다 지파 외에는 다윗의 집을 좇는 자가 없으니라"]],"왕상 12:21-24":[["왕상 12:21","르호보암이 예루살렘에 이르러 유다 온 족속과 베냐민 지파를 모으니 택한 용사가 십 팔만이라 이스라엘 족속과 싸워 나라를 회복하여 솔로몬의 아들 르호보암에게 돌리려 하더니"],["왕상 12:22","하나님의 말씀이 하나님의 사람 스마야에게 임하여 가라사대"],["왕상 12:23","솔로몬의 아들 유다 왕 르호보암과 유다와 베냐민 온 족속과 또 그 남은 백성에게 고하여 이르기를"],["왕상 12:24","여호와의 말씀이 너희는 올라가지 말라 너희 형제 이스라엘 자손과 싸우지 말고 각기 집으로 돌아가라 이 일이 내게로 말미암아 난 것이라 하셨다 하라 하신지라 저희가 여호와의 말씀을 듣고 그 말씀을 좇아 돌아갔더라"]],"대하 11:5":[["대하 11:5","르호보암이 예루살렘에 거하여 유다 땅에 방비하는 성읍들을 건축하였으니"]],"대하 11:13-14":[["대하 11:13","온 이스라엘의 제사장과 레위 사람이 그 모든 지방에서부터 르호보암에게 돌아오되"],["대하 11:14","레위 사람이 그 향리와 산업을 떠나 유다와 예루살렘에 이르렀으니 이는 여로보암과 그 아들들이 저희를 폐하여 여호와께 제사장의 직분을 행치 못하게 하고"]],"왕상 14:22-23":[["왕상 14:22","유다가 여호와 보시기에 악을 행하되 그 열조의 행한 모든 일보다 뛰어나게 하여 그 범한 죄로 여호와의 노를 격발하였으니"],["왕상 14:23","이는 저희도 산 위에와 모든 푸른 나무 아래 산당과 우상과 아세라 목상을 세웠음이라"]],"왕상 14:27":[["왕상 14:27","르호보암왕이 그 대신 놋으로 방패를 만들어 왕궁 문을 지키는 시위대 장관의 손에 맡기매"]],"왕상 14:30":[["왕상 14:30","르호보암과 여로보암 사이에 항상 전쟁이 있으니라"]],"왕상 11:26":[["왕상 11:26","솔로몬의 신복 느밧의 아들 여로보암이 또한 손을 들어 왕을 대적하였으니 저는 에브라임 족속인 스레다 사람이요 그 어미의 이름은 스루아니 과부더라"]],"왕상 11:28":[["왕상 11:28","이 사람 여로보암은 큰 용사라 솔로몬이 이 소년의 부지런함을 보고 세워 요셉 족속의 역사를 감독하게 하였더니"]],"왕상 14:20":[["왕상 14:20","여로보암이 왕이 된지 이십이년이라 저가 그 열조와 함께 자매 그 아들 나답이 대신하여 왕이 되니라"]],"왕상 12:25; 14:17":[["왕상 12:25","여로보암이 에브라임 산지에 세겜을 건축하고 거기서 살며 또 거기서 나가서 부느엘을 건축하고"],["왕상 14:17","여로보암의 처가 일어나 디르사로 돌아가서 집 문지방에 이를 때에 아이가 죽은지라"]],"왕상 14:2":[["왕상 14:2","여로보암이 그 아내에게 이르되 청컨대 일어나 변장하여 사람으로 그대가 여로보암의 아내임을 알지 못하게 하고 실로로 가라 거기 선지자 아히야가 있나니 저는 이전에 내가 이 백성의 왕이 될 것을 내게 고한 사람이니라"]],"왕상 14:1":[["왕상 14:1","그 때에 여로보암의 아들 아비야가 병든지라"]],"왕상 11:30-31":[["왕상 11:30","아히야가 그 입은 새 옷을 잡아 열 두 조각에 찢고"],["왕상 11:31","여로보암에게 이르되 너는 열 조각을 취하라 이스라엘 하나님 여호와의 말씀이 내가 이 나라를 솔로몬의 손에서 찢어 빼앗아 열 지파를 네게 주고"]],"왕상 11:40":[["왕상 11:40","이러므로 솔로몬이 여로보암을 죽이려 하매 여로보암이 일어나 애굽으로 도망하여 애굽 왕 시삭에게 이르러 솔로몬의 죽기까지 애굽에 있으니라"]],"왕상 12:2-3, 20":[["왕상 12:2","느밧의 아들 여로보암이 전에 솔로몬왕의 얼굴을 피하여 애굽으로 도망하여 있었더니 이제 그 소문을 듣고 오히려 애굽에 있는 중에"],["왕상 12:3","무리가 보내어 저를 불렀더라 여로보암과 이스라엘의 온 회중이 와서 르호보암에게 고하여 가로되"],["왕상 12:20","온 이스라엘이 여로보암의 돌아왔다 함을 듣고 보내어 저를 공회로 청하여다가 온 이스라엘의 왕을 삼았으니 유다 지파 외에는 다윗의 집을 좇는 자가 없으니라"]],"왕상 12:25":[["왕상 12:25","여로보암이 에브라임 산지에 세겜을 건축하고 거기서 살며 또 거기서 나가서 부느엘을 건축하고"]],"왕상 12:28-29":[["왕상 12:28","이에 계획하고 두 금송아지를 만들고 무리에게 말하기를 너희가 다시는 예루살렘에 올라갈 것이 없도다 이스라엘아 이는 너희를 애굽 땅에서 인도하여 올린 너희 신이라 하고"],["왕상 12:29","하나는 벧엘에 두고 하나는 단에 둔지라"]],"왕상 12:31-32":[["왕상 12:31","저가 또 산당들을 짓고 레위 자손 아닌 보통 백성으로 제사장을 삼고"],["왕상 12:32","팔월 곧 그 달 십 오일로 절기를 정하여 유다의 절기와 비슷하게 하고 단에 올라가되 벧엘에서 그와 같이 행하여 그 만든 송아지에게 제사를 드렸으며 그 지은 산당의 제사장은 벧엘에서 세웠더라"]],"왕상 13:1, 4":[["왕상 13:1","때에 하나님의 사람이 여호와의 말씀으로 인하여 유다에서부터 벧엘에 이르니 마침 여로보암이 단 곁에 서서 분향하는지라"],["왕상 13:4","여로보암왕이 하나님의 사람의 벧엘에 있는 단을 향하여 외쳐 말함을 들을 때에 단에서 손을 펴며 저를 잡으라 하더라 저를 향하여 편 손이 말라 다시 거두지 못하며"]],"왕상 14:1-2":[["왕상 14:1","그 때에 여로보암의 아들 아비야가 병든지라"],["왕상 14:2","여로보암이 그 아내에게 이르되 청컨대 일어나 변장하여 사람으로 그대가 여로보암의 아내임을 알지 못하게 하고 실로로 가라 거기 선지자 아히야가 있나니 저는 이전에 내가 이 백성의 왕이 될 것을 내게 고한 사람이니라"]],"대하 12:2-3":[["대하 12:2","저희가 여호와께 범죄하였으므로 르호보암왕 오년에 애굽 왕 시삭이 예루살렘을 치러 올라오니"],["대하 12:3","저에게 병거가 일천 이백승이요 마병이 육만이며 애굽에서 좇아나온 무리 곧 훕과 숩과 구스 사람이 불가승수라"]],"대하 12:4":[["대하 12:4","시삭이 유다의 견고한 성읍을 취하고 예루살렘에 이르니"]],"왕상 16:16":[["왕상 16:16","진중 백성들이 시므리가 모반하여 왕을 죽였다는 말을 들은지라 그 날에 이스라엘의 무리가 진에서 군대장관 오므리로 이스라엘 왕을 삼으매"]],"왕상 16:23":[["왕상 16:23","유다 왕 아사 제 삼십 일년에 오므리가 이스라엘 왕이 되어 십 이년을 위에 있으며 디르사에서 육년 동안 치리하니라"]],"왕상 16:23-24":[["왕상 16:23","유다 왕 아사 제 삼십 일년에 오므리가 이스라엘 왕이 되어 십 이년을 위에 있으며 디르사에서 육년 동안 치리하니라"],["왕상 16:24","저가 은 두 달란트로 세멜에게서 사마리아산을 사고 그 산 위에 성을 건축하고 그 건축한 성 이름을 그 산 주인이 되었던 세멜의 이름을 좇아 사마리아라 일컬었더라"]],"왕상 16:25":[["왕상 16:25","오므리가 여호와 보시기에 악을 행하되 그 전의 모든 사람보다 더욱 악하게 행하여"]],"왕상 22:40; 왕하 3:1":[["왕상 22:40","아합이 그 열조와 함께 자매 그 아들 아하시야가 대신하여 왕이 되니라"],["왕하 3:1","유다 왕 여호사밧의 십팔년에 아합의 아들 여호람이 사마리아에서 이스라엘 왕이 되어 십 이년을 치리하니라"]],"왕하 8:26":[["왕하 8:26","아하시야가 위에 나아갈 때에 나이 이십이세라 예루살렘에서 일년을 치리하니라 그 모친의 이름은 아달랴라 이스라엘 왕 오므리의 손녀더라"]],"왕상 16:15-16":[["왕상 16:15","유다 왕 아사 제 이십 칠년에 시므리가 디르사에서 칠일 동안 왕이 되니라 때에 백성들이 블레셋 사람에게 속한 깁브돈을 향하여 진을 치고 있더니"],["왕상 16:16","진중 백성들이 시므리가 모반하여 왕을 죽였다는 말을 들은지라 그 날에 이스라엘의 무리가 진에서 군대장관 오므리로 이스라엘 왕을 삼으매"]],"왕상 16:17-18":[["왕상 16:17","오므리가 이에 이스라엘 무리를 거느리고 깁브돈에서부터 올라와서 디르사를 에워 쌌더라"],["왕상 16:18","시므리가 성이 함락됨을 보고 왕궁 위소에 들어가서 왕궁에 불을 놓고 그 가운데서 죽었으니"]],"왕상 16:21-22":[["왕상 16:21","그 때에 이스라엘 백성이 둘에 나뉘어 그 절반은 기낫의 아들 디브니를 좇아 저로 왕을 삼으려하고 그 절반은 오므리를 좇았더니"],["왕상 16:22","오므리를 좇은 백성이 기낫의 아들 디브니를 좇은 백성을 이긴지라 디브니가 죽으매 오므리가 왕이 되니라"]],"왕상 17:1; 왕하 1:3":[["왕상 17:1","길르앗에 우거하는 자 중에 디셉 사람 엘리야가 아합에게 고하되 나의 섬기는 이스라엘 하나님 여호와의 사심을 가리켜 맹세하노니 내 말이 없으면 수년 동안 우로가 있지 아니하리라 하니라"],["왕하 1:3","여호와의 사자가 디셉 사람 엘리야에게 이르시되 너는 일어나 올라가서 사마리아 왕의 사자를 만나서 저에게 이르기를 이스라엘에 하나님이 없어서 너희가 에그론의 신 바알세붑에게 물으러 가느냐"]],"왕하 1:8":[["왕하 1:8","저희가 대답하되 그는 털이 많은 사람인데 허리에 가죽 띠를 띠었더이다 왕이 가로되 그는 디셉 사람 엘리야로다"]],"왕상 19:16, 19":[["왕상 19:16","너는 또 님시의 아들 예후에게 기름을 부어 이스라엘 왕이 되게 하고 또 아벨므흘라 사밧의 아들 엘리사에게 기름을 부어 너를 대신하여 선지자가 되게 하라"],["왕상 19:19","엘리야가 거기서 떠나 사밧의 아들 엘리사를 만나니 저가 열 두 겨리 소를 앞세우고 밭을 가는데 자기는 열둘째 겨리와 함께 있더라 엘리야가 그리로 건너가서 겉옷을 그의 위에 던졌더니"]],"왕하 2:11":[["왕하 2:11","두 사람이 행하며 말하더니 홀연히 불수레와 불말들이 두 사람을 격하고 엘리야가 회리바람을 타고 승천하더라"]],"왕상 17:5-6":[["왕상 17:5","저가 여호와의 말씀과 같이 하여 곧 가서 요단 앞 그릿 시냇가에 머물매"],["왕상 17:6","까마귀들이 아침에도 떡과 고기를, 저녁에도 떡과 고기를 가져왔고 저가 시내를 마셨더니"]],"왕상 17:14-16, 22":[["왕상 17:14","이스라엘 하나님 여호와의 말씀이 나 여호와가 비를 지면에 내리는 날까지 그 통의 가루는 다하지 아니하고 그 병의 기름은 없어지지 아니하리라 하셨느니라"],["왕상 17:15","저가 가서 엘리야의 말대로 하였더니 저와 엘리야와 식구가 여러날 먹었으나"],["왕상 17:16","여호와께서 엘리야로 하신 말씀 같이 통의 가루가 다하지 아니하고 병의 기름이 없어지지 아니하니라"],["왕상 17:22","여호와께서 엘리야의 소리를 들으시므로 그 아이의 혼이 몸으로 돌아 오고 살아난지라"]],"왕상 18:19, 38-39":[["왕상 18:19","그런즉 보내어 온 이스라엘과 이세벨의 상에서 먹는 바알의 선지자 사백 오십인과 아세라의 선지자 사백인을 갈멜산으로 모아 내게로 나오게 하소서"],["왕상 18:38","이에 여호와의 불이 내려서 번제물과 나무와 돌과 흙을 태우고 또 도랑의 물을 핥은지라"],["왕상 18:39","모든 백성이 보고 엎드려 말하되 여호와 그는 하나님이시로다 여호와 그는 하나님이시로다 하니"]],"왕상 18:40, 45":[["왕상 18:40","엘리야가 저희에게 이르되 바알의 선지자를 잡되 하나도 도망하지 못하게 하라 하매 곧 잡은지라 엘리야가 저희를 기손 시내로 내려다가 거기서 죽이니라"],["왕상 18:45","조금 후에 구름과 바람이 일어나서 하늘이 캄캄하여지며 큰 비가 내리는지라 아합이 마차를 타고 이스르엘로 가니"]],"왕상 19:3-4":[["왕상 19:3","저가 이 형편을 보고 일어나 그 생명을 위하여 도망하여 유다에 속한 브엘세바에 이르러 자기의 사환을 그곳에 머물게 하고"],["왕상 19:4","스스로 광야로 들어가 하룻길쯤 행하고 한 로뎀나무 아래 앉아서 죽기를 구하여 가로되 여호와여 넉넉하오니 지금 내 생명을 취하옵소서 나는 내 열조보다 낫지 못하니이다 하고"]],"왕상 19:11-12":[["왕상 19:11","여호와께서 가라사대 너는 나가서 여호와의 앞에서 산에 섰으라 하시더니 여호와께서 지나가시는데 여호와의 앞에 크고 강한 바람이 산을 가르고 바위를 부수나 바람 가운데 여호와께서 계시지 아니하며 바람 후에 지진이 있으나 지진 가운데도 여호와께서 계시지 아니하며"],["왕상 19:12","또 지진 후에 불이 있으나 불 가운데도 여호와께서 계시지 아니하더니 불 후에 세미한 소리가 있는지라"]],"왕상 19:19":[["왕상 19:19","엘리야가 거기서 떠나 사밧의 아들 엘리사를 만나니 저가 열 두 겨리 소를 앞세우고 밭을 가는데 자기는 열둘째 겨리와 함께 있더라 엘리야가 그리로 건너가서 겉옷을 그의 위에 던졌더니"]],"왕상 21:17-19":[["왕상 21:17","여호와의 말씀이 디셉 사람 엘리야에게 임하여 가라사대"],["왕상 21:18","너는 일어나 내려가서 사마리아에 거하는 이스라엘 왕 아합을 만나라 저가 나봇의 포도원을 취하러 그리로 내려갔나니"],["왕상 21:19","너는 저에게 말하여 이르기를 여호와의 말씀이 네가 죽이고 또 빼앗았느냐 하셨다 하고 또 저에게 이르기를 여호와의 말씀이 개들이 나봇의 피를 핥은 곳에서 개들이 네 피 곧 네 몸의 피도 핥으리라 하셨다 하라"]],"왕하 1:9-10":[["왕하 1:9","이에 오십부장과 그 오십인을 엘리야에게로 보내매 저가 엘리야에게로 올라가서 본즉 산 꼭대기에 앉았는지라 저가 엘리야에게 이르되 하나님의 사람이여 왕의 말씀이 내려오라 하셨나이다"],["왕하 1:10","엘리야가 오십부장에게 대답하여 가로되 내가 만일 하나님의 사람이면 불이 하늘에서 내려와서 너와 너의 오십인을 사를찌로다 하매 불이 곧 하늘에서 내려와서 저와 그 오십인을 살랐더라"]],"왕하 2:8, 11":[["왕하 2:8","엘리야가 겉옷을 취하여 말아 물을 치매 물이 이리 저리 갈라지고 두 사람이 육지 위로 건너더라"],["왕하 2:11","두 사람이 행하며 말하더니 홀연히 불수레와 불말들이 두 사람을 격하고 엘리야가 회리바람을 타고 승천하더라"]],"마 17:3":[["마 17:3","때에 모세와 엘리야가 예수로 더불어 말씀하는 것이 저희에게 보이거늘"]],"욘 1:1":[["욘 1:1","여호와의 말씀이 아밋대의 아들 요나에게 임하니라 이르시되"]],"왕하 14:25":[["왕하 14:25","이스라엘 하나님 여호와께서 그 종 가드헤벨 아밋대의 아들 선지자 요나로 하신 말씀과 같이 여로보암이 이스라엘 지경을 회복하되 하맛 어귀에서부터 아라바 바다까지 하였으니"]],"욘 1:2-3":[["욘 1:2","너는 일어나 저 큰 성읍 니느웨로 가서 그것을 쳐서 외치라 그 악독이 내 앞에 상달하였음이니라 하시니라"],["욘 1:3","그러나 요나가 여호와의 낯을 피하려고 일어나 다시스로 도망하려 하여 욥바로 내려갔더니 마침 다시스로 가는 배를 만난지라 여호와의 낯을 피하여 함께 다시스로 가려고 선가를 주고 배에 올랐더라"]],"욘 1:12":[["욘 1:12","그가 대답하되 나를 들어 바다에 던지라 그리하면 바다가 너희를 위하여 잔잔하리라 너희가 이 큰 폭풍을 만난 것이 나의 연고인줄을 내가 아노라 하니라"]],"욘 1:17; 2:1":[["욘 1:17","여호와께서 이미 큰 물고기를 예비하사 요나를 삼키게 하셨으므로 요나가 삼일 삼야를 물고기 배에 있으니라"],["욘 2:1","요나가 물고기 뱃속에서 그 하나님 여호와께 기도하여"]],"욘 2:10":[["욘 2:10","여호와께서 그 물고기에게 명하시매 요나를 육지에 토하니라"]],"욘 3:4-6":[["욘 3:4","요나가 그 성에 들어가며 곧 하룻길을 행하며 외쳐 가로되 사십일이 지나면 니느웨가 무너지리라 하였더니"],["욘 3:5","니느웨 백성이 하나님을 믿고 금식을 선포하고 무론 대소하고 굵은 베를 입은지라"],["욘 3:6","그 소문이 니느웨 왕에게 들리매 왕이 보좌에서 일어나 조복을 벗고 굵은 베를 입고 재에 앉으니라"]],"욘 4:1-3":[["욘 4:1","요나가 심히 싫어하고 노하여"],["욘 4:2","여호와께 기도하여 가로되 여호와여 내가 고국에 있을 때에 이러하겠다고 말씀하지 아니하였나이까 그러므로 내가 빨리 다시스로 도망하였사오니 주께서는 은혜로우시며 자비로우시며 노하기를 더디하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시는 하나님이신 줄을 내가 알았음이니이다"],["욘 4:3","여호와여 원컨대 이제 내 생명을 취하소서 사는 것보다 죽는 것이 내게 나음이니이다"]],"욘 4:9-11":[["욘 4:9","하나님이 요나에게 이르시되 네가 이 박 넝쿨로 인하여 성냄이 어찌 합당하냐 그가 대답하되 내가 성내어 죽기까지 할찌라도 합당하니이다"],["욘 4:10","여호와께서 가라사대 네가 수고도 아니하였고 배양도 아니하였고 하룻밤에 났다가 하룻밤에 망한 이 박 넝쿨을 네가 아꼈거든"],["욘 4:11","하물며 이 큰 성읍, 니느웨에는 좌우를 분변치 못하는 자가 십 이만 여명이요 육축도 많이 있나니 내가 아끼는 것이 어찌 합당치 아니하냐"]],"마 12:39-41":[["마 12:39","예수께서 대답하여 가라사대 악하고 음란한 세대가 표적을 구하나 선지자 요나의 표적 밖에는 보일 표적이 없느니라"],["마 12:40","요나가 밤낮 사흘을 큰 물고기 뱃속에 있었던것 같이 인자도 밤낮 사흘을 땅속에 있으리라"],["마 12:41","심판 때에 니느웨 사람들이 일어나 이 세대 사람을 정죄하리니 이는 그들이 요나의 전도를 듣고 회개하였음이어니와 요나보다 더 큰이가 여기 있으며"]],"사 20:1":[["사 20:1","앗수르 왕 사르곤이 군대장관을 아스돗으로 보내매 그가 와서 아스돗을 쳐서 취하던 해"]],"왕하 17:5-6":[["왕하 17:5","올라와서 그 온 땅에 두루 다니고 사마리아로 올라와서 삼년을 에워쌌더라"],["왕하 17:6","호세아 구년에 앗수르 왕이 사마리아를 취하고 이스라엘 사람을 사로잡아 앗수르로 끌어다가 할라와 고산 하볼 하숫가와 메대 사람의 여러 고을에 두었더라"]],"왕하 17:24":[["왕하 17:24","앗수르 왕이 바벨론과 구다와 아와와 하맛과 스발와임에서 사람을 옮겨다가 이스라엘 자손을 대신하여 사마리아 여러 성읍에 두매 저희가 사마리아를 차지하여 그 여러 성읍에 거하니라"]],"왕하 21:1":[["왕하 21:1","므낫세가 위에 나아갈 때에 나이 십 이세라 예루살렘에서 오십 오년을 치리하니라 그 모친의 이름은 헵시바더라"]],"왕하 24:3":[["왕하 24:3","이 일이 유다에 임함은 곧 여호와의 명하신바로 저희를 자기 앞에서 물리치고자 하심이니 이는 므낫세의 지은 모든 죄로 인함이며"]],"왕하 21:18":[["왕하 21:18","므낫세가 그 열조와 함께 자매 그 궁궐 동산 곧 웃사의 동산에 장사되고 그 아들 아몬이 대신하여 왕이 되니라"]],"마 1:6, 10":[["마 1:6","이새는 다윗왕을 낳으니라 다윗은 우리야의 아내에게서 솔로몬을 낳고"],["마 1:10","히스기야는 므낫세를 낳고 므낫세는 아몬을 낳고 아몬은 요시야를 낳고"]],"왕하 21:19":[["왕하 21:19","아몬이 위에 나아갈 때에 나이 이십 이세라 예루살렘에서 이년을 치리하니라 그 모친의 이름은 므술레멧이라 욧바 하루스의 딸이더라"]],"왕하 21:26":[["왕하 21:26","아몬이 웃시야의 동산 자기 묘실에 장사되고 그 아들 요시야가 대신하여 왕이 되니라"]],"마 1:10, 16":[["마 1:10","히스기야는 므낫세를 낳고 므낫세는 아몬을 낳고 아몬은 요시야를 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"왕하 21:3":[["왕하 21:3","그 부친 히스기야의 헐어버린 산당을 다시 세우며 이스라엘 왕 아합의 소위를 본받아 바알을 위하여 단을 쌓으며 아세라 목상을 만들며 하늘의 일월 성신을 숭배하여 섬기며"]],"왕하 21:5":[["왕하 21:5","또 여호와의 전 두 마당에 하늘의 일월 성신을 위하여 단들을 쌓고"]],"왕하 21:6":[["왕하 21:6","또 그 아들을 불 가운데로 지나게 하며 점치며 사술을 행하며 신접한 자와 박수를 신임하여 여호와 보시기에 악을 많이 행하여 그 진노를 격발하였으며"]],"왕하 21:16":[["왕하 21:16","므낫세가 여호와 보시기에 악을 행하여 유다로 범하게한 그 죄 외에 또 무죄한 자의 피를 심히 많이 흘려 예루살렘 이 가에서 저 가까지 가득하게 하였더라"]],"대하 33:11":[["대하 33:11","여호와께서 앗수르 왕의 군대 장관들로 와서 치게 하시매 저희가 므낫세를 사로잡고 쇠사슬로 결박하여 바벨론으로 끌어 간지라"]],"대하 33:12-13, 15":[["대하 33:12","저가 환난을 당하여 그 하나님 여호와께 간구하고 그 열조의 하나님 앞에 크게 겸비하여"],["대하 33:13","기도한고로 하나님이 그 기도를 받으시며 그 간구를 들으시사 저로 예루살렘에 돌아와서 다시 왕위에 거하게 하시매 므낫세가 그제야 여호와께서 하나님이신 줄을 알았더라"],["대하 33:15","이방 신들과 여호와의 전의 우상을 제하며 여호와의 전을 건축한 산에와 예루살렘에 쌓은 모든 단을 다 성 밖에 던지고"]],"왕하 21:24; 22:1-2":[["왕하 21:24","그 국민이 아몬왕을 반역한 사람들을 다 죽이고 그 아들 요시야로 대신하여 왕을 삼았더라"],["왕하 22:1","요시야가 위에 나아갈 때에 나이 팔세라 예루살렘에서 삼십 일년을 치리하니라 그 모친의 이름은 여디다라 보스갓 아다야의 딸이더라"],["왕하 22:2","요시야가 여호와 보시기에 정직히 행하여 그 조상 다윗의 모든 길로 행하고 좌우로 치우치지 아니하였더라"]],"왕하 22:1":[["왕하 22:1","요시야가 위에 나아갈 때에 나이 팔세라 예루살렘에서 삼십 일년을 치리하니라 그 모친의 이름은 여디다라 보스갓 아다야의 딸이더라"]],"왕하 22:2":[["왕하 22:2","요시야가 여호와 보시기에 정직히 행하여 그 조상 다윗의 모든 길로 행하고 좌우로 치우치지 아니하였더라"]],"왕하 23:29-30":[["왕하 23:29","요시야 당시에 애굽 왕 바로느고가 앗수르 왕을 치고자 하여 유브라데 하수로 올라가므로 요시야왕이 나가서 방비하더니 애굽 왕이 요시야를 므깃도에서 만나본 후에 죽인지라"],["왕하 23:30","신복들이 그 시체를 병거에 싣고 므깃도에서 예루살렘으로 돌아와서 그 묘실에 장사하니 국민이 요시야의 아들 여호아하스를 데려다가 저에게 기름을 붓고 그 부친을 대신하여 왕을 삼았더라"]],"대상 3:13-14":[["대상 3:13","그 아들은 아하스요 그 아들은 히스기야요 그 아들은 므낫세요"],["대상 3:14","그 아들은 아몬이요 그 아들은 요시야며"]],"왕하 21:24":[["왕하 21:24","그 국민이 아몬왕을 반역한 사람들을 다 죽이고 그 아들 요시야로 대신하여 왕을 삼았더라"]],"대상 3:15":[["대상 3:15","요시야의 아들들은 맏아들 요하난과 둘째 여호야김과 세째 시드기야와 네째 살룸이요"]],"왕하 23:30-31; 렘 22:11":[["왕하 23:30","신복들이 그 시체를 병거에 싣고 므깃도에서 예루살렘으로 돌아와서 그 묘실에 장사하니 국민이 요시야의 아들 여호아하스를 데려다가 저에게 기름을 붓고 그 부친을 대신하여 왕을 삼았더라"],["왕하 23:31","여호아하스가 위에 나아갈 때에 나이 이십 삼세라 예루살렘에서 석달을 치리하니라 그 모친의 이름은 하무달이라 립나 예레미야의 딸이더라"],["렘 22:11","나 여호와가 유다왕 요시야의 아들 곧 그 아비 요시야를 이어 왕이 되었다가 이곳에서 나간 살룸에 대하여 말하노라 그가 이곳으로 다시 돌아오지 못하고"]],"왕하 23:34":[["왕하 23:34","바로느고가 요시야의 아들 엘리아김으로 그 아비 요시야를 대신하여 왕을 삼고 그 이름을 고쳐 여호야김이라 하고 여호아하스는 애굽으로 잡아갔더니 저가 거기서 죽으니라"]],"대상 3:15; 왕하 24:17":[["대상 3:15","요시야의 아들들은 맏아들 요하난과 둘째 여호야김과 세째 시드기야와 네째 살룸이요"],["왕하 24:17","바벨론 왕이 또 여호야긴의 아자비 맛다니야로 대신하여 왕을 삼고 그 이름을 고쳐 시드기야라 하였더라"]],"왕하 21:23-24; 22:1":[["왕하 21:23","그 신복들이 반역하여 왕을 궁중에서 죽이매"],["왕하 21:24","그 국민이 아몬왕을 반역한 사람들을 다 죽이고 그 아들 요시야로 대신하여 왕을 삼았더라"],["왕하 22:1","요시야가 위에 나아갈 때에 나이 팔세라 예루살렘에서 삼십 일년을 치리하니라 그 모친의 이름은 여디다라 보스갓 아다야의 딸이더라"]],"대하 34:3":[["대하 34:3","오히려 어렸을 때 곧 위에 있은지 팔년에 그 조상 다윗의 하나님을 비로소 구하고 그 십 이년에 유다와 예루살렘을 비로소 정결케 하여 그 산당과 아세라 목상들과 아로새긴 우상들과 부어만든 우상들을 제하여 버리매"]],"렘 1:2":[["렘 1:2","아몬의 아들 유다 왕 요시야의 다스린지 십 삼년에 여호와의 말씀이 예레미야에게 임하였고"]],"왕하 22:3, 8":[["왕하 22:3","요시야왕 십 팔년에 왕이 므술람의 손자 아살리야의 아들 서기관 사반을 여호와의 전에 보내며 가로되"],["왕하 22:8","대제사장 힐기야가 서기관 사반에게 이르되 내가 여호와의 전에서 율법책을 발견하였노라 하고 그 책을 사반에게 주니 사반이 읽으니라"]],"왕하 22:11":[["왕하 22:11","왕이 율법책의 말을 듣자 곧 그 옷을 찢으니라"]],"왕하 22:14":[["왕하 22:14","이에 제사장 힐기야와 또 아히감과 악볼과 사반과 아사야가 여선지 훌다에게로 나아가니 저는 할하스의 손자 디과의 아들 예복을 주관하는 살룸의 아내라 예루살렘 둘째 구역에 거하였더라 저희가 더불어 말하매"]],"왕하 23:3-4":[["왕하 23:3","왕이 대 위에 서서 여호와 앞에서 언약을 세우되 마음을 다하고 성품을 다하여 여호와를 순종하고 그 계명과 법도와 율례를 지켜 이 책에 기록된 이 언약의 말씀을 이루게 하리라 하매 백성이 다 그 언약을 좇기로 하니라"],["왕하 23:4","왕이 대제사장 힐기야와 모든 버금 제사장들과 문을 지킨 자들에게 명하여 바알과 아세라와 하늘의 일월 성신을 위하여 만든 모든 기명을 여호와의 전에서 내어다가 예루살렘 바깥 기드론 밭에서 불사르고 그 재를 벧엘로 가져가게 하고"]],"왕하 23:15-16":[["왕하 23:15","이스라엘로 범죄케 한 느밧의 아들 여로보암이 벧엘에 세운 단과 산당을 왕이 헐고 또 그 산당을 불사르고 빻아서 가루를 만들며 또 아세라 목상을 불살랐더라"],["왕하 23:16","요시야가 몸을 돌이켜 산에 있는 묘실들을 보고 보내어 그 묘실에서 해골을 취하여다가 단 위에 불살라 그 단을 더럽게 하니라 이 일을 하나님의 사람이 전하였더니 그 전한 여호와의 말씀대로 되었더라"]],"왕하 23:21-22":[["왕하 23:21","왕이 뭇백성에게 명하여 가로되 이 언약책에 기록된대로 너희의 하나님 여호와를 위하여 유월절을 지키라 하매"],["왕하 23:22","사사가 이스라엘을 다스리던 시대부터 이스라엘 열왕의 시대에든지 유다 열왕의 시대에든지 이렇게 유월절을 지킨 일이 없었더니"]],"왕하 23:29; 대하 35:22-24":[["왕하 23:29","요시야 당시에 애굽 왕 바로느고가 앗수르 왕을 치고자 하여 유브라데 하수로 올라가므로 요시야왕이 나가서 방비하더니 애굽 왕이 요시야를 므깃도에서 만나본 후에 죽인지라"],["대하 35:22","요시야가 몸을 돌이켜 떠나기를 싫어하고 변장하고 싸우고자 하여 하나님의 입에서 나온 느고의 말을 듣지 아니하고 므깃도 골짜기에 이르러 싸울 때에"],["대하 35:23","활 쏘는 자가 요시야왕을 쏜지라 왕이 그 신복에게 이르되 내가 중상하였으니 나를 도와 나가게 하라"],["대하 35:24","그 신복이 저를 병거에서 내리게 하고 저의 버금 병거에 태워 예루살렘에 이른 후에 저가 죽으니 그 열조의 묘실에 장사하니라 온 유다와 예루살렘 사람들이 요시야를 슬퍼하고"]],"대하 35:25":[["대하 35:25","예레미야는 저를 위하여 애가를 지었으며 노래하는 남자와 여자는 요시야를 슬피 노래하니 이스라엘에 규례가 되어 오늘날까지 이르렀으며 그 가사는 애가 중에 기록되었더라"]],"렘 1:1":[["렘 1:1","베냐민 땅 아나돗의 제사장 중 힐기야의 아들 예레미야의 말이라"]],"렘 1:2-3":[["렘 1:2","아몬의 아들 유다 왕 요시야의 다스린지 십 삼년에 여호와의 말씀이 예레미야에게 임하였고"],["렘 1:3","요시야의 아들 유다 왕 여호야김 시대부터 요시야의 아들 유다 왕 시드기야의 제 십 일년 말까지 임하니라 이 해 오월에 예루살렘이 사로잡히니라"]],"렘 16:2":[["렘 16:2","너는 이 땅에서 아내를 취하지 말며 자녀를 두지 말찌니라"]],"렘 36:4":[["렘 36:4","이에 예레미야가 네리야의 아들 바룩을 부르매 바룩이 예레미야의 구전대로 여호와께서 그에게 이르신 모든 말씀을 두루마리 책에 기록하니라"]],"렘 43:6-7":[["렘 43:6","곧 남자와 여자와 유아와 왕의 딸들과 시위대장 느부사라단이 사반의 손자 아히감의 아들 그다랴에게 넘겨 둔 모든 사람과 선지자 예레미야와 네리야의 아들 바룩을 영솔하고"],["렘 43:7","애굽 땅에 들어가 다바네스에 이르렀으니 그들이 여호와의 목소리를 청종치 아니함이 이러하였더라"]],"렘 32:7":[["렘 32:7","보라 네 숙부 살룸의 아들 하나멜이 네게 와서 말하기를 너는 아나돗에 있는 내 밭을 사라 이 기업을 무를 권리가 네게 있느니라 하리라 하시더니"]],"렘 32:7-9":[["렘 32:7","보라 네 숙부 살룸의 아들 하나멜이 네게 와서 말하기를 너는 아나돗에 있는 내 밭을 사라 이 기업을 무를 권리가 네게 있느니라 하리라 하시더니"],["렘 32:8","여호와의 말씀 같이 나의 숙부의 아들 하나멜이 시위대 뜰안 내게로 와서 이르되 청하노니 너는 베냐민 땅 아나돗에 있는 나의 밭을 사라 기업의 상속권이 네게 있고 무를 권리가 네게 있으니 너를 위하여 사라 하는지라 내가 이것이 여호와의 말씀인줄 알았으므로"],["렘 32:9","내 숙부의 아들 하나멜의 아나돗에 있는 밭을 사는데 은 십 칠세겔을 달아주되"]],"렘 1:2, 6":[["렘 1:2","아몬의 아들 유다 왕 요시야의 다스린지 십 삼년에 여호와의 말씀이 예레미야에게 임하였고"],["렘 1:6","내가 가로되 슬프도소이다 주 여호와여 보소서 나는 아이라 말할 줄을 알지 못하나이다"]],"렘 7:2-4":[["렘 7:2","너는 여호와의 집 문에 서서 이 말을 선포하여 이르기를 여호와께 경배하러 이 문으로 들어가는 유다인아 다 여호와의 말씀을 들으라"],["렘 7:3","만군의 여호와 이스라엘의 하나님이 이같이 말씀하시되 너희 길과 행위를 바르게 하라 그리하면 내가 너희로 이곳에 거하게 하리라"],["렘 7:4","너희는 이것이 여호와의 전이라, 여호와의 전이라, 여호와의 전이라 하는 거짓말을 믿지 말라"]],"렘 20:2":[["렘 20:2","이에 바스훌이 선지자 예레미야를 때리고 여호와의 집 베냐민의 윗문에 있는 착고에 채웠더니"]],"렘 25:1, 11":[["렘 25:1","유다 왕 요시야의 아들 여호야김 사년 곧 바벨론 왕 느부갓네살 원년에 유다 모든 백성에 관한 말씀이 예레미야에게 임하니라"],["렘 25:11","이 온 땅이 황폐하여 놀램이 될 것이며 이 나라들은 칠십년 동안 바벨론 왕을 섬기리라"]],"렘 36:1-4":[["렘 36:1","유다 왕 요시야의 아들 여호야김 사년에 여호와께로서 예레미야에게 말씀이 임하니라 가라사대"],["렘 36:2","너는 두루마리 책을 취하여 내가 네게 말하던 날 곧 요시야의 날부터 오늘까지 이스라엘과 유다와 열방에 대하여 나의 네게 이른 모든 말을 그것에 기록하라"],["렘 36:3","유다 족속이 내가 그들에게 내리려한 모든 재앙을 듣고 각기 악한 길에서 돌이킬듯 하니라 그리하면 내가 그 악과 죄를 사하리라"],["렘 36:4","이에 예레미야가 네리야의 아들 바룩을 부르매 바룩이 예레미야의 구전대로 여호와께서 그에게 이르신 모든 말씀을 두루마리 책에 기록하니라"]],"렘 36:23":[["렘 36:23","여후디가 삼편 사편을 낭독하면 왕이 소도로 그것을 연하여 베어 화로 불에 던져서 온 두루마리를 태웠더라"]],"렘 27:2, 12":[["렘 27:2","여호와께서 이같이 내게 이르시되 너는 줄과 멍에를 만들어 네 목에 얹고"],["렘 27:12","내가 이 모든 말씀대로 유다 왕 시드기야에게 고하여 가로되 왕과 백성은 목으로 바벨론 왕의 멍에를 메고 그와 그 백성을 섬기소서 그리하면 살리이다"]],"렘 29:4-7":[["렘 29:4","만군의 여호와 이스라엘의 하나님 내가 예루살렘에서 바벨론으로 사로잡혀 가게 한 모든 포로에게 이같이 이르노라"],["렘 29:5","너희는 집을 짓고 거기 거하며 전원을 만들고 그 열매를 먹으라"],["렘 29:6","아내를 취하여 자녀를 생산하며 너희 아들로 아내를 취하며 너희 딸로 남편을 맞아 그들로 자녀를 생산케 하여 너희로 거기서 번성하고 쇠잔하지 않게 하라"],["렘 29:7","너희는 내가 사로잡혀 가게 한 그 성읍의 평안하기를 힘쓰고 위하여 여호와께 기도하라 이는 그 성이 평안함으로 너희도 평안할 것임이니라"]],"렘 31:31":[["렘 31:31","나 여호와가 말하노라 보라 날이 이르리니 내가 이스라엘 집과 유다 집에 새 언약을 세우리라"]],"렘 32:6-9, 15":[["렘 32:6","예레미야가 가로되 여호와의 말씀이 내게 임하였느니라 이르시기를"],["렘 32:7","보라 네 숙부 살룸의 아들 하나멜이 네게 와서 말하기를 너는 아나돗에 있는 내 밭을 사라 이 기업을 무를 권리가 네게 있느니라 하리라 하시더니"],["렘 32:8","여호와의 말씀 같이 나의 숙부의 아들 하나멜이 시위대 뜰안 내게로 와서 이르되 청하노니 너는 베냐민 땅 아나돗에 있는 나의 밭을 사라 기업의 상속권이 네게 있고 무를 권리가 네게 있으니 너를 위하여 사라 하는지라 내가 이것이 여호와의 말씀인줄 알았으므로"],["렘 32:9","내 숙부의 아들 하나멜의 아나돗에 있는 밭을 사는데 은 십 칠세겔을 달아주되"],["렘 32:15","만군의 여호와 이스라엘의 하나님 내가 이같이 말하노라 사람이 이 땅에서 집과 밭과 포도원을 다시 사게 되리라 하셨다 하니라"]],"렘 38:6-13":[["렘 38:6","그들이 예레미야를 취하여 시위대 뜰에 있는 왕의 아들 말기야의 구덩이에 던져 넣을 때에 예레미야를 줄로 달아내리웠는데 그 구덩이에는 물이 없고 진흙 뿐이므로 예레미야가 진흙 중에 빠졌더라"],["렘 38:7","왕궁 환관 구스인 에벳멜렉이 그들의 예레미야를 구덩이에 던져 넣었음을 들으니라 때에 왕이 베냐민 문에 앉았더니"],["렘 38:8","에벳멜렉이 왕궁에서 나와 왕께 고하여 가로되"],["렘 38:9","내 주 왕이여 저 사람들이 선지자 예레미야에게 행한 모든 일은 악하니이다 성 중에 떡이 떨어졌거늘 그들이 그를 구덩이에 던져 넣었으니 그가 거기서 주려 죽으리이다"],["렘 38:10","왕이 구스인 에벳멜렉에게 명하여 가로되 너는 여기서 삼십명을 데리고 가서 선지자 예레미야의 죽기 전에 그를 구덩이에서 끌어 내라"],["렘 38:11","에벳멜렉이 사람들을 데리고 왕궁 곳간 밑 방에 들어가서 거기서 헝겊과 낡은 옷을 취하고 그것을 구덩이에 있는 예레미야에게 줄로 내리우며"],["렘 38:12","구스인 에벳멜렉이 예레미야에게 이르되 너는 이 헝겊과 낡은 옷을 네 겨드랑이에 대고 줄을 그 아래 대라 예레미야가 그대로 하매"],["렘 38:13","그들이 줄로 예레미야를 구덩이에서 끌어낸지라 예레미야가 시위대 뜰에 머무니라"]],"렘 39:11-14":[["렘 39:11","바벨론 왕 느부갓네살이 예레미야에 대하여 시위대장 느부사라단에게 명하여 가로되"],["렘 39:12","그를 데려다가 선대하고 해하지 말며 그가 네게 말하는대로 행하라"],["렘 39:13","이에 시위대장 느부사라단과 환관장 느부사스반과 박사장 네르갈사레셀과 바벨론 왕의 모든 장관이"],["렘 39:14","보내어 예레미야를 시위대 뜰에서 취하여 내어 사반의 손자 아히감의 아들 그다랴에게 붙여서 그를 집으로 데려가게 하매 그가 백성 중에 거하니라"]],"단 1:7":[["단 1:7","환관장이 그들의 이름을 고쳐 다니엘은 벨드사살이라 하고 하나냐는 사드락이라 하고 미사엘은 메삭이라 하고 아사랴는 아벳느고라 하였더라"]],"단 1:3, 6":[["단 1:3","왕이 환관장 아스부나스에게 명하여 이스라엘 자손 중에서 왕족과 귀족의 몇 사람"],["단 1:6","그들 중에 유다 자손 곧 다니엘과 하나냐와 미사엘과 아사랴가 있었더니"]],"단 2:48":[["단 2:48","왕이 이에 다니엘을 높여 귀한 선물을 많이 주며 세워 바벨론 온 도를 다스리게 하며 또 바벨론 모든 박사의 어른을 삼았으며"]],"단 6:2":[["단 6:2","또 그들 위에 총리 셋을 두었으니 다니엘이 그 중에 하나이라 이는 방백들로 총리에게 자기의 직무를 보고하게 하여 왕에게 손해가 없게 하려함이었더라"]],"단 10:1":[["단 10:1","바사 왕 고레스 삼년에 한 일이 벨드사살이라 이름한 다니엘에게 나타났는데 그 일이 참되니 곧 큰 전쟁에 관한 것이라 다니엘이 그 일을 분명히 알았고 그 이상을 깨달으니라"]],"단 1:6-7":[["단 1:6","그들 중에 유다 자손 곧 다니엘과 하나냐와 미사엘과 아사랴가 있었더니"],["단 1:7","환관장이 그들의 이름을 고쳐 다니엘은 벨드사살이라 하고 하나냐는 사드락이라 하고 미사엘은 메삭이라 하고 아사랴는 아벳느고라 하였더라"]],"단 1:8, 12":[["단 1:8","다니엘은 뜻을 정하여 왕의 진미와 그의 마시는 포도주로 자기를 더럽히지 아니하리라 하고 자기를 더럽히지 않게 하기를 환관장에게 구하니"],["단 1:12","청하오니 당신의 종들을 열흘 동안 시험하여 채식을 주어 먹게 하고 물을 주어 마시게 한 후에"]],"단 1:5, 19-20":[["단 1:5","또 왕이 지정하여 자기의 진미와 자기의 마시는 포도주에서 그들의 날마다 쓸 것을 주어 삼년을 기르게 하였으니 이는 그 후에 그들로 왕의 앞에 모셔 서게 하려함이었더라"],["단 1:19","왕이 그들과 말하여 보매 무리 중에 다니엘과 하나냐와 미사엘과 아사랴와 같은 자 없으므로 그들로 왕 앞에 모시게 하고"],["단 1:20","왕이 그들에게 모든 일을 묻는 중에 그 지혜와 총명이 온 나라 박수와 술객보다 십배나 나은줄을 아니라"]],"단 2:1, 48":[["단 2:1","느부갓네살이 위에 있은지 이년에 꿈을 꾸고 그로 인하여 마음이 번민하여 잠을 이루지 못한지라"],["단 2:48","왕이 이에 다니엘을 높여 귀한 선물을 많이 주며 세워 바벨론 온 도를 다스리게 하며 또 바벨론 모든 박사의 어른을 삼았으며"]],"단 4:19":[["단 4:19","벨드사살이라 이름한 다니엘이 얼마 동안 놀라 벙벙하며 마음이 번민하여 하는지라 왕이 그에게 말하여 이르기를 벨드사살아 너는 이 꿈과 그 해석을 인하여 번민할 것이 아니니라 벨드사살이 대답하여 가로되 내 주여 그 꿈은 왕을 미워하는 자에게 응하기를 원하며 그 해석은 왕의 대적에게 응하기를 원하나이다"]],"단 7:1-3":[["단 7:1","바벨론 왕 벨사살 원년에 다니엘이 그 침상에서 꿈을 꾸며 뇌 속으로 이상을 받고 그 꿈을 기록하며 그 일의 대략을 진술하니라"],["단 7:2","다니엘이 진술하여 가로되 내가 밤에 이상을 보았는데 하늘의 네 바람이 큰 바다로 몰려 불더니"],["단 7:3","큰 짐승 넷이 바다에서 나왔는데 그 모양이 각각 다르니"]],"단 5:25-29":[["단 5:25","기록한 글자는 이것이니 곧 메네 메네 데겔 우바르신이라"],["단 5:26","그 뜻을 해석하건대 메네는 하나님이 이미 왕의 나라의 시대를 세어서 그것을 끝나게 하셨다 함이요"],["단 5:27","데겔은 왕이 저울에 달려서 부족함이 뵈었다 함이요"],["단 5:28","베레스는 왕의 나라가 나뉘어서 메대와 바사 사람에게 준바 되었다 함이니이다"],["단 5:29","이에 벨사살이 명하여 무리로 다니엘에게 자주옷을 입히게 하며 금 사슬로 그의 목에 드리우게 하고 그를 위하여 조서를 내려 나라의 세째 치리자를 삼으니라"]],"단 6:1-2":[["단 6:1","다리오가 자기의 심원대로 방백 일백 이십명을 세워 전국을 통치하게 하고"],["단 6:2","또 그들 위에 총리 셋을 두었으니 다니엘이 그 중에 하나이라 이는 방백들로 총리에게 자기의 직무를 보고하게 하여 왕에게 손해가 없게 하려함이었더라"]],"단 6:10":[["단 6:10","다니엘이 이 조서에 어인이 찍힌 것을 알고도 자기 집에 돌아가서는 그 방의 예루살렘으로 향하여 열린 창에서 전에 행하던대로 하루 세번씩 무릎을 꿇고 기도하며 그 하나님께 감사하였더라"]],"단 6:16, 22-23":[["단 6:16","이에 왕이 명하매 다니엘을 끌어다가 사자 굴에 던져 넣는지라 왕이 다니엘에게 일러 가로되 너의 항상 섬기는 네 하나님이 너를 구원하시리라 하니라"],["단 6:22","나의 하나님이 이미 그 천사를 보내어 사자들의 입을 봉하셨으므로 사자들이 나를 상해치 아니하였사오니 이는 나의 무죄함이 그 앞에 명백함이오며 또 왕이여 나는 왕의 앞에도 해를 끼치지 아니하였나이다"],["단 6:23","왕이 심히 기뻐서 명하여 다니엘을 굴에서 올리라 하매 그들이 다니엘을 굴에서 올린즉 그 몸이 조금도 상하지 아니하였으니 이는 그가 자기 하나님을 의뢰함이었더라"]],"단 9:1-2, 24":[["단 9:1","메대 족속 아하수에로의 아들 다리오가 갈대아 나라 왕으로 세움을 입던 원년"],["단 9:2","곧 그 통치 원년에 나 다니엘이 서책으로 말미암아 여호와의 말씀이 선지자 예레미야에게 임하여 고하신 그 년수를 깨달았나니 곧 예루살렘의 황무함이 칠십년만에 마치리라 하신 것이니라"],["단 9:24","네 백성과 네 거룩한 성을 위하여 칠십 이레로 기한을 정하였나니 허물이 마치며 죄가 끝나며 죄악이 영속되며 영원한 의가 드러나며 이상과 예언이 응하며 또 지극히 거룩한 자가 기름부음을 받으리라"]],"단 10:1, 4":[["단 10:1","바사 왕 고레스 삼년에 한 일이 벨드사살이라 이름한 다니엘에게 나타났는데 그 일이 참되니 곧 큰 전쟁에 관한 것이라 다니엘이 그 일을 분명히 알았고 그 이상을 깨달으니라"],["단 10:4","정월 이십 사일에 내가 힛데겔이라 하는 큰 강 가에 있었는데"]],"단 5:30; 7:1":[["단 5:30","그날 밤에 갈대아왕 벨사살이 죽임을 당하였고"],["단 7:1","바벨론 왕 벨사살 원년에 다니엘이 그 침상에서 꿈을 꾸며 뇌 속으로 이상을 받고 그 꿈을 기록하며 그 일의 대략을 진술하니라"]],"단 5:2, 18":[["단 5:2","벨사살이 술을 마실 때에 명하여 그 부친 느부갓네살이 예루살렘 전에서 취하여 온 금, 은 기명을 가져오게 하였으니 이는 왕과 귀인들과 왕후들과 빈궁들이 다 그것으로 마시려 함이었더라"],["단 5:18","왕이여 지극히 높으신 하나님이 왕의 부친 느부갓네살에게 나라와 큰 권세와 영광과 위엄을 주셨고"]],"단 5:10-11":[["단 5:10","태후가 왕과 그 귀인들의 말로 인하여 잔치하는 궁에 들어 왔더니 이에 말하여 가로되 왕이여 만세수를 하옵소서 왕의 생각을 번민케 말며 낯빛을 변할 것이 아니니이다"],["단 5:11","왕의 나라에 거룩한 신들의 영이 있는 사람이 있으니 곧 왕의 부친 때에 있던 자로서 명철과 총명과 지혜가 있어 신들의 지혜와 같은 자라 왕의 부친 느부갓네살왕이 그를 세워 박수와 술객과 갈대아 술사와 점장이의 어른을 삼으셨으니"]],"단 7:1":[["단 7:1","바벨론 왕 벨사살 원년에 다니엘이 그 침상에서 꿈을 꾸며 뇌 속으로 이상을 받고 그 꿈을 기록하며 그 일의 대략을 진술하니라"]],"단 8:1":[["단 8:1","나 다니엘에게 처음에 나타난 이상 후 벨사살왕 삼년에 다시 이상이 나타나니라"]],"단 5:1-3":[["단 5:1","벨사살왕이 그 귀인 일천명을 위하여 큰 잔치를 배설하고 그 일천명 앞에서 술을 마시니라"],["단 5:2","벨사살이 술을 마실 때에 명하여 그 부친 느부갓네살이 예루살렘 전에서 취하여 온 금, 은 기명을 가져오게 하였으니 이는 왕과 귀인들과 왕후들과 빈궁들이 다 그것으로 마시려 함이었더라"],["단 5:3","이에 예루살렘 하나님의 전 성소 중에서 취하여 온 금 기명을 가져오매 왕이 그 귀인들과 왕후들과 빈궁들로 더불어 그것으로 마시고"]],"단 5:5-6":[["단 5:5","그 때에 사람의 손가락이 나타나서 왕궁 촛대 맞은편 분벽에 글자를 쓰는데 왕이 그 글자 쓰는 손가락을 본지라"],["단 5:6","이에 왕의 즐기던 빛이 변하고 그 생각이 번민하여 넓적다리 마디가 녹는듯하고 그 무릎이 서로 부딪힌지라"]],"단 5:26-29":[["단 5:26","그 뜻을 해석하건대 메네는 하나님이 이미 왕의 나라의 시대를 세어서 그것을 끝나게 하셨다 함이요"],["단 5:27","데겔은 왕이 저울에 달려서 부족함이 뵈었다 함이요"],["단 5:28","베레스는 왕의 나라가 나뉘어서 메대와 바사 사람에게 준바 되었다 함이니이다"],["단 5:29","이에 벨사살이 명하여 무리로 다니엘에게 자주옷을 입히게 하며 금 사슬로 그의 목에 드리우게 하고 그를 위하여 조서를 내려 나라의 세째 치리자를 삼으니라"]],"스 3:2; 학 1:1":[["스 3:2","요사닥의 아들 예수아와 그 형제 제사장들과 스알디엘의 아들 스룹바벨과 그 형제들이 다 일어나 이스라엘 하나님의 단을 만들고 하나님의 사람 모세의 율법에 기록한대로 번제를 그 위에 드리려 할쌔"],["학 1:1","다리오왕 이년 유월 곧 그 달 초하루에 여호와의 말씀이 선지자 학개로 말미암아 스알디엘의 아들 유다 총독 스룹바벨과 여호사닥의 아들 대제사장 여호수아에게 임하니라 가라사대"]],"학 1:1":[["학 1:1","다리오왕 이년 유월 곧 그 달 초하루에 여호와의 말씀이 선지자 학개로 말미암아 스알디엘의 아들 유다 총독 스룹바벨과 여호사닥의 아들 대제사장 여호수아에게 임하니라 가라사대"]],"스 2:1-2":[["스 2:1","옛적에 바벨론 왕 느부갓네살에게 사로잡혀 바벨론으로 갔던 자의 자손 중에서 놓임을 받고 예루살렘과 유다 도로 돌아와 각기 본성에 이른 자"],["스 2:2","곧 스룹바벨과 예수아와 느헤미야와 스라야와 르엘라야와 모르드개와 빌산과 미스발과 비그왜와 르훔과 바아나등과 함께 나온 이스라엘 백성의 명수가 이러하니"]],"스 3:8-10; 6:15":[["스 3:8","예루살렘 하나님의 전에 이른지 이년 이월에 스알디엘의 아들 스룹바벨과 요사닥의 아들 예수아와 다른 형제 제사장들과 레위 사람들과 무릇 사로잡혔다가 예루살렘에 돌아 온 자들이 역사를 시작하고 이십 세 이상의 레위 사람들을 세워 여호와의 전 역사를 감독하게 하매"],["스 3:9","이에 예수아와 그 아들들과 그 형제들과 갓미엘과 그 아들들과 유다 자손과 헤나닷 자손과 그 형제 레위 사람들이 일제히 일어나 하나님의 전 공장을 감독하니라"],["스 3:10","건축자가 여호와의 전 지대를 놓을 때에 제사장들은 예복을 입고 나팔을 들고 아삽 자손 레위 사람들은 제금을 들고 서서 이스라엘 왕 다윗의 규례대로 여호와를 찬송하되"],["스 6:15","다리오왕 육년 아달월 삼일에 전을 필역하니라"]],"마 1:6, 12":[["마 1:6","이새는 다윗왕을 낳으니라 다윗은 우리야의 아내에게서 솔로몬을 낳고"],["마 1:12","바벨론으로 이거한 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고"]],"학 1:1; 스 3:2":[["학 1:1","다리오왕 이년 유월 곧 그 달 초하루에 여호와의 말씀이 선지자 학개로 말미암아 스알디엘의 아들 유다 총독 스룹바벨과 여호사닥의 아들 대제사장 여호수아에게 임하니라 가라사대"],["스 3:2","요사닥의 아들 예수아와 그 형제 제사장들과 스알디엘의 아들 스룹바벨과 그 형제들이 다 일어나 이스라엘 하나님의 단을 만들고 하나님의 사람 모세의 율법에 기록한대로 번제를 그 위에 드리려 할쌔"]],"대상 3:19":[["대상 3:19","브다야의 아들들은 스룹바벨과 시므이요 스룹바벨의 아들은 므술람과 하나냐와 그 매제 슬로밋과"]],"대상 3:20":[["대상 3:20","또 하수바와 오헬과 베레갸와 하사댜와 유삽헤셋 다섯 사람이요"]],"마 1:12-16":[["마 1:12","바벨론으로 이거한 후에 여고냐는 스알디엘을 낳고 스알디엘은 스룹바벨을 낳고"],["마 1:13","스룹바벨은 아비훗을 낳고 아비훗은 엘리아김을 낳고 엘리아김은 아소르를 낳고"],["마 1:14","아소르는 사독을 낳고 사독은 아킴을 낳고 아킴은 엘리웃을 낳고"],["마 1:15","엘리웃은 엘르아살을 낳고 엘르아살은 맛단을 낳고 맛단은 야곱을 낳고"],["마 1:16","야곱은 마리아의 남편 요셉을 낳았으니 마리아에게서 그리스도라 칭하는 예수가 나시니라"]],"스 2:1-2, 64":[["스 2:1","옛적에 바벨론 왕 느부갓네살에게 사로잡혀 바벨론으로 갔던 자의 자손 중에서 놓임을 받고 예루살렘과 유다 도로 돌아와 각기 본성에 이른 자"],["스 2:2","곧 스룹바벨과 예수아와 느헤미야와 스라야와 르엘라야와 모르드개와 빌산과 미스발과 비그왜와 르훔과 바아나등과 함께 나온 이스라엘 백성의 명수가 이러하니"],["스 2:64","온 회중의 합계가 사만 이천 삼백 육십명이요"]],"스 3:1-2":[["스 3:1","이스라엘 자손이 그 본성에 거하였더니 칠월에 이르러 일제히 예루살렘에 모인지라"],["스 3:2","요사닥의 아들 예수아와 그 형제 제사장들과 스알디엘의 아들 스룹바벨과 그 형제들이 다 일어나 이스라엘 하나님의 단을 만들고 하나님의 사람 모세의 율법에 기록한대로 번제를 그 위에 드리려 할쌔"]],"스 3:8, 12":[["스 3:8","예루살렘 하나님의 전에 이른지 이년 이월에 스알디엘의 아들 스룹바벨과 요사닥의 아들 예수아와 다른 형제 제사장들과 레위 사람들과 무릇 사로잡혔다가 예루살렘에 돌아 온 자들이 역사를 시작하고 이십 세 이상의 레위 사람들을 세워 여호와의 전 역사를 감독하게 하매"],["스 3:12","제사장들과 레위 사람들과 족장들 중에 여러 노인은 첫 성전을 보았던고로 이제 이 전 지대 놓임을 보고 대성통곡하며 여러 사람은 기뻐하여 즐거이 부르니"]],"스 4:2-3":[["스 4:2","스룹바벨과 족장들에게 나아와 이르되 우리로 너희와 함께 건축하게 하라 우리도 너희 같이 너희 하나님을 구하노라 앗수르 왕 에살핫돈이 우리를 이리로 오게한 날부터 우리가 하나님께 제사를 드리노라"],["스 4:3","스룹바벨과 예수아와 기타 이스라엘 족장들이 이르되 우리 하나님의 전을 건축하는데 너희는 우리와 상관이 없느니라 바사 왕 고레스가 우리에게 명하신대로 우리가 이스라엘 하나님 여호와를 위하여 홀로 건축하리라 하였더니"]],"스 4:24":[["스 4:24","이에 예루살렘에서 하나님의 전 역사가 그쳐서 바사 왕 다리오 제 이년까지 이르니라"]],"학 1:1, 4":[["학 1:1","다리오왕 이년 유월 곧 그 달 초하루에 여호와의 말씀이 선지자 학개로 말미암아 스알디엘의 아들 유다 총독 스룹바벨과 여호사닥의 아들 대제사장 여호수아에게 임하니라 가라사대"],["학 1:4","이 전이 황무하였거늘 너희가 이 때에 판벽한 집에 거하는 것이 가하냐"]],"스 5:1-2":[["스 5:1","선지자들 곧 선지자 학개와 잇도의 손자 스가랴가 이스라엘 하나님의 이름을 받들어 유다와 예루살렘에 거하는 유다 사람들에게 예언하였더니"],["스 5:2","이에 스알디엘의 아들 스룹바벨과 요사닥의 아들 예수아가 일어나 예루살렘 하나님의 전 건축하기를 시작하매 하나님의 선지자들이 함께 하여 돕더니"]],"슥 4:6":[["슥 4:6","그가 내게 일러 가로되 여호와께서 스룹바벨에게 하신 말씀이 이러하니라 만군의 여호와께서 말씀하시되 이는 힘으로 되지 아니하며 능으로 되지아니하고 오직 나의 신으로 되느니라"]],"학 2:23":[["학 2:23","나 만군의 여호와가 말하노라 스알디엘의 아들 내 종 스룹바벨아 나 여호와가 말하노라 그 날에 내가 너를 취하고 너로 인을 삼으리니 이는 내가 너를 택하였음이니라 만군의 여호와의 말이니라"]],"단 5:31":[["단 5:31","메대 사람 다리오가 나라를 얻었는데 때에 다리오는 육십 이세였더라"]],"스 4:24; 5:1-2":[["스 4:24","이에 예루살렘에서 하나님의 전 역사가 그쳐서 바사 왕 다리오 제 이년까지 이르니라"],["스 5:1","선지자들 곧 선지자 학개와 잇도의 손자 스가랴가 이스라엘 하나님의 이름을 받들어 유다와 예루살렘에 거하는 유다 사람들에게 예언하였더니"],["스 5:2","이에 스알디엘의 아들 스룹바벨과 요사닥의 아들 예수아가 일어나 예루살렘 하나님의 전 건축하기를 시작하매 하나님의 선지자들이 함께 하여 돕더니"]],"스 5:3, 6":[["스 5:3","그 때에 강 서편 총독 닷드내와 스달보스내와 그 동료가 다 나아와 저희에게 이르되 누가 너희를 명하여 이 전을 건축하고 이 성곽을 마치게 하였느냐 하기로"],["스 5:6","강 서편 총독 닷드내와 스달보스내와 그 동료 강 서편 아바삭 사람이 다리오왕에게 올린 글의 초본이 이러하니라"]],"스 6:1-2, 8":[["스 6:1","이에 다리오왕이 조서를 내려 서적 곳간 곧 바벨론에서 보물을 쌓아둔 곳에서 조사하게 하였더니"],["스 6:2","메대도 악메다 궁에서 한 두루마리를 얻으니 거기 기록하였으되"],["스 6:8","내가 또 조서를 내려서 하나님의 이 전을 건축함에 대하여 너희가 유다 사람의 장로들에게 행할 것을 알게 하노니 왕의 재산 곧 강 서편 세금 중에서 그 경비를 이 사람들에게 신속히 주어 저희로 지체치 않게 하라"]],"에 1:1":[["에 1:1","이 일은 아하수에로왕 때에 된 것이니 아하수에로는 인도로 구스까지 일백 이십 칠도를 치리하는 왕이라"]],"에 1:2":[["에 1:2","당시에 아하수에로왕이 수산 궁에서 즉위하고"]],"에 1:9, 19":[["에 1:9","왕후 와스디도 아하수에로 왕궁에서 부녀들을 위하여 잔치를 베푸니라"],["에 1:19","왕이 만일 선히 여기실찐대 와스디로 다시는 왕 앞에 오지 못하게 하는 조서를 내리되 바사와 메대의 법률 중에 기록하여 변역함이 없게 하고 그 왕후의 위를 저보다 나은 사람에게 주소서"]],"스 4:6":[["스 4:6","또 아하수에로가 즉위할 때에 저희가 글을 올려 유다와 예루살렘 거민을 고소하니라"]],"에 1:3-4":[["에 1:3","위에 있은지 삼년에 그 모든 방백과 신복을 위하여 잔치를 베푸니 바사와 메대의 장수와 각 도의 귀족과 방백들이 다 왕 앞에 있는지라"],["에 1:4","왕이 여러 날 곧 일백 팔십일 동안에 그 영화로운 나라의 부함과 위엄의 혁혁함을 나타내니라"]],"에 1:12, 19":[["에 1:12","그러나 왕후 와스디가 내시의 전하는 왕명을 좇아 오기를 싫어하니 왕이 진노하여 중심이 불 붙는듯하더라"],["에 1:19","왕이 만일 선히 여기실찐대 와스디로 다시는 왕 앞에 오지 못하게 하는 조서를 내리되 바사와 메대의 법률 중에 기록하여 변역함이 없게 하고 그 왕후의 위를 저보다 나은 사람에게 주소서"]],"에 2:16-17":[["에 2:16","아하수에로왕의 칠년 시월 곧 데벳월에 에스더가 이끌려 왕궁에 들어가서 왕의 앞에 나아가니"],["에 2:17","왕이 모든 여자보다 에스더를 더욱 사랑하므로 저가 모든 처녀보다 왕의 앞에 더욱 은총을 얻은지라 왕이 그 머리에 면류관을 씌우고 와스디를 대신하여 왕후를 삼은 후에"]],"에 2:21-23":[["에 2:21","모르드개가 대궐 문에 앉았을 때에 문 지킨 왕의 내시 빅단과 데레스 두 사람이 아하수에로왕을 원한하여 모살하려 하거늘"],["에 2:22","모르드개가 알고 왕후 에스더에게 고하니 에스더가 모르드개의 이름으로 왕에게 고한지라"],["에 2:23","사실하여 실정을 얻었으므로 두 사람을 나무에 달고 그 일을 왕의 앞에서 궁중 일기에 기록하니라"]],"에 3:1, 10-13":[["에 3:1","그 후에 아하수에로왕이 아각 사람 함므다다의 아들 하만의 지위를 높이 올려 모든 함께 있는 대신 위에 두니"],["에 3:10","왕이 반지를 손에서 빼어 유다인의 대적 곧 아각 사람 함므다다의 아들 하만에게 주며"],["에 3:11","이르되 그 은을 네게 주고 그 백성도 그리하노니 너는 소견에 좋을대로 행하라 하더라"],["에 3:12","정월 십 삼일에 왕의 서기관이 소집되어 하만의 명을 따라 왕의 대신과 각 도 방백과 각 민족의 관원에게 아하수에로왕의 이름으로 조서를 쓰되 곧 각 도의 문자와 각 민족의 방언대로 쓰고 왕의 반지로 인치니라"],["에 3:13","이에 그 조서를 역졸에게 부쳐 왕의 각 도에 보내니 십이월 곧 아달월 십 삼일 하루 동안에 모든 유다인을 노소나 어린 아이나 부녀를 무론하고 죽이고 도륙하고 진멸하고 또 그 재산을 탈취하라 하였고"]],"에 6:1-3, 10":[["에 6:1","이 밤에 왕이 잠이 오지 아니하므로 명하여 역대 일기를 가져다가 자기 앞에서 읽히더니"],["에 6:2","그 속에 기록하기를 문 지킨 왕의 두 내시 빅다나와 데레스가 아하수에로왕을 모살하려 하는 것을 모르드개가 고발하였다 하였는지라"],["에 6:3","왕이 가로되 이 일을 인하여 무슨 존귀와 관작을 모르드개에게 베풀었느냐 시신이 대답하되 아무 것도 베풀지 아니 하였나이다"],["에 6:10","이에 왕이 하만에게 이르되 너는 네 말대로 속히 왕복과 말을 취하여 대궐 문에 앉은 유다 사람 모르드개에게 행하되 무릇 네가 말한 것에서 조금도 빠짐이 없이 하라"]],"에 7:6, 10":[["에 7:6","에스더가 가로되 대적과 원수는 이 악한 하만이니이다 하니 하만이 왕과 왕후 앞에서 두려워하거늘"],["에 7:10","모르드개를 달고자 한 나무에 하만을 다니 왕의 노가 그치니라"]],"에 8:11":[["에 8:11","조서에는 왕이 여러 고을에 있는 유다인에게 허락하여 저희로 함께 모여 스스로 생명을 보호하여 각 도의 백성 중 세력을 가지고 저희를 치려하는 자와 그 처자를 죽이고 도륙하고 진멸하고 그 재산을 탈취하게 하되"]],"에 2:7":[["에 2:7","저의 삼촌의 딸 하닷사 곧 에스더는 부모가 없고 용모가 곱고 아리따운 처녀라 그 부모가 죽은 후에 모르드개가 자기 딸 같이 양육하더라"]],"에 2:5, 15":[["에 2:5","도성 수산에 한 유다인이 있으니 이름은 모르드개라 저는 베냐민 자손이니 기스의 증손이요 시므이의 손자요 야일의 아들이라"],["에 2:15","모르드개의 삼촌 아비하일의 딸 곧 모르드개가 자기의 딸 같이 양육하는 에스더가 차례대로 왕에게 나아갈 때에 궁녀를 주관하는 내시 헤개의 정한 것 외에는 다른것을 구하지 아니하였으나 모든 보는 자에게 굄을 얻더라"]],"에 2:5, 8":[["에 2:5","도성 수산에 한 유다인이 있으니 이름은 모르드개라 저는 베냐민 자손이니 기스의 증손이요 시므이의 손자요 야일의 아들이라"],["에 2:8","왕의 조명이 반포되매 처녀들이 도성 수산에 많이 모여 헤개의 수하에 나아갈 때에 에스더도 왕궁으로 이끌려 가서 궁녀를 주관하는 헤개의 수하에 속하니"]],"에 2:15":[["에 2:15","모르드개의 삼촌 아비하일의 딸 곧 모르드개가 자기의 딸 같이 양육하는 에스더가 차례대로 왕에게 나아갈 때에 궁녀를 주관하는 내시 헤개의 정한 것 외에는 다른것을 구하지 아니하였으나 모든 보는 자에게 굄을 얻더라"]],"에 2:7, 15":[["에 2:7","저의 삼촌의 딸 하닷사 곧 에스더는 부모가 없고 용모가 곱고 아리따운 처녀라 그 부모가 죽은 후에 모르드개가 자기 딸 같이 양육하더라"],["에 2:15","모르드개의 삼촌 아비하일의 딸 곧 모르드개가 자기의 딸 같이 양육하는 에스더가 차례대로 왕에게 나아갈 때에 궁녀를 주관하는 내시 헤개의 정한 것 외에는 다른것을 구하지 아니하였으나 모든 보는 자에게 굄을 얻더라"]],"에 2:8, 12":[["에 2:8","왕의 조명이 반포되매 처녀들이 도성 수산에 많이 모여 헤개의 수하에 나아갈 때에 에스더도 왕궁으로 이끌려 가서 궁녀를 주관하는 헤개의 수하에 속하니"],["에 2:12","처녀마다 차례대로 아하수에로왕에게 나아가기 전에 여자에 대하여 정한 규례대로 열 두달 동안을 행하되 여섯달은 몰약 기름을 쓰고 여섯달은 향품과 여자에게 쓰는 다른 물품을 써서 몸을 정결케 하는 기한을 마치며"]],"에 2:10":[["에 2:10","에스더가 자기의 민족과 종족을 고하지 아니하니 이는 모르드개가 명하여 고하지 말라 하였음이라"]],"에 2:22":[["에 2:22","모르드개가 알고 왕후 에스더에게 고하니 에스더가 모르드개의 이름으로 왕에게 고한지라"]],"에 3:7, 13":[["에 3:7","아하수에로왕 십 이년 정월 곧 니산월에 무리가 하만 앞에서 날과 달에 대하여 부르 곧 제비를 뽑아 십이월 곧 아달월을 얻은지라"],["에 3:13","이에 그 조서를 역졸에게 부쳐 왕의 각 도에 보내니 십이월 곧 아달월 십 삼일 하루 동안에 모든 유다인을 노소나 어린 아이나 부녀를 무론하고 죽이고 도륙하고 진멸하고 또 그 재산을 탈취하라 하였고"]],"에 4:16; 5:1-2":[["에 4:16","당신은 가서 수산에 있는 유다인을 다 모으고 나를 위하여 금식하되 밤낮 삼일을 먹지도 말고 마시지도 마소서 나도 나의 시녀로 더불어 이렇게 금식한 후에 규례를 어기고 왕에게 나아가리니 죽으면 죽으리이다"],["에 5:1","제 삼일에 에스더가 왕후의 예복을 입고 왕궁 안 뜰 곧 어전 맞은편에 서니 왕이 어전에서 전 문을 대하여 보좌에 앉았다가"],["에 5:2","왕후 에스더가 뜰에 선 것을 본즉 심히 사랑스러우므로 손에 잡았던 금홀을 그에게 내어미니 에스더가 가까이 가서 금홀 끝을 만진지라"]],"에 7:3-6":[["에 7:3","왕후 에스더가 대답하여 가로되 왕이여 내가 만일 왕의 목전에서 은혜를 입었으며 왕이 선히 여기시거든 내 소청대로 내 생명을 내게 주시고 내 요구대로 내 민족을 내게 주소서"],["에 7:4","나와 내 민족이 팔려서 죽임과 도륙함과 진멸함을 당하게 되었나이다 만일 우리가 노비로 팔렸더면 내가 잠잠하였으리이다 그래도 대적이 왕의 손해를 보충하지 못하였으리이다"],["에 7:5","아하수에로왕이 왕후 에스더에게 일러 가로되 감히 이런 일을 심중에 품은 자가 누구며 그가 어디 있느뇨"],["에 7:6","에스더가 가로되 대적과 원수는 이 악한 하만이니이다 하니 하만이 왕과 왕후 앞에서 두려워하거늘"]],"에 8:5, 11":[["에 8:5","가로되 왕이 만일 즐겨하시며 내가 왕의 목전에 은혜를 입었고 또 왕이 이 일을 선히 여기시며 나를 기쁘게 보실찐대 조서를 내리사 아각 사람 함므다다의 아들 하만이 왕의 각 도에 있는 유다인을 멸하려고 꾀하고 쓴 조서를 취소하소서"],["에 8:11","조서에는 왕이 여러 고을에 있는 유다인에게 허락하여 저희로 함께 모여 스스로 생명을 보호하여 각 도의 백성 중 세력을 가지고 저희를 치려하는 자와 그 처자를 죽이고 도륙하고 진멸하고 그 재산을 탈취하게 하되"]],"에 9:29-32":[["에 9:29","아비하일의 딸 왕후 에스더와 유다인 모르드개가 전권으로 글을 쓰고 부림에 대한 이 둘째 편지를 굳이 지키게 하되"],["에 9:30","화평하고 진실한 말로 편지를 써서 아하수에로의 나라 일백 이십 칠도에 있는 유다 모든 사람에게 보내어"],["에 9:31","정한 기한에 이 부림일을 지키게 하였으니 이는 유다인 모르드개와 왕후 에스더의 명한바와 유다인이 금식하며 부르짖은 것을 인하여 자기와 자기 자손을 위하여 정한 바가 있음이더라"],["에 9:32","에스더의 명령이 이 부림에 대한 일을 견고히 하였고 그 일이 책에 기록되었더라"]],"스 7:1-5":[["스 7:1","이 일 후 바사 왕 아닥사스다가 위에 있을 때에 에스라라 하는 자가 있으니라 저는 스라야의 아들이요 아사랴의 손자요 힐기야의 증손이요"],["스 7:2","살룸의 현손이요 사독의 오대손이요 아히둡의 육대손이요"],["스 7:3","아마랴의 칠대손이요 아사랴의 팔대손이요 므라욧의 구대손이요"],["스 7:4","스라히야의 십대손이요 웃시엘의 십 일대손이요 북기의 십 이대손이요"],["스 7:5","아비수아의 십 삼대손이요 비느하스의 십 사대손이요 엘르아살의 십 오대손이요 대제사장 아론의 십 륙대손이라"]],"스 7:6, 11":[["스 7:6","이 에스라가 바벨론에서 올라왔으니 저는 이스라엘 하나님 여호와께서 주신바 모세의 율법에 익숙한 학사로서 그 하나님 여호와의 도우심을 입으므로 왕에게 구하는 것은 다 받는 자더니"],["스 7:11","여호와의 계명의 말씀과 이스라엘에게 주신 율례의 학사인 학사겸 제사장 에스라에게 아닥사스다왕이 내린 조서 초본은 아래와 같으니라"]],"스 7:7-8":[["스 7:7","아닥사스다왕 칠년에 이스라엘 자손과 제사장들과 레위 사람들과 노래하는 자들과 문지기들과 느디님 사람들 중에 몇 사람이 예루살렘으로 올라올 때에"],["스 7:8","이 에스라가 올라왔으니 왕의 칠년 오월이라"]],"스 7:25":[["스 7:25","에스라여 너는 네 손에 있는 네 하나님의 지혜를 따라 네 하나님의 율법을 아는 자로 유사와 재판관을 삼아 강 서편 모든 백성을 재판하게 하고 그 알지 못하는 자는 너희가 가르치라"]],"스 7:5":[["스 7:5","아비수아의 십 삼대손이요 비느하스의 십 사대손이요 엘르아살의 십 오대손이요 대제사장 아론의 십 륙대손이라"]],"스 7:1-2":[["스 7:1","이 일 후 바사 왕 아닥사스다가 위에 있을 때에 에스라라 하는 자가 있으니라 저는 스라야의 아들이요 아사랴의 손자요 힐기야의 증손이요"],["스 7:2","살룸의 현손이요 사독의 오대손이요 아히둡의 육대손이요"]],"스 7:1":[["스 7:1","이 일 후 바사 왕 아닥사스다가 위에 있을 때에 에스라라 하는 자가 있으니라 저는 스라야의 아들이요 아사랴의 손자요 힐기야의 증손이요"]],"스 7:7, 9":[["스 7:7","아닥사스다왕 칠년에 이스라엘 자손과 제사장들과 레위 사람들과 노래하는 자들과 문지기들과 느디님 사람들 중에 몇 사람이 예루살렘으로 올라올 때에"],["스 7:9","정월 초하루에 바벨론에서 길을 떠났고 하나님의 선한 손의 도우심을 입어 오월 초하루에 예루살렘에 이르니라"]],"스 8:21-22":[["스 8:21","때에 내가 아하와강 가에서 금식을 선포하고 우리 하나님 앞에서 스스로 겸비하여 우리와 우리 어린것과 모든 소유를 위하여 평탄한 길을 그에게 간구하였으니"],["스 8:22","이는 우리가 전에 왕에게 고하기를 우리 하나님의 손은 자기를 찾는 모든 자에게 선을 베푸시고 자기를 배반하는 모든 자에게는 권능과 진노를 베푸신다 하였으므로 길에서 적군을 막고 우리를 도울 보병과 마병을 왕에게 구하기를 부끄러워 하였음이라"]],"스 7:9":[["스 7:9","정월 초하루에 바벨론에서 길을 떠났고 하나님의 선한 손의 도우심을 입어 오월 초하루에 예루살렘에 이르니라"]],"스 9:3, 6":[["스 9:3","내가 이 일을 듣고 속옷과 겉옷을 찢고 머리털과 수염을 뜯으며 기가 막혀 앉으니"],["스 9:6","말하기를 나의 하나님이여 내가 부끄러워 낯이 뜨뜻하여 감히 나의 하나님을 향하여 얼굴을 들지 못하오니 이는 우리 죄악이 많아 정수리에 넘치고 우리 허물이 커서 하늘에 미침이니이다"]],"스 10:3, 10-11":[["스 10:3","곧 내 주의 교훈을 좇으며 우리 하나님의 명령을 떨며 준행하는 자의 의논을 좇아 이 모든 아내와 그 소생을 다 내어 보내기로 우리 하나님과 언약을 세우고 율법대로 행할 것이라"],["스 10:10","제사장 에스라가 일어서서 저희에게 이르되 너희가 범죄하여 이방 여자로 아내를 삼아 이스라엘의 죄를 더하게 하였으니"],["스 10:11","이제 너희 열조의 하나님 앞에서 죄를 자복하고 그 뜻대로 행하여 이 땅 족속들과 이방 여인을 끊어 버리라"]],"느 8:1-4":[["느 8:1","이스라엘 자손이 그 본성에 거하였더니 칠월에 이르러는 모든 백성이 일제히 수문 앞 광장에 모여 학사 에스라에게 여호와께서 이스라엘에게 명하신 모세의 율법책을 가지고 오기를 청하매"],["느 8:2","칠월 일일에 제사장 에스라가 율법책을 가지고 남자, 여자 무릇 알아 들을만한 회중 앞에 이르러"],["느 8:3","수문 앞 광장에서 새벽부터 오정까지 남자, 여자 무릇 알아 들을만한 자의 앞에서 읽으매 뭇백성이 그 율법책에 귀를 기울였는데"],["느 8:4","때에 학사 에스라가 특별히 지은 나무 강단에 서매 그 우편에 선 자는 맛디댜와 스마와 아나야와 우리야와 힐기야와 마아세야요 그 좌편에 선 자는 브다야와 미사엘과 말기야와 하숨과 하스밧다나와 스가랴와 므술람이라"]],"느 8:8":[["느 8:8","하나님의 율법 책을 낭독하고 그 뜻을 해석하여 백성으로 그 낭독하는 것을 다 깨닫게 하매"]],"느 8:14-17":[["느 8:14","율법책을 본즉 여호와께서 모세로 명하시기를 이스라엘 자손은 칠월 절기에 초막에 거할찌니라 하였고"],["느 8:15","또 일렀으되 모든 성읍과 예루살렘에 공포하여 이르기를 너희는 산에 가서 감람나무 가지와 들 감람나무 가지와 화석류나무 가지와 종려나무 가지와 기타 무성한 나무 가지를 취하여 기록한바를 따라 초막을 지으라 하라 하였는지라"],["느 8:16","백성이 이에 나가서 나무 가지를 취하여 혹은 지붕 위에, 혹은 뜰 안에, 혹은 하나님의 전 뜰에, 혹은 수문 광장에, 혹은 에브라임 문 광장에 초막을 짓되"],["느 8:17","사로잡혔다가 돌아온 회 무리가 다 초막을 짓고 그 안에 거하니 눈의 아들 여호수아 때로부터 그 날까지 이스라엘 자손이 이같이 행함이 없었으므로 이에 크게 즐거워하며"]],"느 12:36":[["느 12:36","그 형제 스마야와 아사렐과 밀랄래와 길랄래와 마애와 느다넬과 유다와 하나니라 다 하나님의 사람 다윗의 악기를 잡았고 학사 에스라가 앞서서"]],"느 1:1":[["느 1:1","하가랴의 아들 느헤미야의 말이라 아닥사스다왕 제 이십년 기슬르월에 내가 수산궁에 있더니"]],"느 1:11":[["느 1:11","주여 구하오니 귀를 기울이사 종의 기도와 주의 이름을 경외하기를 기뻐하는 종들의 기도를 들으시고 오늘날 종으로 형통하여 이 사람 앞에서 은혜를 입게 하옵소서 하였나니 그 때에 내가 왕의 술 관원이 되었었느니라"]],"느 5:14":[["느 5:14","내가 유다 땅 총독으로 세움을 받은 때 곧 아닥사스다왕 이십년부터 삼십 이년까지 십 이년 동안은 나와 내 형제가 총독의 녹을 먹지 아니하였느니라"]],"느 1:2; 7:2":[["느 1:2","나의 한 형제 중 하나니가 두어 사람과 함께 유다에서 이르렀기로 내가 그 사로잡힘을 면하고 남아 있는 유다 사람과 예루살렘 형편을 물은즉"],["느 7:2","내 아우 하나니와 영문의 관원 하나냐로 함께 예루살렘을 다스리게 하였는데 하나냐는 위인이 충성되어 하나님을 경외함이 무리에서 뛰어난 자라"]],"느 1:1-4":[["느 1:1","하가랴의 아들 느헤미야의 말이라 아닥사스다왕 제 이십년 기슬르월에 내가 수산궁에 있더니"],["느 1:2","나의 한 형제 중 하나니가 두어 사람과 함께 유다에서 이르렀기로 내가 그 사로잡힘을 면하고 남아 있는 유다 사람과 예루살렘 형편을 물은즉"],["느 1:3","저희가 내게 이르되 사로잡힘을 면하고 남은 자가 그 도에서 큰 환난을 만나고 능욕을 받으며 예루살렘성은 훼파되고 성문들은 소화되었다 하는지라"],["느 1:4","내가 이 말을 듣고 앉아서 울고 수일 동안 슬퍼하며 하늘의 하나님 앞에 금식하며 기도하여"]],"느 2:1-6":[["느 2:1","아닥사스다왕 이십년 니산월에 왕의 앞에 술이 있기로 내가 들어 왕에게 드렸는데 이전에는 내가 왕의 앞에서 수색이 없었더니"],["느 2:2","왕이 내게 이르시되 네가 병이 없거늘 어찌하여 얼굴에 수색이 있느냐 이는 필연 네 마음에 근심이 있음이로다 그 때에 내가 크게 두려워하여"],["느 2:3","왕께 대답하되 왕은 만세수를 하옵소서 나의 열조의 묘실 있는 성읍이 이제까지 황무하고 성문이 소화되었사오니 내가 어찌 얼굴에 수색이 없사오리이까"],["느 2:4","왕이 내게 이르시되 그러면 네가 무엇을 원하느냐 하시기로 내가 곧 하늘의 하나님께 묵도하고"],["느 2:5","왕에게 고하되 왕이 만일 즐겨하시고 종이 왕의 목전에서 은혜를 얻었사오면 나를 유다 땅 나의 열조의 묘실 있는 성읍에 보내어 그 성을 중건하게 하옵소서 하였는데"],["느 2:6","그 때에 왕후도 왕의 곁에 앉았더라 왕이 내게 이르시되 네가 몇날에 행할 길이며 어느 때에 돌아 오겠느냐 하고 왕이 나를 보내기를 즐겨하시기로 내가 기한을 정하고"]],"느 2:12-15":[["느 2:12","내 하나님이 내 마음을 감화하사 예루살렘을 위하여 행하게 하신 일을 내가 아무 사람에게도 말하지 아니하고 밤에 일어나 두어 사람과 함께 나갈쌔 내가 탄 짐승 외에는 다른 짐승이 없더라"],["느 2:13","그 밤에 골짜기 문으로 나가서 용정으로 분문에 이르는 동안에 보니 예루살렘 성벽이 다 무너졌고 성문은 소화되었더라"],["느 2:14","앞으로 행하여 샘문과 왕의 못에 이르러는 탄 짐승이 지나갈 곳이 없는지라"],["느 2:15","그 밤에 시내를 좇아 올라가서 성벽을 살펴 본 후에 돌이켜 골짜기 문으로 들어와서 돌아 왔으나"]],"느 2:19":[["느 2:19","호론 사람 산발랏과 종이 되었던 암몬 사람 도비야와 아라비아 사람 게셈이 이 말을 듣고 우리를 업신여기고 비웃어 가로되 너희의 하는 일이 무엇이냐 왕을 배반코자 하느냐 하기로"]],"느 4:17":[["느 4:17","성을 건축하는 자와 담부하는 자는 다 각각 한 손으로 일을 하며 한 손에는 병기를 잡았는데"]],"느 5:10-11, 14":[["느 5:10","나와 내 형제와 종자들도 역시 돈과 곡식을 백성에게 취하여 주나니 우리가 그 이식 받기를 그치자"],["느 5:11","그런즉 너희는 오늘이라도 그 밭과 포도원과 감람원과 집이며 취한바 돈이나 곡식이나 새 포도주나 기름의 백분지 일을 돌려 보내라 하였더니"],["느 5:14","내가 유다 땅 총독으로 세움을 받은 때 곧 아닥사스다왕 이십년부터 삼십 이년까지 십 이년 동안은 나와 내 형제가 총독의 녹을 먹지 아니하였느니라"]],"느 8:2; 9:38":[["느 8:2","칠월 일일에 제사장 에스라가 율법책을 가지고 남자, 여자 무릇 알아 들을만한 회중 앞에 이르러"],["느 9:38","우리가 이 모든 일을 인하여 이제 견고한 언약을 세워 기록하고 우리의 방백들과 레위 사람들과 제사장들이 다 인을 치나이다 하였느니라"]],"느 12:27":[["느 12:27","예루살렘 성곽이 낙성되니 각처에서 레위 사람들을 찾아 예루살렘으로 데려다가 감사하며 노래하며 제금 치며 비파와 수금을 타며 즐거이 봉헌식을 행하려 하매"]],"느 13:6-8":[["느 13:6","그 때에는 내가 예루살렘에 있지 아니하였었느니라 바벨론 왕 아닥사스다 삼십 이년에 내가 왕에게 나아갔다가 며칠 후에 왕에게 말미를 청하고"],["느 13:7","예루살렘에 이르러서야 엘리아십이 도비야를 위하여 하나님의 전 뜰에 방을 갖춘 악한 일을 안지라"],["느 13:8","내가 심히 근심하여 도비야의 세간을 그 방 밖으로 다 내어 던지고"]],"느 13:19":[["느 13:19","안식일 전 예루살렘 성문이 어두워 갈 때에 내가 명하여 성문을 닫고 안식일이 지나기 전에는 열지 말라 하고 내 종자 두어 사람을 성문마다 세워서 안식일에 아무 짐도 들어 오지 못하게 하매"]],"요 10:22-23":[["요 10:22","예루살렘에 수전절이 이르니 때는 겨울이라"],["요 10:23","예수께서 성전 안 솔로몬 행각에서 다니시니"]],"마 2:19":[["마 2:19","헤롯이 죽은 후에 주의 사자가 애굽에서 요셉에게 현몽하여 가로되"]],"마 2:22":[["마 2:22","그러나 아켈라오가 그 부친 헤롯을 이어 유대의 임금 됨을 듣고 거기로 가기를 무서워하더니 꿈에 지시하심을 받아 갈릴리 지방으로 떠나가"]],"행 12:1-2":[["행 12:1","그 때에 헤롯왕이 손을 들어 교회 중 몇 사람을 해하려하여"],["행 12:2","요한의 형제 야고보를 칼로 죽이니"]],"막 6:17":[["막 6:17","전에 헤롯이 자기가 동생 빌립의 아내 헤로디아에게 장가 든 고로 이 여자를 위하여 사람을 보내어 요한을 잡아 옥에 가두었으니"]],"행 25:13":[["행 25:13","수일 후에 아그립바왕과 버니게가 베스도에게 문안하러 가이사랴에 와서"]],"마 2:1-3":[["마 2:1","헤롯왕 때에 예수께서 유대 베들레헴에서 나시매 동방으로부터 박사들이 예루살렘에 이르러 말하되"],["마 2:2","유대인의 왕으로 나신 이가 어디 계시뇨 우리가 동방에서 그의 별을 보고 그에게 경배하러 왔노라 하니"],["마 2:3","헤롯왕과 온 예루살렘이 듣고 소동한지라"]],"마 2:16":[["마 2:16","이에 헤롯이 박사들에게 속은 줄을 알고 심히 노하여 사람을 보내어 베들레헴과 그 모든 지경 안에 있는 사내 아이를 박사들에게 자세히 알아본 그 때를 표준하여 두 살부터 그 아래로 다 죽이니"]],"마 2:19, 22":[["마 2:19","헤롯이 죽은 후에 주의 사자가 애굽에서 요셉에게 현몽하여 가로되"],["마 2:22","그러나 아켈라오가 그 부친 헤롯을 이어 유대의 임금 됨을 듣고 거기로 가기를 무서워하더니 꿈에 지시하심을 받아 갈릴리 지방으로 떠나가"]],"눅 1:13, 59-63":[["눅 1:13","천사가 일러 가로되 사가랴여 무서워 말라 너의 간구함이 들린지라 네 아내 엘리사벳이 네게 아들을 낳아 주리니 그 이름을 요한이라 하라"],["눅 1:59","팔일이 되매 아이를 할례하러 와서 그 부친의 이름을 따라 사가랴라 하고자 하더니"],["눅 1:60","그 모친이 대답하여 가로되 아니라 요한이라 할 것이라 하매"],["눅 1:61","저희가 가로되 네 친족 중에 이 이름으로 이름한 이가 없다 하고"],["눅 1:62","그 부친께 형용하여 무엇으로 이름하려 하는가 물으니"],["눅 1:63","저가 서판을 달라 하여 그 이름은 요한이라 쓰매 다 기이히 여기더라"]],"눅 1:26, 36":[["눅 1:26","여섯째 달에 천사 가브리엘이 하나님의 보내심을 받들어 갈릴리 나사렛이란 동네에 가서"],["눅 1:36","보라 네 친족 엘리사벳도 늙어서 아들을 배었느니라 본래 수태하지 못한다 하던 이가 이미 여섯 달이 되었나니"]],"마 3:1; 막 1:4-5":[["마 3:1","그 때에 세례 요한이 이르러 유대 광야에서 전파하여 가로되"],["막 1:4","세례 요한이 이르러 광야에서 죄 사함을 받게 하는 회개의 세례를 전파하니"],["막 1:5","온 유대 지방과 예루살렘 사람이 다 나아가 자기 죄를 자복하고 요단강에서 그에게 세례를 받더라"]],"마 3:4":[["마 3:4","이 요한은 약대 털옷을 입고 허리에 가죽띠를 띠고 음식은 메뚜기와 석청이었더라"]],"막 6:27":[["막 6:27","왕이 곧 시위병 하나를 보내어 요한의 머리를 가져오라 명하니 그 사람이 나가 옥에서 요한을 목 베어"]],"눅 1:5-7":[["눅 1:5","유대 왕 헤롯 때에 아비야 반열에 제사장 하나가 있으니 이름은 사가랴요 그 아내는 아론의 자손이니 이름은 엘리사벳이라"],["눅 1:6","이 두 사람이 하나님 앞에 의인이니 주의 모든 계명과 규례대로 흠이 없이 행하더라"],["눅 1:7","엘리사벳이 수태를 못하므로 저희가 무자하고 두 사람의 나이 많더라"]],"눅 1:11-13":[["눅 1:11","주의 사자가 저에게 나타나 향단 우편에 선지라"],["눅 1:12","사가랴가 보고 놀라며 무서워하니"],["눅 1:13","천사가 일러 가로되 사가랴여 무서워 말라 너의 간구함이 들린지라 네 아내 엘리사벳이 네게 아들을 낳아 주리니 그 이름을 요한이라 하라"]],"눅 1:59-64":[["눅 1:59","팔일이 되매 아이를 할례하러 와서 그 부친의 이름을 따라 사가랴라 하고자 하더니"],["눅 1:60","그 모친이 대답하여 가로되 아니라 요한이라 할 것이라 하매"],["눅 1:61","저희가 가로되 네 친족 중에 이 이름으로 이름한 이가 없다 하고"],["눅 1:62","그 부친께 형용하여 무엇으로 이름하려 하는가 물으니"],["눅 1:63","저가 서판을 달라 하여 그 이름은 요한이라 쓰매 다 기이히 여기더라"],["눅 1:64","이에 그 입이 곧 열리고 혀가 풀리며 말을 하여 하나님을 찬송하니"]],"눅 1:80":[["눅 1:80","아이가 자라며 심령이 강하여지며 이스라엘에게 나타나는 날까지 빈 들에 있으니라"]],"눅 3:1-3":[["눅 3:1","디베료 가이사가 위에 있은지 열 다섯 해 곧 본디오 빌라도가 유대의 총독으로, 헤롯이 갈릴리의 분봉왕으로, 그 동생 빌립이 이두래와 드라고닛 지방의 분봉왕으로, 루사니아가 아빌레네의 분봉왕으로,"],["눅 3:2","안나스와 가야바가 대제사장으로 있을 때에 하나님의 말씀이 빈 들에서 사가랴의 아들 요한에게 임한지라"],["눅 3:3","요한이 요단강 부근 각처에 와서 죄 사함을 얻게 하는 회개의 세례를 전파하니"]],"마 3:13-15":[["마 3:13","이 때에 예수께서 갈릴리로서 요단강에 이르러 요한에게 세례를 받으려 하신대"],["마 3:14","요한이 말려 가로되 내가 당신에게 세례를 받아야 할 터인데 당신이 내게로 오시나이까"],["마 3:15","예수께서 대답하여 가라사대 이제 허락하라 우리가 이와 같이 하여 모든 의를 이루는 것이 합당하니라 하신대 이에 요한이 허락하는지라"]],"요 1:29":[["요 1:29","이튿날 요한이 예수께서 자기에게 나아오심을 보고 가로되 보라 세상 죄를 지고 가는 하나님의 어린 양이로다"]],"막 6:17-18":[["막 6:17","전에 헤롯이 자기가 동생 빌립의 아내 헤로디아에게 장가 든 고로 이 여자를 위하여 사람을 보내어 요한을 잡아 옥에 가두었으니"],["막 6:18","이는 요한이 헤롯에게 말하되 동생의 아내를 취한 것이 옳지 않다 하였음이라"]],"마 11:2-3":[["마 11:2","요한이 옥에서 그리스도의 하신 일을 듣고 제자들을 보내어"],["마 11:3","예수께 여짜오되 오실 그이가 당신이오니이까 우리가 다른이를 기다리오리이까"]],"막 6:24-28":[["막 6:24","저가 나가서 그 어미에게 말하되 내가 무엇을 구하리이까 그 어미가 가로되 세례 요한의 머리를 구하라 하니"],["막 6:25","저가 곧 왕에게 급히 들어가 구하여 가로되 세례 요한의 머리를 소반에 담아 곧 내게 주기를 원하옵나이다 한대"],["막 6:26","왕이 심히 근심하나 자기의 맹세한 것과 그 앉은 자들을 인하여 저를 거절할 수 없는지라"],["막 6:27","왕이 곧 시위병 하나를 보내어 요한의 머리를 가져오라 명하니 그 사람이 나가 옥에서 요한을 목 베어"],["막 6:28","그 머리를 소반에 담아다가 여아에게 주니 여아가 이것을 그 어미에게 주니라"]],"요 1:42":[["요 1:42","데리고 예수께로 오니 예수께서 보시고 가라사대 네가 요한의 아들 시몬이니 장차 게바라 하리라 하시니라 (게바는 번역하면 베드로라)"]],"마 16:17; 요 1:42":[["마 16:17","예수께서 대답하여 가라사대 바요나 시몬아 네가 복이 있도다 이를 네게 알게 한 이는 혈육이 아니요 하늘에 계신 내 아버지시니라"],["요 1:42","데리고 예수께로 오니 예수께서 보시고 가라사대 네가 요한의 아들 시몬이니 장차 게바라 하리라 하시니라 (게바는 번역하면 베드로라)"]],"요 1:44":[["요 1:44","빌립은 안드레와 베드로와 한 동네 벳새다 사람이라"]],"막 1:21, 29-30":[["막 1:21","저희가 가버나움에 들어가니라 예수께서 곧 안식일에 회당에 들어가 가르치시매"],["막 1:29","회당에서 나와 곧 야고보와 요한과 함께 시몬과 안드레의 집에 들어가시니"],["막 1:30","시몬의 장모가 열병으로 누웠는지라 사람들이 곧 그의 일로 예수께 여짜온대"]],"마 4:18":[["마 4:18","갈릴리 해변에 다니시다가 두 형제 곧 베드로라 하는 시몬과 그 형제 안드레가 바다에 그물 던지는 것을 보시니 저희는 어부라"]],"요 21:18-19":[["요 21:18","내가 진실로 진실로 네게 이르노니 젊어서는 네가 스스로 띠 띠고 원하는 곳으로 다녔거니와 늙어서는 네 팔을 벌리리니 남이 네게 띠 띠우고 원치 아니하는 곳으로 데려가리라"],["요 21:19","이 말씀을 하심은 베드로가 어떠한 죽음으로 하나님께 영광을 돌릴 것을 가리키심이러라 이 말씀을 하시고 베드로에게 이르시되 나를 따르라 하시니"]],"고전 9:5":[["고전 9:5","우리가 다른 사도들과 주의 형제들과 게바와 같이 자매 된 아내를 데리고 다닐 권이 없겠느냐"]],"막 1:30-31":[["막 1:30","시몬의 장모가 열병으로 누웠는지라 사람들이 곧 그의 일로 예수께 여짜온대"],["막 1:31","나아가사 그 손을 잡아 일으키시니 열병이 떠나고 여자가 저희에게 수종드니라"]],"요 1:40-42":[["요 1:40","요한의 말을 듣고 예수를 좇는 두 사람 중에 하나는 시몬 베드로의 형제 안드레라"],["요 1:41","그가 먼저 자기의 형제 시몬을 찾아 말하되 우리가 메시야를 만났다 하고 (메시야는 번역하면 그리스도라)"],["요 1:42","데리고 예수께로 오니 예수께서 보시고 가라사대 네가 요한의 아들 시몬이니 장차 게바라 하리라 하시니라 (게바는 번역하면 베드로라)"]],"막 1:16-18":[["막 1:16","갈릴리 해변으로 지나가시다가 시몬과 그 형제 안드레가 바다에 그물 던지는 것을 보시니 저희는 어부라"],["막 1:17","예수께서 가라사대 나를 따라 오너라 내가 너희로 사람을 낚는 어부가 되게 하리라 하시니"],["막 1:18","곧 그물을 버려 두고 좇으니라"]],"마 14:29-30":[["마 14:29","오라 하시니 베드로가 배에서 내려 물 위로 걸어서 예수께로 가되"],["마 14:30","바람을 보고 무서워 빠져 가는지라 소리질러 가로되 주여 나를 구원하소서 하니"]],"마 16:16":[["마 16:16","시몬 베드로가 대답하여 가로되 주는 그리스도시요 살아계신 하나님의 아들이시니이다"]],"마 17:1-2":[["마 17:1","엿새 후에 예수께서 베드로와 야고보와 그 형제 요한을 데리시고 따로 높은 산에 올라가셨더니"],["마 17:2","저희 앞에서 변형되사 그 얼굴이 해 같이 빛나며 옷이 빛과 같이 희어졌더라"]],"마 26:74-75":[["마 26:74","저가 저주하며 맹세하여 가로되 내가 그 사람을 알지 못하노라 하니 닭이 곧 울더라"],["마 26:75","이에 베드로가 예수의 말씀에 닭 울기 전에 네가 세번 나를 부인하리라 하심이 생각나서 밖에 나가서 심히 통곡하니라"]],"요 20:3-6; 고전 15:5":[["요 20:3","베드로와 그 다른 제자가 나가서 무덤으로 갈쌔"],["요 20:4","둘이 같이 달음질하더니 그 다른 제자가 베드로보다 더 빨리 달아나서 먼저 무덤에 이르러"],["요 20:5","구푸려 세마포 놓인 것을 보았으나 들어가지는 아니하였더니"],["요 20:6","시몬 베드로도 따라 와서 무덤에 들어가 보니 세마포가 놓였고"],["고전 15:5","게바에게 보이시고 후에 열 두 제자에게와"]],"요 21:15-17":[["요 21:15","저희가 조반 먹은 후에 예수께서 시몬 베드로에게 이르시되 요한의 아들 시몬아 네가 이 사람들보다 나를 더 사랑하느냐 하시니 가로되 주여 그러하외다 내가 주를 사랑하는줄 주께서 아시나이다 가라사대 내 어린 양을 먹이라 하시고"],["요 21:16","또 두번째 가라사대 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 가로되 주여 그러하외다 내가 주를 사랑하는줄 주께서 아시나이다 가라사대 내 양을 치라 하시고"],["요 21:17","세번째 가라사대 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 주께서 세번째 네가 나를 사랑하느냐 하시므로 베드로가 근심하여 가로되 주여 모든 것을 아시오매 내가 주를 사랑하는 줄을 주께서 아시나이다 예수께서 가라사대 내 양을 먹이라"]],"행 2:14, 41":[["행 2:14","베드로가 열 한 사도와 같이 서서 소리를 높여 가로되 유대인들과 예루살렘에 사는 모든 사람들아 이 일을 너희로 알게 할 것이니 내 말에 귀를 기울이라"],["행 2:41","그 말을 받는 사람들은 세례를 받으매 이 날에 제자의 수가 삼천이나 더하더라"]],"행 3:6-8":[["행 3:6","베드로가 가로되 은과 금은 내게 없거니와 내게 있는 것으로 네게 주노니 곧 나사렛 예수 그리스도의 이름으로 걸으라 하고"],["행 3:7","오른손을 잡아 일으키니 발과 발목이 곧 힘을 얻고"],["행 3:8","뛰어 서서 걸으며 그들과 함께 성전으로 들어 가면서 걷기도 하고 뛰기도 하며 하나님을 찬미하니"]],"행 9:40; 10:47-48":[["행 9:40","베드로가 사람을 다 내어보내고 무릎을 꿇고 기도하고 돌이켜 시체를 향하여 가로되 다비다야 일어나라 하니 그가 눈을 떠 베드로를 보고 일어나 앉는지라"],["행 10:47","이에 베드로가 가로되 이 사람들이 우리와 같이 성령을 받았으니 누가 능히 물로 세례 줌을 금하리요 하고"],["행 10:48","명하여 예수 그리스도의 이름으로 세례를 주라 하니라 저희가 베드로에게 수일 더 유하기를 청하니라"]],"행 12:6-7":[["행 12:6","헤롯이 잡아 내려고 하는 그 전날 밤에 베드로가 두 군사 틈에서 두 쇠사슬에 매여 누워 자는데 파숫군들이 문 밖에서 옥을 지키더니"],["행 12:7","홀연히 주의 사자가 곁에 서매 옥중에 광채가 조요하며 또 베드로의 옆구리를 쳐 깨워 가로되 급히 일어나라 하니 쇠사슬이 그 손에서 벗어지더라"]],"행 15:7, 11":[["행 15:7","많은 변론이 있은 후에 베드로가 일어나 말하되 형제들아 너희도 알거니와 하나님이 이방인들로 내 입에서 복음의 말씀을 들어 믿게 하시려고 오래 전부터 너희 가운데서 나를 택하시고"],["행 15:11","우리가 저희와 동일하게 주 예수의 은혜로 구원 받는 줄을 믿노라 하니라"]],"갈 2:11-12":[["갈 2:11","게바가 안디옥에 이르렀을 때에 책망할 일이 있기로 내가 저를 면책하였노라"],["갈 2:12","야고보에게서 온 어떤이들이 이르기 전에 게바가 이방인과 함께 먹다가 저희가 오매 그가 할례자들을 두려워하여 떠나 물러가매"]],"행 6:3, 5":[["행 6:3","형제들아 너희 가운데서 성령과 지혜가 충만하여 칭찬 듣는 사람 일곱을 택하라 우리가 이 일을 저희에게 맡기고"],["행 6:5","온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교한 안디옥 사람 니골라를 택하여"]],"행 6:5":[["행 6:5","온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교한 안디옥 사람 니골라를 택하여"]],"행 6:8":[["행 6:8","스데반이 은혜와 권능이 충만하여 큰 기사와 표적을 민간에 행하니"]],"행 7:58-60":[["행 7:58","성 밖에 내치고 돌로 칠쌔 증인들이 옷을 벗어 사울이라 하는 청년의 발앞에 두니라"],["행 7:59","저희가 돌로 스데반을 치니 스데반이 부르짖어 가로되 주 예수여 내 영혼을 받으시옵소서 하고"],["행 7:60","무릎을 꿇고 크게 불러 가로되 주여 이 죄를 저들에게 돌리지 마옵소서 이 말을 하고 자니라"]],"행 6:5-6":[["행 6:5","온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교한 안디옥 사람 니골라를 택하여"],["행 6:6","사도들 앞에 세우니 사도들이 기도하고 그들에게 안수하니라"]],"행 6:9-10":[["행 6:9","리버디노 구레네인, 알렉산드리아인, 길리기아와 아시아에서 온 사람들의 회당이라는 각 회당에서 어떤자들이 일어나 스데반으로 더불어 변론할쌔"],["행 6:10","스데반이 지혜와 성령으로 말함을 저희가 능히 당치 못하여"]],"행 6:13":[["행 6:13","거짓 증인들을 세우니 가로되 이 사람이 이 거룩한 곳과 율법을 거스려 말하기를 마지 아니하는도다"]],"행 6:15":[["행 6:15","공회 중에 앉은 사람들이 다 스데반을 주목하여 보니 그 얼굴이 천사의 얼굴과 같더라"]],"행 7:2, 47":[["행 7:2","스데반이 가로되 여러분 부형들이여 들으소서 우리 조상 아브라함이 하란에 있기 전 메소보다미아에 있을 때에 영광의 하나님이 그에게 보여"],["행 7:47","솔로몬이 그를 위하여 집을 지었느니라"]],"행 7:55-56":[["행 7:55","스데반이 성령이 충만하여 하늘을 우러러 주목하여 하나님의 영광과 및 예수께서 하나님 우편에 서신 것을 보고"],["행 7:56","말하되 보라 하늘이 열리고 인자가 하나님 우편에 서신 것을 보노라 한대"]],"행 8:2":[["행 8:2","경건한 사람들이 스데반을 장사하고 위하여 크게 울더라"]],"행 8:1, 4":[["행 8:1","사울이 그의 죽임 당함을 마땅히 여기더라 그 날에 예루살렘에 있는 교회에 큰 핍박이 나서 사도 외에는 다 유대와 사마리아 모든 땅으로 흩어지니라"],["행 8:4","그 흩어진 사람들이 두루 다니며 복음의 말씀을 전할쌔"]],"행 11:19":[["행 11:19","때에 스데반의 일로 일어난 환난을 인하여 흩어진 자들이 베니게와 구브로와 안디옥까지 이르러 도를 유대인에게만 전하는데"]],"행 22:20":[["행 22:20","또 주의 증인 스데반의 피를 흘릴 적에 내가 곁에 서서 찬성하고 그 죽이는 사람들의 옷을 지킨줄 저희도 아나이다"]],"막 3:17":[["막 3:17","또 세베대의 아들 야고보와 야고보의 형제 요한이니 이 둘에게는 보아너게 곧 우뢰의 아들이란 이름을 더하셨으며"]],"마 4:21":[["마 4:21","거기서 더 가시다가 다른 두 형제 곧 세베대의 아들 야고보와 그 형제 요한이 그 부친 세베대와 한가지로 배에서 그물 깁는 것을 보시고 부르시니"]],"막 1:19-20":[["막 1:19","조금 더 가시다가 세베대의 아들 야고보와 그 형제 요한을 보시니 저희도 배에 있어 그물을 깁는데"],["막 1:20","곧 부르시니 그 아비 세베대를 삯군들과 함께 배에 버려두고 예수를 따라가니라"]],"눅 5:10":[["눅 5:10","세베대의 아들로서 시몬의 동업자인 야고보와 요한도 놀랐음이라 예수께서 시몬에게 일러 가라사대 무서워 말라 이제 후로는 네가 사람을 취하리라 하시니"]],"갈 2:9":[["갈 2:9","또 내게 주신 은혜를 알므로 기둥 같이 여기는 야고보와 게바와 요한도 나와 바나바에게 교제의 악수를 하였으니 이는 우리는 이방인에게로, 저희는 할례자에게로 가게 하려 함이라"]],"마 20:20":[["마 20:20","그 때에 세베대의 아들의 어미가 그 아들들을 데리고 예수께 와서 절하며 무엇을 구하니"]],"막 3:14, 17":[["막 3:14","이에 열 둘을 세우셨으니 이는 자기와 함께 있게 하시고 또 보내사 전도도 하며"],["막 3:17","또 세베대의 아들 야고보와 야고보의 형제 요한이니 이 둘에게는 보아너게 곧 우뢰의 아들이란 이름을 더하셨으며"]],"막 5:37; 9:2":[["막 5:37","베드로와 야고보와 야고보의 형제 요한 외에 아무도 따라옴을 허치 아니하시고"],["막 9:2","엿새 후에 예수께서 베드로와 야고보와 요한을 데리시고 따로 높은 산에 올라가셨더니 저희 앞에서 변형되사"]],"눅 9:54-55":[["눅 9:54","제자 야고보와 요한이 이를 보고 가로되 주여 우리가 불을 명하여 하늘로 좇아 내려 저희를 멸하라 하기를 원하시나이까"],["눅 9:55","예수께서 돌아보시며 꾸짖으시고"]],"마 20:20-21":[["마 20:20","그 때에 세베대의 아들의 어미가 그 아들들을 데리고 예수께 와서 절하며 무엇을 구하니"],["마 20:21","예수께서 가라사대 무엇을 원하느뇨 가로되 이 나의 두 아들을 주의 나라에서 하나는 주의 우편에, 하나는 주의 좌편에 앉게 명하소서"]],"눅 22:8":[["눅 22:8","예수께서 베드로와 요한을 보내시며 가라사대 가서 우리를 위하여 유월절을 예비하여 우리로 먹게 하라"]],"요 19:26-27":[["요 19:26","예수께서 그 모친과 사랑하시는 제자가 곁에 섰는 것을 보시고 그 모친께 말씀하시되 여자여 보소서 아들이니이다 하시고"],["요 19:27","또 그 제자에게 이르시되 보라 네 어머니라 하신대 그 때부터 그 제자가 자기 집에 모시니라"]],"요 20:2-4":[["요 20:2","시몬 베드로와 예수의 사랑하시던 그 다른 제자에게 달려가서 말하되 사람이 주를 무덤에서 가져다가 어디 두었는지 우리가 알지 못하겠다 하니"],["요 20:3","베드로와 그 다른 제자가 나가서 무덤으로 갈쌔"],["요 20:4","둘이 같이 달음질하더니 그 다른 제자가 베드로보다 더 빨리 달아나서 먼저 무덤에 이르러"]],"행 3:1; 4:13":[["행 3:1","제 구시 기도 시간에 베드로와 요한이 성전에 올라갈쌔"],["행 4:13","저희가 베드로와 요한이 기탄없이 말함을 보고 그 본래 학문 없는 범인으로 알았다가 이상히 여기며 또 그 전에 예수와 함께 있던 줄도 알고"]],"행 8:14-17":[["행 8:14","예루살렘에 있는 사도들이 사마리아도 하나님의 말씀을 받았다 함을 듣고 베드로와 요한을 보내매"],["행 8:15","그들이 내려가서 저희를 위하여 성령 받기를 기도하니"],["행 8:16","이는 아직 한 사람에게도 성령 내리신 일이 없고 오직 주 예수의 이름으로 세례만 받을 뿐이러라"],["행 8:17","이에 두 사도가 저희에게 안수하매 성령을 받는지라"]],"눅 21:20":[["눅 21:20","너희가 예루살렘이 군대들에게 에워싸이는 것을 보거든 그 멸망이 가까운 줄을 알라"]],"창 12:1-3":[["창 12:1","여호와께서 아브람에게 이르시되 너는 너의 본토 친척 아비 집을 떠나 내가 네게 지시할 땅으로 가라"],["창 12:2","내가 너로 큰 민족을 이루고 네게 복을 주어 네 이름을 창대케 하리니 너는 복의 근원이 될찌라"],["창 12:3","너를 축복하는 자에게는 내가 복을 내리고 너를 저주하는 자에게는 내가 저주하리니 땅의 모든 족속이 너를 인하여 복을 얻을 것이니라 하신지라"]],"창 15:6":[["창 15:6","아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고"]],"히 11:8":[["히 11:8","믿음으로 아브라함은 부르심을 받았을 때에 순종하여 장래 기업으로 받을 땅에 나갈쌔 갈 바를 알지 못하고 나갔으며"]],"출 3:14":[["출 3:14","하나님이 모세에게 이르시되 나는 스스로 있는 자니라 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라"]],"신 34:10":[["신 34:10","그 후에는 이스라엘에 모세와 같은 선지자가 일어나지 못하였나니 모세는 여호와께서 대면하여 아시던 자요"]],"삼상 16:7":[["삼상 16:7","여호와께서 사무엘에게 이르시되 그 용모와 신장을 보지 말라 내가 이미 그를 버렸노라 나의 보는 것은 사람과 같지 아니하니 사람은 외모를 보거니와 나 여호와는 중심을 보느니라"]],"삼상 17:45":[["삼상 17:45","다윗이 블레셋 사람에게 이르되 너는 칼과 창과 단창으로 내게 오거니와 나는 만군의 여호와의 이름 곧 네가 모욕하는 이스라엘 군대의 하나님의 이름으로 네게 가노라"]],"시 23:1":[["시 23:1","여호와는 나의 목자시니 내가 부족함이 없으리로다"]],"왕상 16:30":[["왕상 16:30","오므리의 아들 아합이 그 전의 모든 사람보다 여호와 보시기에 악을 더욱 행하여"]],"왕상 18:21":[["왕상 18:21","엘리야가 모든 백성에게 가까이 나아가 이르되 너희가 어느때까지 두 사이에서 머뭇머뭇 하려느냐 여호와가 만일 하나님이면 그를 좇고 바알이 만일 하나님이면 그를 좇을찌니라 하니 백성이 한 말도 대답지 아니하는지라"]],"왕하 9:20":[["왕하 9:20","파숫군이 또 고하여 가로되 저도 저희에게까지 갔으나 돌아오지 아니하고 그 병거 모는 것이 님시의 손자 예후의 모는 것 같이 미치게 모나이다"]],"왕하 10:28-29":[["왕하 10:28","예후가 이와 같이 이스라엘 중에서 바알을 멸하였으나"],["왕하 10:29","이스라엘로 범죄케 한 느밧의 아들 여로보암의 죄 곧 벧엘과 단에 있는 금송아지를 섬기는 죄에서는 떠나지 아니하였더라"]],"사 6:8":[["사 6:8","내가 또 주의 목소리를 들은즉 이르시되 내가 누구를 보내며 누가 우리를 위하여 갈꼬 그 때에 내가 가로되 내가 여기 있나이다 나를 보내소서"]],"사 7:14":[["사 7:14","그러므로 주께서 친히 징조로 너희에게 주실 것이라 보라 처녀가 잉태하여 아들을 낳을 것이요 그 이름을 임마누엘이라 하리라"]],"사 40:8":[["사 40:8","풀은 마르고 꽃은 시드나 우리 하나님의 말씀은 영영히 서리라 하라"]],"왕하 18:5":[["왕하 18:5","히스기야가 이스라엘 하나님 여호와를 의지하였는데 그의 전후 유다 여러 왕 중에 그러한 자가 없었으니"]],"왕하 19:19":[["왕하 19:19","우리 하나님 여호와여 원컨대 이제 우리를 그 손에서 구원하옵소서 그리하시면 천하 만국이 주 여호와는 홀로 하나님이신줄 알리이다 하니라"]],"왕하 20:5":[["왕하 20:5","너는 돌아가서 내 백성의 주권자 히스기야에게 이르기를 왕의 조상 다윗의 하나님 여호와의 말씀이 내가 네 기도를 들었고 네 눈물을 보았노라 내가 너를 낫게 하리니 네가 삼일만에 여호와의 전에 올라가겠고"]],"왕하 18:19-20":[["왕하 18:19","랍사게가 저희에게 이르되 너희는 히스기야에게 고하라 대왕 앗수르 왕의 말씀이 너의 의뢰하는 이 의뢰가 무엇이냐"],["왕하 18:20","네가 싸울만한 계교와 용력이 있다고 한다마는 이는 입에 붙은 말 뿐이라 네가 이제 누구를 의뢰하고 나를 반역하였느냐"]],"왕하 19:35-37":[["왕하 19:35","이 밤에 여호와의 사자가 나와서 앗수르 진에서 군사 십 팔만 오천을 친지라 아침에 일찌기 일어나 보니 다 송장이 되었더라"],["왕하 19:36","앗수르 왕 산헤립이 떠나 돌아가서 니느웨에 거하더니"],["왕하 19:37","그 신 니스록의 묘에 경배할 때에 아드람멜렉과 사레셀이 저를 칼로 쳐 죽이고 아라랏 땅으로 도망하매 그 아들 에살핫돈이 대신하여 왕이 되니라"]],"왕하 24:12":[["왕하 24:12","유다 왕 여호야긴이 그 모친과 신복과 방백들과 내시들과 함께 바벨론 왕에게 나아가매 왕이 잡으니 때는 바벨론 왕 팔년이라"]],"왕하 25:28-29":[["왕하 25:28","선히 말하고 그 위를 바벨론에 저와 함께 있는 모든 왕의 위보다 높이고"],["왕하 25:29","그 죄수의 의복을 바꾸게 하고 그 일평생에 항상 왕의 앞에서 먹게 하였고"]],"렘 22:24":[["렘 22:24","나 여호와가 말하노라 나의 삶으로 맹세하노니 유다 왕 여호야김의 아들 너 고니야가 나의 오른손의 인장반지라 할찌라도 내가 빼어"]],"단 4:37":[["단 4:37","그러므로 지금 나 느부갓네살이 하늘의 왕을 찬양하며 칭송하며 존경하노니 그의 일이 다 진실하고 그의 행하심이 의로우시므로 무릇 교만하게 행하는 자를 그가 능히 낮추심이니라"]],"사 44:28":[["사 44:28","고레스에 대하여는 이르기를 그는 나의 목자라 나의 모든 기쁨을 성취하리라 하며 예루살렘에 대하여는 이르기를 중건되리라 하며 성전에 대하여는 이르기를 네 기초가 세움이 되리라 하는 자니라"]],"사 45:1":[["사 45:1","나 여호와는 나의 기름 받은 고레스의 오른손을 잡고 열국으로 그 앞에 항복하게 하며 열왕의 허리를 풀며 성 문을 그 앞에 열어서 닫지 못하게 하리라 내가 고레스에게 이르기를"]],"대하 36:23":[["대하 36:23","바사 왕 고레스는 말하노니 하늘의 신 여호와께서 세상 만국으로 내게 주셨고 나를 명하여 유다 예루살렘에 전을 건축하라 하셨나니 너희 중에 무릇 그 백성 된 자는 다 올라갈찌어다 너희 하나님 여호와께서 함께하시기를 원하노라 하였더라"]],"막 1:15":[["막 1:15","가라사대 때가 찼고 하나님 나라가 가까왔으니 회개하고 복음을 믿으라 하시더라"]],"마 5:3":[["마 5:3","심령이 가난한 자는 복이 있나니 천국이 저희 것임이요"]],"요 3:16":[["요 3:16","하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 저를 믿는 자마다 멸망치 않고 영생을 얻게 하려 하심이니라"]],"요 14:6":[["요 14:6","예수께서 가라사대 내가 곧 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라"]],"요 19:22":[["요 19:22","빌라도가 대답하되 나의 쓸 것을 썼다 하니라"]],"마 26:63":[["마 26:63","예수께서 잠잠하시거늘 대제사장이 가로되 내가 너로 살아 계신 하나님께 맹세하게 하노니 네가 하나님의 아들 그리스도인지 우리에게 말하라"]],"행 9:4-5":[["행 9:4","땅에 엎드러져 들으매 소리 있어 가라사대 사울아 사울아 네가 어찌하여 나를 핍박하느냐 하시거늘"],["행 9:5","대답하되 주여 뉘시오니이까 가라사대 나는 네가 핍박하는 예수라"]],"롬 1:16":[["롬 1:16","내가 복음을 부끄러워하지 아니하노니 이 복음은 모든 믿는 자에게 구원을 주시는 하나님의 능력이 됨이라 첫째는 유대인에게요 또한 헬라인에게로다"]],"갈 2:20":[["갈 2:20","내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 산 것이 아니요 오직 내 안에 그리스도께서 사신 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 몸을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라"]],"딤후 4:7":[["딤후 4:7","내가 선한 싸움을 싸우고 나의 달려갈 길을 마치고 믿음을 지켰으니"]],"창 22:7-8":[["창 22:7","이삭이 그 아비 아브라함에게 말하여 가로되 내 아버지여 하니 그가 가로되 내 아들아 내가 여기 있노라 이삭이 가로되 불과 나무는 있거니와 번제할 어린 양은 어디 있나이까"],["창 22:8","아브라함이 가로되 아들아 번제할 어린 양은 하나님이 자기를 위하여 친히 준비하시리라 하고 두 사람이 함께 나아가서"]],"창 26:24":[["창 26:24","그 밤에 여호와께서 그에게 나타나 가라사대 나는 네 아비 아브라함의 하나님이니 두려워 말라 내 종 아브라함을 위하여 내가 너와 함께 있어 네게 복을 주어 네 자손으로 번성케 하리라 하신지라"]],"히 11:20":[["히 11:20","믿음으로 이삭은 장차 오는 일에 대하여 야곱과 에서에게 축복하였으며"]],"창 28:16-17":[["창 28:16","야곱이 잠이 깨어 가로되 여호와께서 과연 여기 계시거늘 내가 알지 못하였도다"],["창 28:17","이에 두려워하여 가로되 두렵도다 이곳이여 다른 것이 아니라 이는 하나님의 전이요 이는 하늘의 문이로다 하고"]],"창 47:9":[["창 47:9","야곱이 바로에게 고하되 내 나그네 길의 세월이 일백 삼십년이니이다 나의 연세가 얼마 못되니 우리 조상의 나그네 길의 세월에 미치지 못하나 험악한 세월을 보내었나이다 하고"]],"창 39:9":[["창 39:9","이 집에는 나보다 큰이가 없으며 주인이 아무 것도 내게 금하지 아니하였어도 금한 것은 당신뿐이니 당신은 자기 아내임이라 그런즉 내가 어찌 이 큰 악을 행하여 하나님께 득죄하리이까"]],"창 45:5":[["창 45:5","당신들이 나를 이곳에 팔았으므로 근심하지 마소서 한탄하지 마소서 하나님이 생명을 구원하시려고 나를 당신들 앞서 보내셨나이다"]],"창 50:20":[["창 50:20","당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 만민의 생명을 구원하게 하시려 하셨나니"]],"출 4:14":[["출 4:14","여호와께서 모세를 향하여 노를 발하시고 가라사대 레위 사람 네 형 아론이 있지 아니하뇨 그의 말 잘함을 내가 아노라 그가 너를 만나러 나오나니 그가 너를 볼 때에 마음에 기뻐할 것이라"]],"민 6:24-26":[["민 6:24","여호와는 네게 복을 주시고 너를 지키시기를 원하며"],["민 6:25","여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며"],["민 6:26","여호와는 그 얼굴을 네게로 향하여 드사 평강 주시기를 원하노라 할찌니라 하라"]],"시 133:2":[["시 133:2","머리에 있는 보배로운 기름이 수염 곧 아론의 수염에 흘러서 그 옷깃까지 내림 같고"]],"수 1:9":[["수 1:9","내가 네게 명한 것이 아니냐 마음을 강하게 하고 담대히 하라 두려워 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라 하시니라"]],"민 14:9":[["민 14:9","오직 여호와를 거역하지 말라 또 그 땅 백성을 두려워하지 말라 그들은 우리 밥이라 그들의 보호자는 그들에게서 떠났고 여호와는 우리와 함께 하시느니라 그들을 두려워 말라 하나"]],"수 24:15":[["수 24:15","만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 열조가 강 저편에서 섬기던 신이든지 혹 너희의 거하는 땅 아모리 사람의 신이든지 너희 섬길 자를 오늘날 택하라 오직 나와 내 집은 여호와를 섬기겠노라"]],"삿 5:7":[["삿 5:7","이스라엘에 관원이 그치고 그쳤더니 나 드보라가 일어났고 내가 일어나서 이스라엘의 어미가 되었도다"]],"삿 6:12":[["삿 6:12","여호와의 사자가 기드온에게 나타나 이르되 큰 용사여 여호와께서 너와 함께 계시도다"]],"삿 7:2":[["삿 7:2","여호와께서 기드온에게 이르시되 너를 좇은 백성이 너무 많은즉 내가 그들의 손에 미디안 사람을 붙이지 아니하리니 이는 이스라엘이 나를 거스려 자긍하기를 내 손이 나를 구원하였다 할까 함이니라"]],"삿 8:23":[["삿 8:23","기드온이 그들에게 이르되 내가 너희를 다스리지 아니하겠고 나의 아들도 너희를 다스리지 아니할 것이요 여호와께서 너희를 다스리시리라"]],"룻 1:16-17":[["룻 1:16","룻이 가로되 나로 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 유숙하시는 곳에서 나도 유숙하겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니"],["룻 1:17","어머니께서 죽으시는 곳에서 나도 죽어 거기 장사될 것이라 만일 내가 죽는 일 외에 어머니와 떠나면 여호와께서 내게 벌을 내리시고 더 내리시기를 원하나이다"]],"룻 2:12":[["룻 2:12","여호와께서 네 행한 일을 보응하시기를 원하며 이스라엘의 하나님 여호와께서 그 날개 아래 보호를 받으러 온 네게 온전한 상 주시기를 원하노라"]],"삼상 7:12":[["삼상 7:12","사무엘이 돌을 취하여 미스바와 센 사이에 세워 가로되 여호와께서 여기까지 우리를 도우셨다 하고 그 이름을 에벤에셀이라 하니라"]],"삼상 18:7":[["삼상 18:7","여인들이 뛰놀며 창화하여 가로되 사울의 죽인 자는 천천이요 다윗은 만만이로다 한지라"]],"삼하 1:23":[["삼하 1:23","사울과 요나단이 생전에 사랑스럽고 아름다운 자러니 죽을 때에도 서로 떠나지 아니하였도다 저희는 독수리보다 빠르고 사자보다 강하였도다"]],"왕상 3:9":[["왕상 3:9","누가 주의 이 많은 백성을 재판할 수 있사오리이까 지혜로운 마음을 종에게 주사 주의 백성을 재판하여 선악을 분별하게 하옵소서"]],"왕상 8:27":[["왕상 8:27","하나님이 참으로 땅에 거하시리이까 하늘과 하늘들의 하늘이라도 주를 용납지 못하겠거든 하물며 내가 건축한 이 전이오리이까"]],"잠 1:7":[["잠 1:7","여호와를 경외하는 것이 지식의 근본이어늘 미련한 자는 지혜와 훈계를 멸시하느니라"]],"왕상 12:14":[["왕상 12:14","소년의 가르침을 좇아 저희에게 고하여 가로되 내 부친은 너희의 멍에를 무겁게 하였으나 나는 너희의 멍에를 더욱 무겁게 할찌라 내 부친은 채찍으로 너희를 징치하였으나 나는 전갈로 너희를 징치하리라 하니라"]],"왕상 12:16":[["왕상 12:16","온 이스라엘이 자기들의 말을 왕이 듣지 아니함을 보고 왕에게 대답하여 가로되 우리가 다윗과 무슨 관계가 있느뇨 이새의 아들에게서 업이 없도다 이스라엘아 너희의 장막으로 돌아가라 다윗이여 이제 너는 네 집이나 돌아보라 하고 이스라엘이 그 장막으로 돌아가니라"]],"왕상 11:31":[["왕상 11:31","여로보암에게 이르되 너는 열 조각을 취하라 이스라엘 하나님 여호와의 말씀이 내가 이 나라를 솔로몬의 손에서 찢어 빼앗아 열 지파를 네게 주고"]],"왕상 12:28":[["왕상 12:28","이에 계획하고 두 금송아지를 만들고 무리에게 말하기를 너희가 다시는 예루살렘에 올라갈 것이 없도다 이스라엘아 이는 너희를 애굽 땅에서 인도하여 올린 너희 신이라 하고"]],"왕상 13:34":[["왕상 13:34","이 일이 여로보암 집에 죄가 되어 그 집이 지면에서 끊어져 멸망케 되니라"]],"대하 12:2":[["대하 12:2","저희가 여호와께 범죄하였으므로 르호보암왕 오년에 애굽 왕 시삭이 예루살렘을 치러 올라오니"]],"대하 12:8":[["대하 12:8","그러나 저희가 시삭의 종이 되어 나를 섬기는 것과 열국을 섬기는 것이 어떠한지 알게 되리라 하셨더라"]],"미 6:16":[["미 6:16","너희가 오므리의 율례와 아합 집의 모든 행위를 지키고 그들의 꾀를 좇으니 이는 나로 너희를 황무케 하며 그 거민으로 사람의 치솟거리를 만들게 하려 함이라 너희가 내 백성의 수욕을 담당하리라"]],"왕상 19:12":[["왕상 19:12","또 지진 후에 불이 있으나 불 가운데도 여호와께서 계시지 아니하더니 불 후에 세미한 소리가 있는지라"]],"말 4:5":[["말 4:5","보라 여호와의 크고 두려운 날이 이르기 전에 내가 선지 엘리야를 너희에게 보내리니"]],"약 5:17":[["약 5:17","엘리야는 우리와 성정이 같은 사람이로되 저가 비 오지 않기를 간절히 기도한즉 삼년 육개월 동안 땅에 비가 아니 오고"]],"욘 2:9":[["욘 2:9","나는 감사하는 목소리로 주께 제사를 드리며 나의 서원을 주께 갚겠나이다 구원은 여호와께로서 말미암나이다 하니라"]],"욘 4:11":[["욘 4:11","하물며 이 큰 성읍, 니느웨에는 좌우를 분변치 못하는 자가 십 이만 여명이요 육축도 많이 있나니 내가 아끼는 것이 어찌 합당치 아니하냐"]],"마 12:40":[["마 12:40","요나가 밤낮 사흘을 큰 물고기 뱃속에 있었던것 같이 인자도 밤낮 사흘을 땅속에 있으리라"]],"대하 33:12-13":[["대하 33:12","저가 환난을 당하여 그 하나님 여호와께 간구하고 그 열조의 하나님 앞에 크게 겸비하여"],["대하 33:13","기도한고로 하나님이 그 기도를 받으시며 그 간구를 들으시사 저로 예루살렘에 돌아와서 다시 왕위에 거하게 하시매 므낫세가 그제야 여호와께서 하나님이신 줄을 알았더라"]],"렘 15:4":[["렘 15:4","유다 왕 히스기야의 아들 므낫세가 예루살렘에 행한 바를 인하여 내가 그들을 세계 열방 중에 흩으리라"]],"왕하 23:25":[["왕하 23:25","요시야와 같이 마음을 다하며 성품을 다하며 힘을 다하여 여호와를 향하여 모세의 모든 율법을 온전히 준행한 임금은 요시야 전에도 없었고 후에도 그와 같은 자가 없었더라"]],"왕하 22:19":[["왕하 22:19","내가 이곳과 그 거민에게 대하여 빈 터가 되고 저주가 되리라 한 말을 네가 듣고 마음이 연하여 여호와 앞 곧 내 앞에서 겸비하여 옷을 찢고 통곡하였으므로 나도 네 말을 들었노라 여호와가 말하였느니라"]],"렘 22:15-16":[["렘 22:15","네가 백향목으로 집 짓기를 경쟁하므로 왕이 될 수 있겠느냐 네 아비가 먹으며 마시지 아니하였으며 공평과 의리를 행치 아니하였느냐 그 때에 그가 형통하였었느니라"],["렘 22:16","그는 가난한 자와 궁핍한 자를 신원하고 형통하였나니 이것이 나를 앎이 아니냐 여호와의 말이니라"]],"렘 9:1":[["렘 9:1","어찌하면 내 머리는 물이 되고 내 눈은 눈물 근원이 될꼬 그렇게 되면 살륙 당한 딸 내 백성을 위하여 주야로 곡읍하리로다"]],"렘 29:11":[["렘 29:11","나 여호와가 말하노라 너희를 향한 나의 생각은 내가 아나니 재앙이 아니라 곧 평안이요 너희 장래에 소망을 주려하는 생각이라"]],"렘 31:33":[["렘 31:33","나 여호와가 말하노라 그러나 그 날 후에 내가 이스라엘 집에 세울 언약은 이러하니 곧 내가 나의 법을 그들의 속에 두며 그 마음에 기록하여 나는 그들의 하나님이 되고 그들은 내 백성이 될 것이라"]],"단 1:8":[["단 1:8","다니엘은 뜻을 정하여 왕의 진미와 그의 마시는 포도주로 자기를 더럽히지 아니하리라 하고 자기를 더럽히지 않게 하기를 환관장에게 구하니"]],"단 12:3":[["단 12:3","지혜 있는 자는 궁창의 빛과 같이 빛날 것이요 많은 사람을 옳은데로 돌아오게 한 자는 별과 같이 영원토록 비취리라"]],"단 5:5":[["단 5:5","그 때에 사람의 손가락이 나타나서 왕궁 촛대 맞은편 분벽에 글자를 쓰는데 왕이 그 글자 쓰는 손가락을 본지라"]],"단 5:25-28":[["단 5:25","기록한 글자는 이것이니 곧 메네 메네 데겔 우바르신이라"],["단 5:26","그 뜻을 해석하건대 메네는 하나님이 이미 왕의 나라의 시대를 세어서 그것을 끝나게 하셨다 함이요"],["단 5:27","데겔은 왕이 저울에 달려서 부족함이 뵈었다 함이요"],["단 5:28","베레스는 왕의 나라가 나뉘어서 메대와 바사 사람에게 준바 되었다 함이니이다"]],"스 3:11":[["스 3:11","서로 찬송가를 화답하며 여호와께 감사하여 가로되 주는 지선하시므로 그 인자하심이 이스라엘에게 영원하시도다 하니 모든 백성이 여호와의 전 지대가 놓임을 보고 여호와를 찬송하며 큰 소리로 즐거이 부르며"]],"스 6:7":[["스 6:7","하나님의 전 역사를 막지 말고 유다 총독과 장로들로 하나님의 이 전을 본처에 건축하게 하라"]],"스 6:12":[["스 6:12","만일 열왕이나 백성이 이 조서를 변개하고 손을 들어 예루살렘 하나님의 전을 헐찐대 그곳에 이름을 두신 하나님이 저희를 멸하시기를 원하노라 나 다리오가 조서를 내렸노니 신속히 행할찌어다 하였더라"]],"에 5:3":[["에 5:3","왕이 이르되 왕후 에스더여 그대의 소원이 무엇이며 요구가 무엇이뇨 나라의 절반이라도 그대에게 주겠노라"]],"에 6:6":[["에 6:6","하만이 들어오거늘 왕이 묻되 왕이 존귀케 하기를 기뻐하는 사람에게 어떻게 하여야 하겠느뇨 하만이 심중에 이르되 왕이 존귀케 하기를 기뻐하시는 자는 나 외에 누구리요 하고"]],"에 4:14":[["에 4:14","이 때에 네가 만일 잠잠하여 말이 없으면 유다인은 다른데로 말미암아 놓임과 구원을 얻으려니와 너와 네 아비 집은 멸망하리라 네가 왕후의 위를 얻은 것이 이 때를 위함이 아닌지 누가 아느냐"]],"에 4:16":[["에 4:16","당신은 가서 수산에 있는 유다인을 다 모으고 나를 위하여 금식하되 밤낮 삼일을 먹지도 말고 마시지도 마소서 나도 나의 시녀로 더불어 이렇게 금식한 후에 규례를 어기고 왕에게 나아가리니 죽으면 죽으리이다"]],"스 7:6":[["스 7:6","이 에스라가 바벨론에서 올라왔으니 저는 이스라엘 하나님 여호와께서 주신바 모세의 율법에 익숙한 학사로서 그 하나님 여호와의 도우심을 입으므로 왕에게 구하는 것은 다 받는 자더니"]],"스 9:6":[["스 9:6","말하기를 나의 하나님이여 내가 부끄러워 낯이 뜨뜻하여 감히 나의 하나님을 향하여 얼굴을 들지 못하오니 이는 우리 죄악이 많아 정수리에 넘치고 우리 허물이 커서 하늘에 미침이니이다"]],"느 8:6":[["느 8:6","에스라가 광대하신 하나님 여호와를 송축하매 모든 백성이 손을 들고 아멘 아멘 응답하고 몸을 굽혀 얼굴을 땅에 대고 여호와께 경배하였느니라"]],"느 2:20":[["느 2:20","내가 대답하여 가로되 하늘의 하나님이 우리로 형통케 하시리니 그의 종 우리가 일어나 건축하려니와 오직 너희는 예루살렘에서 아무 기업도 없고 권리도 없고 명록도 없다 하였느니라"]],"느 6:3":[["느 6:3","내가 곧 저희에게 사자들을 보내어 이르기를 내가 이제 큰 역사를 하니 내려가지 못하겠노라 어찌하여 역사를 떠나 정지하게 하고 너희에게로 내려 가겠느냐 하매"]],"느 8:10":[["느 8:10","느헤미야가 또 이르기를 너희는 가서 살진 것을 먹고 단 것을 마시되 예비치 못한 자에게는 너희가 나누어 주라 이 날은 우리 주의 성일이니 근심하지 말라 여호와를 기뻐하는 것이 너희의 힘이니라 하고"]],"마 2:3":[["마 2:3","헤롯왕과 온 예루살렘이 듣고 소동한지라"]],"마 3:2":[["마 3:2","회개하라 천국이 가까왔느니라 하였으니"]],"요 3:30":[["요 3:30","그는 흥하여야 하겠고 나는 쇠하여야 하리라 하니라"]],"마 11:11":[["마 11:11","내가 진실로 너희에게 말하노니 여자가 낳은 자 중에 세례 요한보다 큰이가 일어남이 없도다 그러나 천국에서는 극히 작은 자라도 저보다 크니라"]],"마 16:18":[["마 16:18","또 내가 네게 이르노니 너는 베드로라 내가 이 반석 위에 내 교회를 세우리니 음부의 권세가 이기지 못하리라"]],"요 21:17":[["요 21:17","세번째 가라사대 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 주께서 세번째 네가 나를 사랑하느냐 하시므로 베드로가 근심하여 가로되 주여 모든 것을 아시오매 내가 주를 사랑하는 줄을 주께서 아시나이다 예수께서 가라사대 내 양을 먹이라"]],"행 3:6":[["행 3:6","베드로가 가로되 은과 금은 내게 없거니와 내게 있는 것으로 네게 주노니 곧 나사렛 예수 그리스도의 이름으로 걸으라 하고"]],"행 7:56":[["행 7:56","말하되 보라 하늘이 열리고 인자가 하나님 우편에 서신 것을 보노라 한대"]],"요 20:31":[["요 20:31","오직 이것을 기록함은 너희로 예수께서 하나님의 아들 그리스도이심을 믿게 하려 함이요 또 너희로 믿고 그 이름을 힘입어 생명을 얻게 하려 함이니라"]],"요일 4:8":[["요일 4:8","사랑하지 아니하는 자는 하나님을 알지 못하나니 이는 하나님은 사랑이심이라"]],"계 21:4":[["계 21:4","모든 눈물을 그 눈에서 씻기시매 다시 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라"]],"눅 19:43-44":[["눅 19:43","날이 이를찌라 네 원수들이 토성을 쌓고 너를 둘러 사면으로 가두고"],["눅 19:44","또 너와 및 그 가운데 있는 네 자식들을 땅에 메어치며 돌 하나도 돌 위에 남기지 아니하리니 이는 권고 받는 날을 네가 알지 못함을 인함이니라 하시니라"]],"마 24:2":[["마 24:2","대답하여 가라사대 너희가 이 모든 것을 보지 못하느냐 내가 진실로 너희에게 이르노니 돌 하나도 돌 위에 남지 않고 다 무너뜨리우리라"]]};
